window.__BOOK__={"meta": {"title_ru": "Маленький принц", "title_zh": "小王子", "author_ru": "Антуан де Сент-Экзюпери", "author_zh": "安托万·德·圣埃克苏佩里", "voice": "ru-RU-SvetlanaNeural (edge-tts)", "ipa_note": "宽式音位转写：标注辅音腭化/清浊同化/词末清化，不标重音、不做非重读元音弱化", "n_chapters": 28, "n_paras": 110, "n_sents": 1581}, "chapters": [{"id": "ch00", "title_ru": "Посвящение", "title_zh": "献词", "paras": [{"id": "ch00p00", "audio": true, "sents": [{"ru": "Леону Верту", "zh": "列翁·维尔特", "t": [100, 1226]}]}, {"id": "ch00p01", "audio": true, "sents": [{"ru": "Я прошу прощения у детей за то, что посвятил эту книжку взрослому человеку.", "zh": "请孩子们原谅我把这本书献给了这位大人。", "t": [100, 5738]}, {"ru": "Однако у меня есть веское оправдание.", "zh": "然而，我有充分的理由。", "t": [5738, 9288]}, {"ru": "Этот взрослый — мой лучший друг на свете.", "zh": "这位大人——我世间最挚友。", "t": [9288, 12800]}, {"ru": "Есть и другое оправдание — он все понимает, даже книжки, написанные для детей.", "zh": "他懂得一切，即便是对孩子写的书。", "t": [12800, 18800]}, {"ru": "У меня есть и третье оправдание — этот взрослый живет во Франции, где голодает и мерзнет.", "zh": "这位大人身处法国，忍饥受寒。", "t": [18800, 25038]}, {"ru": "Конечно же, его надо утешить.", "zh": "当然，他需要安慰。", "t": [25038, 28075]}, {"ru": "А если этих оправданий недостаточно, я охотно посвящу эту книжку ребенку, которым этот взрослый когда-то был.", "zh": "若这些理由尚不足够，我乐意将此书献给那位曾经是孩子的他。", "t": [28075, 35275]}, {"ru": "Ведь все взрослые когда-то были детьми, хотя мало кто из них помнит об этом.", "zh": "大人们曾经都是孩子，尽管很少有人记得这一点。", "t": [35275, 40388]}, {"ru": "Поэтому я исправляю это посвящение: Леону Верту, когда он был маленьким мальчиком", "zh": "因此，我将此献词修正：献给我的小男孩列翁·维尔特。", "t": [40388, 45613]}]}]}, {"id": "ch01", "title_ru": "Глава 1", "title_zh": "第 1 章", "paras": [{"id": "ch01p00", "audio": true, "sents": [{"ru": "Когда мне было шесть лет, я увидел однажды в книжке про тропические леса удивительный рисунок.", "zh": "六岁那一年，我在一本描写原始森林的书里看见一幅扣人心弦的图画。", "t": [100, 6475]}, {"ru": "Книжка называлась «Житейские истории».", "zh": "那本书的书名叫做“丛林奇遇记”。", "t": [6475, 10250]}, {"ru": "На рисунке был изображен удав, который глотал какого-то зверька.", "zh": "图中画的是正在吞吃野兽的蟒蛇。", "t": [10250, 15000]}, {"ru": "Вот как это примерно выглядело.", "zh": "下面是这幅画的复印件。", "t": [15000, 16887]}]}, {"id": "ch01p01", "audio": true, "sents": [{"ru": "В книге говорилось, что удавы глотают свою добычу целиком, не разжевывая.", "zh": "书中说：“蟒蛇囫囵吞下猎物，肚子撑得它不能动弹，要躺六个月才能把猎物消化掉。", "t": [100, 5825]}, {"ru": "А потом они не могут больше ползать и спят в течение шести месяцев, пока все не переварят.", "zh": "” 从此，我对丛林的种种奇事产生了无穷尽的遐想。", "t": [5825, 10874]}]}, {"id": "ch01p02", "audio": true, "sents": [{"ru": "В то время я часто мечтал о приключениях в джунглях, и поэтому тоже нарисовал цветным карандашом рисунок.", "zh": "我也用彩色铅笔绘下我的第一幅画。", "t": [100, 7012]}, {"ru": "Это был мой первый рисунок.", "zh": "我称它为一号画。", "t": [7012, 9700]}, {"ru": "Он был примерно таким.", "zh": "一号画如下： 我把我的杰作拿给大人看，还问他们，我的画是否吓坏了他们。", "t": [9700, 11200]}]}, {"id": "ch01p03", "audio": true, "sents": [{"ru": "Я показал мой шедевр взрослым и спросил у них, не страшно ли им.", "zh": "一号画如下： 我把我的杰作拿给大人看，还问他们，我的画是否吓坏了他们。", "t": [100, 5062]}, {"ru": "И они мне ответили — что может быть страшного в шляпе?", "zh": "他们回答我说：“一顶帽子有什么可怕的？", "t": [5062, 9038]}, {"ru": "Однако на моем рисунке была изображена не шляпа.", "zh": "” 我画的不是一顶帽子，而是一条正在消化大象的蟒蛇啊。", "t": [9038, 12850]}, {"ru": "Это был удав, который переваривал слона.", "zh": "” 我画的不是一顶帽子，而是一条正在消化大象的蟒蛇啊。", "t": [12850, 16450]}, {"ru": "Тогда для ясности я нарисовал, что было у удава внутри, чтобы взрослые могли это понять.", "zh": "我又画了一张画，画的是蟒蛇和它肚子里的大象，好让大人看懂我的画。", "t": [16450, 22575]}, {"ru": "Им ведь всегда приходится все растолковывать.", "zh": "他们总是需要我们给他们解释的。", "t": [22575, 26050]}, {"ru": "Мой второй рисунок был таким.", "zh": "他们总是需要我们给他们解释的。", "t": [26050, 27950]}]}, {"id": "ch01p04", "audio": true, "sents": [{"ru": "Но взрослые мне посоветовали не рисовать удавов, ни снаружи, ни изнутри, а заняться лучше географией, историей, арифметикой и правописанием.", "zh": "我的二号画如下： 大人们劝我，别画这些肚子没打开或打开了的蟒蛇了，把心思放到地理、历史、算术、语法上去吧。", "t": [100, 9738]}, {"ru": "Вот почему в шесть лет я перестал мечтать стать знаменитым художником.", "zh": "就这样，我在六岁这一年放弃了画家的光辉生涯。", "t": [9738, 14650]}, {"ru": "Я был разочарован полным провалом моих рисунков: первого и второго.", "zh": "一号画、二号画的失败令我垂头丧气。", "t": [14650, 19912]}, {"ru": "Взрослые ведь сами ничего не понимают, а детям трудно снова и снова все им растолковывать.", "zh": "大人们老是需要孩子们费尽唇舌，给他们再三解释，不然就一窍不通，真把我们累得够呛。", "t": [19912, 26062]}, {"ru": "Поэтому мне пришлось избрать другую профессию.", "zh": "我只好选择另一门职业。", "t": [26062, 29875]}, {"ru": "Я научился летать на самолетах.", "zh": "我学会了驾驶飞机，几乎跑遍了世界各地。", "t": [29875, 32912]}, {"ru": "И я облетел почти весь мир.", "zh": "我学会了驾驶飞机，几乎跑遍了世界各地。", "t": [32912, 35800]}, {"ru": "Так что знание географии мне помогло.", "zh": "地理确实帮了我的大忙。", "t": [35800, 38975]}, {"ru": "Я научился с первого взгляда отличать Китай от Аризоны.", "zh": "在空中，我一眼就能认出中国和亚利桑那 [1] ，这样的本领很管用——如果夜航时迷了路。", "t": [38975, 43362]}, {"ru": "А это полезно, когда заплутаешь в ночи.", "zh": "在空中，我一眼就能认出中国和亚利桑那 [1] ，这样的本领很管用——如果夜航时迷了路。", "t": [43362, 46888]}, {"ru": "В течение жизни у меня была целая куча встреч с кучей серьезных людей.", "zh": "在空中，我一眼就能认出中国和亚利桑那 [1] ，这样的本领很管用——如果夜航时迷了路。", "t": [46888, 51900]}, {"ru": "Я часто жил среди взрослых.", "zh": "我一生与许多重要人物打过交道，我在大人当中生活了很长时间，我仔细地观察过他们，然而我对他们的看法没有多大的改善。", "t": [51900, 54700]}, {"ru": "Я их нередко разглядывал вблизи, хотя это и не улучшило моего мнения о них.", "zh": "我一生与许多重要人物打过交道，我在大人当中生活了很长时间，我仔细地观察过他们，然而我对他们的看法没有多大的改善。", "t": [54700, 60238]}, {"ru": "Когда я встречал взрослого, который казался мне более понятливым, я проделывал над ним опыт.", "zh": "我始终保留着我的一号画。", "t": [60238, 66250]}, {"ru": "Я показывал ему свой первый рисунок, который всегда хранил при себе.", "zh": "遇到一个我认为略为懂事的大人，我就用这幅画做试验，看他是否真的懂事，但他们总是这样回答我：“这是一顶帽子。", "t": [66250, 71138]}, {"ru": "Мне хотелось узнать, насколько этот взрослый понятлив.", "zh": "遇到一个我认为略为懂事的大人，我就用这幅画做试验，看他是否真的懂事，但他们总是这样回答我：“这是一顶帽子。", "t": [71138, 75438]}, {"ru": "Однако он мне всегда отвечал, что это шляпа.", "zh": "”听了这样的话，我就不再与他们谈蟒蛇、原始森林、星星了。", "t": [75438, 79150]}, {"ru": "И поэтому я не рассказывал ему ни об удавах, ни о тропических лесах, ни о звездах.", "zh": "”听了这样的话，我就不再与他们谈蟒蛇、原始森林、星星了。", "t": [79150, 84938]}, {"ru": "Я к нему приноравливался.", "zh": "我谈他们能理解的事情，例如桥牌啦，高尔夫球啦，政治啦，领带啦。", "t": [84938, 87538]}, {"ru": "Я говорил с ним о бридже, о гольфе, о политике и о галстуках.", "zh": "我谈他们能理解的事情，例如桥牌啦，高尔夫球啦，政治啦，领带啦。", "t": [87538, 92688]}, {"ru": "И этот взрослый был вполне доволен знакомству с таким здравомыслящим человеком, как я.", "zh": "大人们便很满意，以为他们认识了一个通情达理、善解人意的人。", "t": [92688, 97476]}]}]}, {"id": "ch02", "title_ru": "Глава 2", "title_zh": "第 2 章", "paras": [{"id": "ch02p00", "audio": true, "sents": [{"ru": "Потом я жил один, и мне не с кем было поговорить по-настоящему.", "zh": "从此我孤独地生活着，没有一个可以推心置腹的朋友。", "t": [100, 4675]}, {"ru": "Так продолжалось до тех пор, пока шесть лет назад я не попал в аварию над пустыней Сахарой.", "zh": "这种状况一直延续至六年前。", "t": [4675, 10550]}, {"ru": "Что-то сломалось в моторе моего самолета.", "zh": "六年前，我的飞机出了故障，发动机里的某个部件被撞坏了，我被迫在撒哈拉沙漠降落。", "t": [10550, 13925]}, {"ru": "И поскольку со мной не было ни механика, ни пассажиров, я решил самостоятельно справиться с этой трудной поломкой.", "zh": "身边没有机械师，没有一个乘客，我只好勉为其难，自己动手，试着修理部件。", "t": [13925, 20912]}, {"ru": "Воды у меня было немного — всего на восемь дней.", "zh": "我带的水仅够喝一个星期，能否修好飞机，关系到我的生死存亡了。", "t": [20912, 24750]}, {"ru": "Вечером первого дня я заснул на песке в тысяче миль от человеческого жилья.", "zh": "第一夜，我在远离人烟、千里之遥的沙漠上睡觉。", "t": [24750, 29838]}, {"ru": "Я был более одинок, чем потерпевший кораблекрушение человек на плоту посреди океана.", "zh": "比起那些乘着木排，在茫茫大洋中挣扎漂浮的遇险者，我更显得孤独无助。", "t": [29838, 36025]}, {"ru": "Поэтому вы можете представить мое удивление, когда на рассвете меня разбудил чей-то тоненький голосок.", "zh": "朝霞初露的时候，一个细细的奇妙的声音把我唤醒。", "t": [36025, 42638]}, {"ru": "Он сказал: — Пожалуйста… нарисуй мне барашка!", "zh": "你不难想像我当时有多惊讶了。", "t": [42638, 46512]}, {"ru": "— Что?", "zh": "这细细的奇妙的声音说： “劳驾……请你给我画一只绵羊吧！", "t": [46512, 47975]}, {"ru": "— Нарисуй мне барашка!", "zh": "这细细的奇妙的声音说： “劳驾……请你给我画一只绵羊吧！", "t": [47975, 50325]}, {"ru": "Я вскочил на ноги, как будто рядом сверкнула молния.", "zh": "” “你说什么？", "t": [50325, 54712]}, {"ru": "Я изо всех сил протер глаза и осмотрелся вокруг.", "zh": "” “给我画一只绵羊……” 我像遭了雷击，一跃而起。", "t": [54712, 58788]}, {"ru": "И я увидел совершенно необыкновенного малыша, который с серьезным видом меня разглядывал.", "zh": "我使劲揉我的眼睛，仔细地看了看，只见一个很奇特的小小的人儿，他正在那儿注视我呢。", "t": [58788, 64750]}, {"ru": "Вот самое лучшее его изображение, которое мне удалось сделать позже.", "zh": "我使劲揉我的眼睛，仔细地看了看，只见一个很奇特的小小的人儿，他正在那儿注视我呢。", "t": [64750, 69975]}, {"ru": "Хотя на моем рисунке он не так хорош, как на самом деле.", "zh": "下面就是以后我给他画的最为成功的一幅肖像画。", "t": [69975, 74588]}, {"ru": "Но это не моя вина.", "zh": "当然，它没有他本人可爱俊美，这可不能怪我，该怪大人，是他们在我六岁那年葬送了我的画家生涯。", "t": [74588, 76900]}, {"ru": "Ведь когда мне было шесть лет, взрослые отбили у меня охоту стать художником, и я не научился рисовать ничего кроме удавов снаружи и изнутри.", "zh": "当然，它没有他本人可爱俊美，这可不能怪我，该怪大人，是他们在我六岁那年葬送了我的画家生涯。", "t": [76900, 84813]}]}, {"id": "ch02p01", "audio": true, "sents": [{"ru": "Итак, я таращился во все глаза на это удивительное явление.", "zh": "我大吃一惊，眼睛瞪得溜圆，看着这位突然出现的人儿。", "t": [100, 4962]}, {"ru": "Не забывайте — ведь я находился в тысяче миль от любого жилья.", "zh": "我大吃一惊，眼睛瞪得溜圆，看着这位突然出现的人儿。", "t": [4962, 9362]}, {"ru": "А малыш не казался мне ни заблудившимся, ни испуганным, ни умирающим от голода или жажды.", "zh": "你们可别忘了，这儿是远离人烟、千里之遥的地方啊。", "t": [9362, 15412]}, {"ru": "Он был совершенно не похож на ребенка, потерявшегося посреди пустыни за сотни миль от человеческого жилья.", "zh": "他一点不像迷失于沙漠中的孩子，不像远离人烟、千里之遥的孩子。", "t": [15412, 22000]}, {"ru": "Когда я снова обрел дар речи, я спросил его: — Но… что ты тут делаешь?", "zh": "我终于能够张口说话了，我问他： “……你在这儿干什么？", "t": [22000, 27275]}, {"ru": "А он в ответ тихо и серьезно повторил: — Пожалуйста… нарисуй мне барашка!", "zh": "我终于能够张口说话了，我问他： “……你在这儿干什么？", "t": [27275, 32600]}, {"ru": "Поскольку все случившееся казалось мне неразрешимой и впечатляющей тайной, я не осмелился отказать.", "zh": "” 他不慌不忙地重述他的要求，像说一件很严肃的事情： “请你给我画一只绵羊……” 当神秘的东西使得你心惊肉跳的时候，你不敢不听他的命令。", "t": [32600, 39288]}, {"ru": "И как бы ни казалось мне это неуместным в тысяче миль от человеческого жилья, на границе жизни и смерти, я вынул из кармана листок бумаги и авторучку.", "zh": "虽然，身处远离人烟的荒漠，面临死亡的威胁，叫人画画的要求又未免荒堂，我还是从口袋里掏出一张纸和一枝钢笔。", "t": [39288, 48200]}, {"ru": "Однако я вспомнил, что в основном изучал географию, историю, арифметику и правописание.", "zh": "我忽然记起，除了钻研地理、历史、算术、语法，我没有画过画，便没好气地冲小人儿说，我不会画画。", "t": [48200, 54925]}, {"ru": "Поэтому с несколько расстроенным видом я сказал малышу, что не умею рисовать.", "zh": "我忽然记起，除了钻研地理、历史、算术、语法，我没有画过画，便没好气地冲小人儿说，我不会画画。", "t": [54925, 60125]}, {"ru": "Но он мне ответил: — Неважно.", "zh": "他说：“不要紧，给我画一只绵羊吧。", "t": [60125, 63050]}, {"ru": "Нарисуй барашка.", "zh": "他说：“不要紧，给我画一只绵羊吧。", "t": [63050, 65262]}, {"ru": "Поскольку я никогда не изображал барашков, я повторил для него одну из двух картинок, которые умел рисовать, — удава снаружи.", "zh": "” 我从没画过绵羊，只画过那两张画。", "t": [65262, 73162]}, {"ru": "И был чрезвычайно удивлен, когда малыш мне ответил: — Нет, нет!", "zh": "我吓了一跳，我听见小人儿说： “不！", "t": [73162, 78200]}, {"ru": "Мне не нужен слон в удаве.", "zh": "我不要象在蟒蛇的肚子里。", "t": [78200, 80825]}, {"ru": "Удав слишком опасен, а слон слишком велик.", "zh": "蟒蛇太可怕，象太占地方。", "t": [80825, 84688]}, {"ru": "А у меня дома все очень маленькое.", "zh": "我的家地方不大。", "t": [84688, 87925]}, {"ru": "Мне нужен барашек.", "zh": "我要绵羊，给我画一只绵羊吧。", "t": [87925, 90262]}, {"ru": "Нарисуй мне барашка.", "zh": "” 我便画了一头羊。", "t": [90262, 92625]}, {"ru": "Тогда я нарисовал его.", "zh": "” 我便画了一头羊。", "t": [92625, 94188]}]}, {"id": "ch02p02", "audio": true, "sents": [{"ru": "Он посмотрел на него внимательно и сказал: — Нет.", "zh": "他仔细看看，然后说： “不好！", "t": [100, 3875]}, {"ru": "Этот слишком хилый.", "zh": "这是一头患了重病的羊。", "t": [3875, 6275]}, {"ru": "Нарисуй другого.", "zh": "给我画另一头吧。", "t": [6275, 8400]}, {"ru": "И я нарисовал второго барашка.", "zh": "” 我又画了一只羊。", "t": [8400, 10450]}]}, {"id": "ch02p03", "audio": true, "sents": [{"ru": "Мой новый знакомый снисходительно улыбнулся.", "zh": "” 我又画了一只羊。", "t": [100, 3738]}, {"ru": "— Не видишь разве?", "zh": "我的朋友露出亲切可爱的微笑，并没有责怪我的意思，他说： “你瞧瞧，这不是小羊，是公羊，它长着角哩。", "t": [3738, 5788]}, {"ru": "— Это не барашек, а баран.", "zh": "我的朋友露出亲切可爱的微笑，并没有责怪我的意思，他说： “你瞧瞧，这不是小羊，是公羊，它长着角哩。", "t": [5788, 8375]}, {"ru": "У него же рога…", "zh": "我的朋友露出亲切可爱的微笑，并没有责怪我的意思，他说： “你瞧瞧，这不是小羊，是公羊，它长着角哩。", "t": [8375, 9376]}]}, {"id": "ch02p04", "audio": true, "sents": [{"ru": "Тогда я снова переделал свой рисунок.", "zh": "” 我又画了一张。", "t": [100, 2462]}]}, {"id": "ch02p05", "audio": true, "sents": [{"ru": "Но он отказался и от него, как и от предыдущих: — Этот барашек слишком старый.", "zh": "” 我又画了一张。", "t": [100, 5700]}, {"ru": "А мне нужен барашек, который будет жить долго.", "zh": "这一张画和前面两张一样，遭到了他的拒绝： “这只太老了，我要一只能活很久的绵羊。", "t": [5700, 9412]}, {"ru": "Тогда я потерял терпение, ведь мне нужно было спешить с починкой моего мотора.", "zh": "” 我急于着手拆卸我的发动机，失去了耐性。", "t": [9412, 14600]}, {"ru": "Я нацарапал такой рисунок и небрежно заметил:", "zh": "我胡乱涂了下面这幅画。", "t": [14600, 17438]}]}, {"id": "ch02p06", "audio": true, "sents": [{"ru": "— Вот тебе ящик.", "zh": "而且我冲他说： “这是一只箱子，你要的绵羊在里面。", "t": [100, 2425]}, {"ru": "Барашек, который тебе нужен, сидит внутри.", "zh": "而且我冲他说： “这是一只箱子，你要的绵羊在里面。", "t": [2425, 6288]}, {"ru": "Однако я был очень удивлен, когда увидел, как просияло лицо моего юного критика: — Это именно то, что я хотел!", "zh": "” 然而我惊讶地看到，我的这位小法官竟眉开眼笑： “我要的正是这样的箱子！", "t": [6288, 13950]}, {"ru": "Как ты думаешь — этому барашку надо много травы?", "zh": "” “为什么你提这个问题？", "t": [13950, 17750]}, {"ru": "— А что?", "zh": "” “因为我的家太小啦……” “肯定够了。", "t": [17750, 19362]}, {"ru": "— Потому, что у меня все очень маленькое…", "zh": "” “因为我的家太小啦……” “肯定够了。", "t": [19362, 21862]}, {"ru": "— Уверен, ему хватит.", "zh": "我给你的是一只很小很小的绵羊。", "t": [21862, 24238]}, {"ru": "Ведь он совсем маленький.", "zh": "我给你的是一只很小很小的绵羊。", "t": [24238, 26912]}, {"ru": "Он склонился к рисунку.", "zh": "” 他低头看画。", "t": [26912, 29450]}, {"ru": "— Не такой уж и маленький.", "zh": "“没有这个这么小吧……咦！", "t": [29450, 32138]}, {"ru": "Смотри-ка!", "zh": "“没有这个这么小吧……咦！", "t": [32138, 33950]}, {"ru": "Он заснул.", "zh": "它睡熟了……” 我就这样认识了小王子。", "t": [33950, 35788]}, {"ru": "Так я познакомился с маленьким принцем.", "zh": "它睡熟了……” 我就这样认识了小王子。", "t": [35788, 38150]}]}]}, {"id": "ch03", "title_ru": "Глава 3", "title_zh": "第 3 章", "paras": [{"id": "ch03p00", "audio": true, "sents": [{"ru": "Я не сразу понял, откуда он появился.", "zh": "过了好久好久，我才弄明白他是打哪儿来的。", "t": [100, 3462]}, {"ru": "Маленький принц задавал мне много вопросов и, казалось, совсем не слушал, что спрашиваю его я.", "zh": "小王子向我提了许多问题，却从不理会我对他提的问题。", "t": [3462, 9950]}, {"ru": "Однако, вслушиваясь в его случайно оброненные слова, я постепенно понял, в чем дело.", "zh": "我从他无意中吐出的片言只语里，逐渐知道了他的来历。", "t": [9950, 16225]}, {"ru": "Когда он впервые заметил мой самолет (я не буду его рисовать — такая картинка для меня слишком сложная), то спросил у меня: — Что это за штука?", "zh": "例如，当他第一次看见我的飞机的时候（我不愿画飞机，太复杂了），就问我： “这是什么玩艺儿呀？", "t": [16225, 24875]}, {"ru": "— Это не штука.", "zh": "这是飞机，是我的飞机。", "t": [24875, 26862]}, {"ru": "Это самолет.", "zh": "这是飞机，是我的飞机。", "t": [26862, 28900]}, {"ru": "Он летает.", "zh": "这是飞机，是我的飞机。", "t": [28900, 30825]}, {"ru": "Это мой самолет.", "zh": "” 我挺自豪地告诉他我会飞。", "t": [30825, 32988]}, {"ru": "И я с гордостью рассказал ему, что я летал на нем.", "zh": "他嚷起来： “怎么？", "t": [32988, 36900]}, {"ru": "— Вот как?", "zh": "你是从天上掉下来的吗？", "t": [36900, 38662]}, {"ru": "Значит, ты упал с неба?", "zh": "你是从天上掉下来的吗？", "t": [38662, 41575]}, {"ru": "— Да, — скромно ответил я.", "zh": "” “是的。", "t": [41575, 43562]}, {"ru": "— А…", "zh": "”我并没有吹嘘的意思。", "t": [43562, 44688]}, {"ru": "Это забавно…", "zh": "“啊！", "t": [44688, 46575]}, {"ru": "Маленький принц звонко рассмеялся, и это меня задело.", "zh": "“啊！", "t": [46575, 50838]}, {"ru": "Мне казалось, что к моему бедственному положению стоило отнестись серьезно.", "zh": "我不喜欢别人对我的不幸打哈哈。", "t": [50838, 56200]}, {"ru": "Потом он добавил: — Значит, ты тоже с неба.", "zh": "然后他又说： “这么说，你也是从天上下来的！", "t": [56200, 59938]}, {"ru": "А с какой планеты?", "zh": "然后他又说： “这么说，你也是从天上下来的！", "t": [59938, 62088]}, {"ru": "Тут я начал догадываться о тайне его появления и спросил его напрямик: — Так ты с другой планеты?", "zh": "” 这句话犹如一道亮光，让我马上瞥见了他突然出现的秘密。", "t": [62088, 68238]}, {"ru": "Однако он мне не ответил.", "zh": "我以突袭的方式问他： “你是从另一个星球来的？", "t": [68238, 70838]}, {"ru": "Он лишь покачал головой, глядя на мой самолет: — Пожалуй, на этой штуке ты не мог прилететь совсем издалека…", "zh": "” 他不答。", "t": [70838, 77675]}, {"ru": "Он замолчал и размышлял довольно долго.", "zh": "他看着我的飞机，轻轻地点头： “从你乘的这玩艺来看，你确实不可能来自很远的地方……” 他陷入沉思。", "t": [77675, 80100]}]}, {"id": "ch03p01", "audio": true, "sents": [{"ru": "Потом он вытащил из кармана мой рисунок с барашком и стал рассматривать этот бесценный подарок.", "zh": "过了很久，他从口袋里掏出我画的绵羊，低头凝视他的宝贝。", "t": [100, 6012]}, {"ru": "Можете себе представить, насколько я был удивлен этими его словами о других планетах.", "zh": "过了很久，他从口袋里掏出我画的绵羊，低头凝视他的宝贝。", "t": [6012, 12038]}, {"ru": "Поэтому я постарался узнать об этом побольше.", "zh": "你们不难想像，听了他那句无意透露的“其他星球”的话后，我会怎样惊讶吧。", "t": [12038, 15588]}, {"ru": "— Откуда же ты прибыл, мой маленький дружок?", "zh": "我竭力从中探听他的来历： “我的小人儿，你从哪儿来？", "t": [15588, 18888]}, {"ru": "Где это там «у тебя»?", "zh": "我竭力从中探听他的来历： “我的小人儿，你从哪儿来？", "t": [18888, 21662]}, {"ru": "Куда ты хочешь забрать моего барашка?", "zh": "你的家在哪儿？", "t": [21662, 23850]}]}, {"id": "ch03p02", "audio": true, "sents": [{"ru": "Он помолчал и ответил задумчиво: — Хорошо, что ты нарисовал его в ящичке.", "zh": "” 他默默不答。", "t": [100, 5412]}, {"ru": "По ночам он будет в нем спать.", "zh": "然后才说： “你给了我一个箱子，太好了。", "t": [5412, 8162]}, {"ru": "— Ну, конечно.", "zh": "夜里可以给绵羊做屋子了。", "t": [8162, 10338]}, {"ru": "И если ты будешь умницей, я нарисую тебе веревку, чтобы привязывать его днем.", "zh": "” “是呀，如果你乖，我还要给你一根绳子，白天给你拴羊用。", "t": [10338, 15688]}, {"ru": "И колышек.", "zh": "” “是呀，如果你乖，我还要给你一根绳子，白天给你拴羊用。", "t": [15688, 17562]}, {"ru": "Однако это мое предложение, казалось, раздосадовало маленького принца.", "zh": "我还要给你一根拴羊的桩。", "t": [17562, 23012]}, {"ru": "— Привязывать?", "zh": "” 我的建议显然惹恼了小王子： “拴住它？", "t": [23012, 24712]}, {"ru": "Какая странная мысль!", "zh": "” 我的建议显然惹恼了小王子： “拴住它？", "t": [24712, 27188]}, {"ru": "— Но если ты его не привяжешь, он может куда-нибудь забрести и потеряться…", "zh": "亏你想得出这样的主意！", "t": [27188, 32175]}, {"ru": "Тут мой дружок снова звонко рассмеялся: — Куда же, ты думаешь, он может уйти?", "zh": "” 我的朋友发出清脆的笑声： “你以为它会跑到哪儿去呢？", "t": [32175, 37588]}, {"ru": "— Неважно, куда…", "zh": "” 我的朋友发出清脆的笑声： “你以为它会跑到哪儿去呢？", "t": [37588, 39788]}, {"ru": "Куда-нибудь.", "zh": "” 我的朋友发出清脆的笑声： “你以为它会跑到哪儿去呢？", "t": [39788, 41575]}, {"ru": "Тогда маленький принц сказал вполне серьезно: — Не беда, ведь у меня там так мало места…", "zh": "” “到处乱跑呗，朝前跑呗……” 小王子告诉我： “这倒不成问题，我的家小得很呢！", "t": [41575, 47150]}, {"ru": "Потом он немного грустно добавил: — Даже если идти все время прямо, там невозможно забрести далеко.", "zh": "” 他的神色略带忧伤，说： “朝前跑，也跑不了多远……”", "t": [47150, 52237]}]}]}, {"id": "ch04", "title_ru": "Глава 4", "title_zh": "第 4 章", "paras": [{"id": "ch04p00", "audio": true, "sents": [{"ru": "Так я узнал вторую важную вещь.", "zh": "就这样，我知道了第二件很重要的事情：他打那儿来的星球比一幢房子大不了多少！", "t": [100, 3075]}, {"ru": "Его родная планета была едва ли больше обычного дома!", "zh": "就这样，我知道了第二件很重要的事情：他打那儿来的星球比一幢房子大不了多少！", "t": [3075, 7162]}, {"ru": "Впрочем, это меня не очень-то удивило.", "zh": "我并不因此大惊小怪。", "t": [7162, 10525]}, {"ru": "Я хорошо знал, что за такими большими планетами, как Земля, Юпитер, Марс и Венера, есть сотни других.", "zh": "我知道，除了起了名字的大星球，如地球、木星、火星、金星，还有成千上万的星球。", "t": [10525, 18262]}, {"ru": "Некоторые из них такие маленькие, что их трудно разглядеть в телескоп.", "zh": "有些星球小到连望远镜都难以观测。", "t": [18262, 23450]}, {"ru": "Когда астроном открывает такую планетку,", "zh": "天文学家发现一颗星，就用号码给它命名，例如叫它“小行星3251号”。", "t": [23450, 25988]}]}, {"id": "ch04p01", "audio": true, "sents": [{"ru": "он дает ей вместо названия лишь номер.", "zh": "天文学家发现一颗星，就用号码给它命名，例如叫它“小行星3251号”。", "t": [100, 3362]}, {"ru": "Он ее называет, к примеру, «астероид 3251».", "zh": "我有充分的证据认为小王子打那儿来的星球就是B612号小行星。", "t": [3362, 6050]}, {"ru": "У меня были серьезные основания думать, что планета, с которой прилетел маленький принц, была астероидом Б 612.", "zh": "我有充分的证据认为小王子打那儿来的星球就是B612号小行星。", "t": [6050, 15075]}, {"ru": "Этот астероид впервые был замечен в телескоп в 1909 году каким-то турецким астрономом.", "zh": "在国际天文会议上，他为他的发现做了雄辩的论证，但没有人相信他的报告。", "t": [15075, 23475]}, {"ru": "Он сделал об этом своем открытии большой доклад на Международном астрономическом конгрессе.", "zh": "因为他穿的是土耳其人的服装。", "t": [23475, 29262]}, {"ru": "Но никто ему тогда не поверил, потому что он был странно одет.", "zh": "大人们就这个德性：以衣冠取人。", "t": [29262, 33738]}, {"ru": "Такие вот люди, эти взрослые.", "zh": "幸好，为了维护B612小行星的声誉，土耳其独裁者颁布了一条法令，命令百姓改穿欧式服装，否则处以死刑。", "t": [33738, 36975]}]}, {"id": "ch04p02", "audio": true, "sents": [{"ru": "К счастью для астероида Б 612, турецкий правитель приказал своим подданным под страхом смерти одеваться по-европейски.", "zh": "幸好，为了维护B612小行星的声誉，土耳其独裁者颁布了一条法令，命令百姓改穿欧式服装，否则处以死刑。", "t": [100, 2512]}, {"ru": "Астроном повторил свой доклад в 1920 году.", "zh": "一九二〇年，这位土耳其天文学家身穿一套极考究的西服，再一次在国际会议上做了论证。", "t": [2512, 6912]}, {"ru": "На этот раз он был одет весьма элегантно, и все с ним согласились.", "zh": "一九二〇年，这位土耳其天文学家身穿一套极考究的西服，再一次在国际会议上做了论证。", "t": [6912, 11925]}, {"ru": "А если я вам так подробно рассказал об этом астероиде и даже сообщил его номер — Б 612, так это из-за взрослых.", "zh": "我对你们详细报告发现小行星B612的这些细节，把它的号码告诉你们，都是由于那些大人们的缘故。", "t": [11925, 19575]}, {"ru": "Взрослые любят цифры.", "zh": "我对你们详细报告发现小行星B612的这些细节，把它的号码告诉你们，都是由于那些大人们的缘故。", "t": [19575, 22188]}, {"ru": "Когда вы им рассказываете о своем новом друге, они никогда не спрашивают вас о самом главном.", "zh": "因为大人们对数字情有独钟。", "t": [22188, 28250]}, {"ru": "Они не спрашивают о его голосе или во что он играет.", "zh": "如果你对他们介绍一个新朋友，他们从不打听他的基本情况，他们从不会问你：“他的嗓子怎么样？", "t": [28250, 32125]}, {"ru": "Они не интересуются, что ему нравится и собирает ли он бабочек.", "zh": "他喜欢玩什么游戏？", "t": [32125, 36912]}, {"ru": "Они спрашивают — сколько ему лет?", "zh": "他是否采集蝴蝶标本？", "t": [36912, 40062]}, {"ru": "Сколько у него братьев?", "zh": "”而是问：“他几岁了？", "t": [40062, 42538]}, {"ru": "Сколько он весит?", "zh": "有多少个兄弟？", "t": [42538, 44788]}, {"ru": "Сколько зарабатывает его отец?", "zh": "体重多少？", "t": [44788, 47625]}, {"ru": "Только тогда им кажется, что они его узнали.", "zh": "他的父亲挣多少钱？", "t": [47625, 51275]}]}, {"id": "ch04p03", "audio": true, "sents": [{"ru": "Если вы скажете взрослым, что видели красивый дом из красного кирпича с геранью на подоконниках и с голубями на крыше, они не смогут себе его представить.", "zh": "如果你告诉大人：“我看见一幢漂亮的红砖房子，窗前摆着天竺葵，鸽子在屋顶栖息……”他们便无法想像这是一幢怎样的房子。", "t": [100, 3488]}, {"ru": "Им нужно сказать, что ты видел дом, который стоит сто тысяч франков.", "zh": "你必须对他们说：“我看见一幢值十万法郎的房子！", "t": [3488, 8788]}, {"ru": "Тогда они воскликнут: «Какая красота!».", "zh": "你必须对他们说：“我看见一幢值十万法郎的房子！", "t": [8788, 12238]}, {"ru": "Поэтому, если вы им говорите, что маленький принц существует, потому что он удивительный, потому что он смеялся и хотел, чтобы ему нарисовали барашка (ведь желание иметь барашка доказывает, что ты существуешь), они лишь пожмут плечами и посмотрят на вас, как на ребенка.", "zh": "” 所以，如果你对他们说：“这世上确实存在一位王子，证据就是他可爱俊美，脸带笑容，他要一只绵羊。", "t": [12238, 27712]}, {"ru": "Но если вы им скажете, что он прилетел с астероида Б 612, это их убедит, они от вас отстанут и не будут больше донимать своими вопросами.", "zh": "但如果你对他们说：“他打那儿来的星球是小行星B612。", "t": [27712, 36788]}, {"ru": "Они такие.", "zh": "”他们就深信不疑了，就不会用没完没了的问题烦你了。", "t": [36788, 38862]}, {"ru": "И не стоит за это на них обижаться.", "zh": "”他们就深信不疑了，就不会用没完没了的问题烦你了。", "t": [38862, 41888]}, {"ru": "Дети должны быть снисходительны ко взрослым.", "zh": "他们就这副德性。", "t": [41888, 45375]}, {"ru": "Конечно, тех, кто понимает жизнь, не волнуют цифры.", "zh": "我们不要责怪埋怨他们，孩子对大人应当尽量地宽容。", "t": [45375, 49888]}, {"ru": "Я бы хотел начать эту историю, как волшебную сказку.", "zh": "当然，我们是理解生活的人，我们才不会把数字放在眼里呢！", "t": [49888, 54300]}, {"ru": "Я бы сказал: «Жил-был однажды маленький принц.", "zh": "当然，我们是理解生活的人，我们才不会把数字放在眼里呢！", "t": [54300, 58062]}, {"ru": "И жил он на планете, которая была чуть больше его самого.", "zh": "我喜欢以讲童话的方式讲这个故事。", "t": [58062, 62425]}, {"ru": "Ему нужен был друг…»", "zh": "我喜欢这样讲： “从前有个小王子，他住在小行星里。", "t": [62425, 65050]}, {"ru": "Для тех, кто понимает жизнь, это было бы больше похоже на правду.", "zh": "这颗行星比他自己大不了多少。", "t": [65050, 69912]}, {"ru": "Мне совсем не хочется, чтобы мою книгу читали ради развлечения.", "zh": "他需要一个朋友。", "t": [69912, 74925]}, {"ru": "Мне горько рассказывать о своих воспоминаниях.", "zh": "我不喜欢别人漫不经心地读我的书。", "t": [74925, 78525]}, {"ru": "Ведь прошло уже шесть лет, как мой друг покинул меня вместе со своим барашком.", "zh": "提起这些往事，我还挺伤心的。", "t": [78525, 83925]}, {"ru": "Я пытаюсь здесь его описать, просто чтобы не забыть о нем.", "zh": "我的朋友牵着他的羊走了六年了。", "t": [83925, 88112]}, {"ru": "Ведь это грустно — забыть о друге.", "zh": "我在这儿讲述他的故事，是为了不忘记他。", "t": [88112, 91088]}, {"ru": "Не у всех в жизни был друг.", "zh": "忘了朋友是可悲的。", "t": [91088, 93800]}, {"ru": "Я ведь могу стать как взрослые, которых интересуют только цифры.", "zh": "并不是每个人都有朋友的。", "t": [93800, 98700]}, {"ru": "Для этого я и купил коробку с красками и карандаши.", "zh": "也许有一天我也像大人那样，除了数字，对别的东西都失去兴趣。", "t": [98700, 102888]}, {"ru": "Трудно снова начинать рисовать в моем возрасте,", "zh": "为了这个缘故，我买了一盒颜料和几枝铅笔。", "t": [102888, 105724]}]}, {"id": "ch04p04", "audio": true, "sents": [{"ru": "особенно если раньше, когда тебе было шесть, у тебя были всего две попытки — рисунки удава снаружи и изнутри!", "zh": "到了我这个年龄才重拾画笔是困难的。", "t": [100, 7400]}, {"ru": "Но я, конечно, постараюсь, чтобы вышло похоже.", "zh": "而且，除了在六岁那年画过一条打开肚子的蟒蛇和一条没打开肚子的蟒蛇之外，我没画过别的画。", "t": [7400, 11850]}, {"ru": "Хотя я совершенно не уверен, что у меня получится.", "zh": "当然，我可以画最逼真的人像画。", "t": [11850, 16012]}, {"ru": "Один рисунок удается, а другой — выходит не очень…", "zh": "但能否成功，我把握不大。", "t": [16012, 20312]}, {"ru": "Я сомневаюсь также насчет роста.", "zh": "这一幅画得可以，另一幅却画得不像。", "t": [20312, 23288]}, {"ru": "На одном маленький принц получается слишком большим, а на другом — слишком маленьким.", "zh": "对他的个儿高矮，我也记得不太真切。", "t": [23288, 29075]}, {"ru": "Я не уверен и в цвете его костюма.", "zh": "这幅把他画得太高，另一幅把他画得太矮。", "t": [29075, 32325]}, {"ru": "Приходится действовать по наитию, наугад — и так и этак.", "zh": "该给他的衣服抹什么颜色，我也犹豫不决。", "t": [32325, 36912]}, {"ru": "Наконец, я могу ошибаться и в некоторых важных деталях.", "zh": "我在画纸上抹来抹去，画了张约莫相似的肖像，但某些重要部位也许弄错了。", "t": [36912, 41350]}, {"ru": "Придется вам меня за это простить.", "zh": "我在画纸上抹来抹去，画了张约莫相似的肖像，但某些重要部位也许弄错了。", "t": [41350, 44250]}, {"ru": "Мой друг никогда мне ничего не объяснял.", "zh": "对这一点，你们一定要谅解。", "t": [44250, 47500]}, {"ru": "Наверное, он думал, что я такой же, как и он сам.", "zh": "对这一点，你们一定要谅解。", "t": [47500, 51862]}, {"ru": "Но я, к сожалению, не умею видеть барашков сквозь стенки ящичка.", "zh": "我的朋友从不向我解释，大概他以为我和他一样；可是我呢，很遗憾，我不能透过箱子看到里面的绵羊。", "t": [51862, 57125]}, {"ru": "Возможно, я немного похож на взрослых.", "zh": "也许我有点像大人了。", "t": [57125, 60538]}, {"ru": "Наверное, я просто постарел.", "zh": "我大概老了。", "t": [60538, 62575]}]}]}, {"id": "ch05", "title_ru": "Глава 5", "title_zh": "第 5 章", "paras": [{"id": "ch05p00", "audio": true, "sents": [{"ru": "Каждый день я узнавал кое-что новое о его планете и о начале его путешествия.", "zh": "每一天，我都从他那儿获得一些有关星球、启程、旅行的知识。", "t": [100, 5650]}, {"ru": "Он рассказывал о ней понемногу, когда выдавался случай.", "zh": "这些知识是逐渐得到的，只要想到什么问题就提什么问题。", "t": [5650, 10000]}, {"ru": "Поэтому о трагедии с баобабами я узнал лишь на третий день.", "zh": "这些知识是逐渐得到的，只要想到什么问题就提什么问题。", "t": [10000, 14100]}, {"ru": "И это случилось именно благодаря барашку.", "zh": "第三天，我就是这样了解到有关猴面包树的事情的。", "t": [14100, 17500]}, {"ru": "Маленький принц после долгого раздумья вдруг спросил меня: — Правда ведь, что барашки едят кустарники?", "zh": "这一回还真亏了绵羊。", "t": [17500, 24012]}, {"ru": "— Да, правда.", "zh": "因为小王子突然对一件事产生了极大的怀疑，突然问我： “羊吃灌木，这是真的吗？", "t": [24012, 26025]}, {"ru": "— А… это хорошо…", "zh": "因为小王子突然对一件事产生了极大的怀疑，突然问我： “羊吃灌木，这是真的吗？", "t": [26025, 28438]}, {"ru": "Я сразу не понял, почему для него было так важно, что овцы едят кусты.", "zh": "” “是呀，是真的呀。", "t": [28438, 33638]}, {"ru": "Однако маленький принц добавил: — Значит, и баобабы они тоже едят?", "zh": "” 我不明白，羊吃灌木为什么这么重要。", "t": [33638, 38712]}, {"ru": "Я заметил маленькому принцу, что баобабы — не кустарники, а деревья, высокие, как церкви, и если бы он даже прихватил на свою планету целое стадо слонов, оно не справилось бы и с одним-единственным баобабом.", "zh": "” 我提醒小王子，猴面包树不是灌木丛，而是像教堂一样巍峨高大的树。", "t": [38712, 51912]}, {"ru": "Мысль о стаде слонов на его планете рассмешила маленького принца.", "zh": "即使他弄一群大象来，它们也啃不完一棵猴面包树。", "t": [51912, 56475]}, {"ru": "— Тогда нужно будет ставить одного слона на другого.", "zh": "想到一群象啃猴面包树的情景，小王子忍不住笑了： “那它们非得叠罗汉了……” 他很机灵，指出： “猴面包树的树苗挺小的呢！", "t": [56475, 60238]}, {"ru": "Однако он мудро заметил: — Но ведь баобабы, прежде чем вырасти, тоже бывают маленькими.", "zh": "想到一群象啃猴面包树的情景，小王子忍不住笑了： “那它们非得叠罗汉了……” 他很机灵，指出： “猴面包树的树苗挺小的呢！", "t": [60238, 66350]}, {"ru": "— Это точно!", "zh": "” “你说得对！", "t": [66350, 68238]}, {"ru": "Но почему ты хочешь, чтобы твои барашки питались маленькими баобабами?", "zh": "” “你说得对！", "t": [68238, 72600]}]}, {"id": "ch05p01", "audio": true, "sents": [{"ru": "Он мне ответил, как будто речь шла о вещах очевидных: — Почему?", "zh": "” 他说：“嘿！", "t": [100, 5125]}, {"ru": "Сам прикинь…", "zh": "那还用说吗！", "t": [5125, 7000]}, {"ru": "И мне потребовалось изрядно напрячь свои мозги, чтобы понять, в чем тут проблема.", "zh": "”似乎这是再明白不过的事情。", "t": [7000, 12800]}]}, {"id": "ch05p02", "audio": true, "sents": [{"ru": "В самом деле, наверняка на планете маленького принца, как и на прочих планетах, среди полезных растений росли и сорняки.", "zh": "是的，小王子的星球和其他星球一样，长着益草，也长着毒草，因此也就有了益草的种子和毒草的种子。", "t": [100, 2688]}, {"ru": "Следовательно, в земле были хорошие семена хороших растений и плохие семена плохих.", "zh": "是的，小王子的星球和其他星球一样，长着益草，也长着毒草，因此也就有了益草的种子和毒草的种子。", "t": [2688, 8525]}, {"ru": "Однако семена толком не разглядишь.", "zh": "但种子是看不见的，它们沉埋在土地深处，直至其中一颗突然苏醒……它伸伸懒腰，羞羞答答，向着太阳伸出一株青嫩可爱、娇小玲珑、不伤人的幼苗来。", "t": [8525, 11625]}, {"ru": "Они спят до поры, храня свой секрет в земле, пока кому-нибудь из них не взбредет в голову проснуться.", "zh": "但种子是看不见的，它们沉埋在土地深处，直至其中一颗突然苏醒……它伸伸懒腰，羞羞答答，向着太阳伸出一株青嫩可爱、娇小玲珑、不伤人的幼苗来。", "t": [11625, 18050]}, {"ru": "Тогда семя дает росток.", "zh": "但种子是看不见的，它们沉埋在土地深处，直至其中一颗突然苏醒……它伸伸懒腰，羞羞答答，向着太阳伸出一株青嫩可爱、娇小玲珑、不伤人的幼苗来。", "t": [18050, 20775]}]}, {"id": "ch05p03", "audio": true, "sents": [{"ru": "Сначала он робко тянется к солнцу, такой восхитительный и безобидный.", "zh": "倘若它是萝卜或玫瑰的幼苗，我们可以任由它茁壮成长；倘若它是有毒的植物，一经认出，我们就必须马上拔除。", "t": [100, 2825]}, {"ru": "Это верно, если речь идет о ростке редиски или розы.", "zh": "倘若它是萝卜或玫瑰的幼苗，我们可以任由它茁壮成长；倘若它是有毒的植物，一经认出，我们就必须马上拔除。", "t": [2825, 6925]}, {"ru": "Тогда можно дать ему волю расти и дальше.", "zh": "倘若它是萝卜或玫瑰的幼苗，我们可以任由它茁壮成长；倘若它是有毒的植物，一经认出，我们就必须马上拔除。", "t": [6925, 10388]}, {"ru": "Однако, если речь о сорняке, его надо сразу же выполоть, как распознаешь.", "zh": "小王子的星球上埋着可怕的种子……这就是猴面包树的种子，星球的土壤饱受其害，不及时动手除掉它们，你就永远别想摆脱它们的侵害。", "t": [10388, 15850]}, {"ru": "А на планете маленького принца такие ужасные семена как раз имелись.", "zh": "小王子的星球上埋着可怕的种子……这就是猴面包树的种子，星球的土壤饱受其害，不及时动手除掉它们，你就永远别想摆脱它们的侵害。", "t": [15850, 20625]}, {"ru": "Это были семена баобабов.", "zh": "小王子的星球上埋着可怕的种子……这就是猴面包树的种子，星球的土壤饱受其害，不及时动手除掉它们，你就永远别想摆脱它们的侵害。", "t": [20625, 23300]}, {"ru": "Вся почва планеты была ими заражена.", "zh": "它的树身枝叶占据整个星球，如果星球小，而猴面包树过多，就会撑破星球。", "t": [23300, 26538]}, {"ru": "А если взяться даже за один баобаб слишком поздно, от него уже не избавишься.", "zh": "它的树身枝叶占据整个星球，如果星球小，而猴面包树过多，就会撑破星球。", "t": [26538, 31725]}, {"ru": "Он заполонит всю планету и прорастет в нее своими корнями.", "zh": "它的树身枝叶占据整个星球，如果星球小，而猴面包树过多，就会撑破星球。", "t": [31725, 36288]}, {"ru": "И если планета очень маленькая, а баобабов слишком много, они ее просто разорвут на части.", "zh": "后来小王子对我说：“人早上梳洗之后，一定要小心清理地球，要经常督促自己，要养成良好的习惯。", "t": [36288, 42900]}, {"ru": "Поэтому это важный пункт распорядка дня — говорил мне маленький принц позже.", "zh": "猴面包树的苗儿与玫瑰花的苗儿长得极相似，把它们区别开来之后，就要经常督促自己拔除猴面包树苗。", "t": [42900, 47938]}, {"ru": "Когда закончишь утром приводить себя в порядок, надо аккуратно привести в порядок свою планету.", "zh": "猴面包树的苗儿与玫瑰花的苗儿长得极相似，把它们区别开来之后，就要经常督促自己拔除猴面包树苗。", "t": [47938, 54125]}]}, {"id": "ch05p04", "audio": true, "sents": [{"ru": "Надо приучить себя регулярно выдергивать молодые баобабы, как только сможешь их отличить от кустов роз, на которые они в молодости очень похожи.", "zh": "” 有一天，他建议我用心画一幅猴面包树的画，要让我们那儿的孩子牢牢记住它。", "t": [100, 8050]}, {"ru": "Эта работа довольно скучная, хотя и очень простая.", "zh": "他对我说：“有朝一日他们外出旅行，这幅画就派上用场了。", "t": [8050, 12225]}, {"ru": "Однажды он мне посоветовал постараться нарисовать такую картинку, чтобы дети там, где я живу, хорошо это себе уяснили.", "zh": "有些时候，耽搁了的工夫造不成多大的恶果，然而对猴面包树的危害却不能轻视。", "t": [12225, 20238]}, {"ru": "«Если они когда-нибудь начнут путешествовать, — сказал он мне, — это может им помочь.", "zh": "我知道，有一颗星球上住着一个懒人，他忽略了剔除三棵猴面包树苗的事儿……” 在小王子的指点下，我画了这个星球。", "t": [20238, 25988]}, {"ru": "Иногда можно без проблем отложить свою работу.", "zh": "我知道，有一颗星球上住着一个懒人，他忽略了剔除三棵猴面包树苗的事儿……” 在小王子的指点下，我画了这个星球。", "t": [25988, 29775]}, {"ru": "Но только не в случае с баобабами.", "zh": "我知道，有一颗星球上住着一个懒人，他忽略了剔除三棵猴面包树苗的事儿……” 在小王子的指点下，我画了这个星球。", "t": [29775, 32825]}, {"ru": "Иначе это кончится бедой.", "zh": "我知道，有一颗星球上住着一个懒人，他忽略了剔除三棵猴面包树苗的事儿……” 在小王子的指点下，我画了这个星球。", "t": [32825, 35588]}, {"ru": "Я знавал одну планету, на которой жил лентяй.", "zh": "我知道，有一颗星球上住着一个懒人，他忽略了剔除三棵猴面包树苗的事儿……” 在小王子的指点下，我画了这个星球。", "t": [35588, 39600]}, {"ru": "Он долго не обращал внимание на три кустика…»", "zh": "我素来不喜欢装腔作势，摆出一副道学家的面孔训人，但许多人对猴面包树的危害认识不足，在小行星上迷路的人遇到的风险又那么大，我不能不一反平日矜持的常态，大声疾呼：“孩子们，当心猴面包树啊！", "t": [39600, 43262]}, {"ru": "По просьбе маленького принца я нарисовал ту самую планету.", "zh": "我素来不喜欢装腔作势，摆出一副道学家的面孔训人，但许多人对猴面包树的危害认识不足，在小行星上迷路的人遇到的风险又那么大，我不能不一反平日矜持的常态，大声疾呼：“孩子们，当心猴面包树啊！", "t": [43262, 47462]}, {"ru": "Я не люблю никого поучать.", "zh": "我素来不喜欢装腔作势，摆出一副道学家的面孔训人，但许多人对猴面包树的危害认识不足，在小行星上迷路的人遇到的风险又那么大，我不能不一反平日矜持的常态，大声疾呼：“孩子们，当心猴面包树啊！", "t": [47462, 50200]}, {"ru": "Однако угроза, исходящая от баобабов, столь мало известна, а опасность для тех, кто очутится на астероиде, столь серьезна, что в данном случае я, пожалуй, сделаю исключение.", "zh": "”为了向朋友们发出警告，让他们提防早已威胁我们的危险——而他们和我一样，对这样的危险一无所知——我对这幅画下足了功夫。", "t": [50200, 62075]}, {"ru": "Я говорю: «Дети!", "zh": "”为了向朋友们发出警告，让他们提防早已威胁我们的危险——而他们和我一样，对这样的危险一无所知——我对这幅画下足了功夫。", "t": [62075, 64425]}, {"ru": "Следите за баобабами!»", "zh": "”为了向朋友们发出警告，让他们提防早已威胁我们的危险——而他们和我一样，对这样的危险一无所知——我对这幅画下足了功夫。", "t": [64425, 67075]}, {"ru": "Так я хочу предупредить моих юных друзей об опасности, с которой они сталкиваются уже довольно давно.", "zh": "”为了向朋友们发出警告，让他们提防早已威胁我们的危险——而他们和我一样，对这样的危险一无所知——我对这幅画下足了功夫。", "t": [67075, 73388]}, {"ru": "Я и сам о ней не подозревал, пока не закончил этот рисунок.", "zh": "提醒大家警惕危险，是我义不容辞的责任。", "t": [73388, 77862]}, {"ru": "Над ним стоило потрудиться как следует.", "zh": "也许你们看了这幅画后会纳闷：“为什么他在这本书里画的其他画没有这张猴面包树的画雄壮，有气势？", "t": [77862, 81150]}, {"ru": "Возможно, вы меня спросите — почему в этой книжке нет других таких же внушительных рисунков, как эта картинка с баобабами?", "zh": "也许你们看了这幅画后会纳闷：“为什么他在这本书里画的其他画没有这张猴面包树的画雄壮，有气势？", "t": [81150, 89125]}, {"ru": "Ответ совсем прост.", "zh": "”我的回答很简单：我尽了力去画其他的画，但心有余而力不足。", "t": [89125, 91575]}, {"ru": "Я старался, но у меня ничего не получилось.", "zh": "”我的回答很简单：我尽了力去画其他的画，但心有余而力不足。", "t": [91575, 95100]}, {"ru": "А когда я рисовал баобабы, меня вдохновляла сама необходимость и неотложность этой работы.", "zh": "而画猴面包树的时候，为急迫的需要所激励，我的画便超出了原有的水平。", "t": [95100, 100376]}]}]}, {"id": "ch06", "title_ru": "Глава 6", "title_zh": "第 6 章", "paras": [{"id": "ch06p00", "audio": true, "sents": [{"ru": "Ах, маленький принц!", "zh": "小王子！", "t": [100, 2712]}, {"ru": "Мало-помалу я понял, почему ты так печален.", "zh": "我就是这样逐渐了解到，你过着并不顺心愉快的生活。", "t": [2712, 6338]}, {"ru": "Долгое время ты развлекал себя только красотой нежных вечерних закатов.", "zh": "长期以来，你惟一的消遣就是观赏夕阳西下的美景。", "t": [6338, 11225]}, {"ru": "Я узнал об", "zh": "长期以来，你惟一的消遣就是观赏夕阳西下的美景。", "t": [11225, 12276]}]}, {"id": "ch06p01", "audio": true, "sents": [{"ru": "этой новой подробности твоей жизни утром четвертого дня, когда ты мне сказал: — Я очень люблю закаты.", "zh": "你对我说： “我喜欢夕阳。", "t": [100, 6538]}, {"ru": "Пойдем, посмотрим на закат…", "zh": "我们去看日落的壮观吧……” “可是要等啊……” “等什么？", "t": [6538, 8550]}, {"ru": "— Надо будет подождать…", "zh": "我们去看日落的壮观吧……” “可是要等啊……” “等什么？", "t": [8550, 10050]}, {"ru": "— Подождать чего?", "zh": "” “等太阳下山的时刻呀。", "t": [10050, 11862]}, {"ru": "— Подождать, пока солнце не начнет садиться.", "zh": "” “等太阳下山的时刻呀。", "t": [11862, 15525]}, {"ru": "При этом ты сначала очень удивился, а потом рассмеялся сам над собой.", "zh": "” 你露出惊讶的神气，然后又自觉可笑，说道： “我老以为我是在自己家里呢！", "t": [15525, 20600]}, {"ru": "— Мне все время кажется, что я у себя дома.", "zh": "” 这话说得不错。", "t": [20600, 24238]}]}, {"id": "ch06p02", "audio": true, "sents": [{"ru": "В самом деле — когда в Америке полдень, все в мире знают, что во Франции солнце уже садится.", "zh": "大家都知道，在美国，太阳正在天空的当中，而这时在法国，太阳已经西下。", "t": [100, 5025]}, {"ru": "Если бы удалось за минуту попасть во Францию, можно было бы присутствовать при этом закате.", "zh": "若能在一分钟之内赶到法国，就可以观看落日的壮景，遗憾的是法国离得太远了。", "t": [5025, 10788]}, {"ru": "К несчастью, Франция слишком далеко.", "zh": "若能在一分钟之内赶到法国，就可以观看落日的壮景，遗憾的是法国离得太远了。", "t": [10788, 14175]}, {"ru": "Однако на твоей планетке тебе достаточно лишь передвинуть стул на несколько шагов.", "zh": "但是，在你那小小的星球上，你只要把椅子挪几步就能看到日落了。", "t": [14175, 19400]}, {"ru": "И ты можешь наблюдать за сумерками сколько душа пожелает.", "zh": "什么时候要看夕晖都能看得到…… “有一天，我看了四十三次太阳下山！", "t": [19400, 23438]}, {"ru": "— Однажды я наблюдал закат сорок три раза!", "zh": "什么时候要看夕晖都能看得到…… “有一天，我看了四十三次太阳下山！", "t": [23438, 26862]}, {"ru": "И немного погодя ты добавил: — Знаешь, когда грустно, хорошо смотреть на закаты…", "zh": "” 过了一会儿，你又说： “你知道……一个人愁闷的时候，都爱看西下的夕阳……” “看了四十三次太阳西下的那一天，你的心情差得很吧？", "t": [26862, 31850]}, {"ru": "— Значит, когда ты смотрел на закат сорок три раза, тебе было очень грустно?", "zh": "” 过了一会儿，你又说： “你知道……一个人愁闷的时候，都爱看西下的夕阳……” “看了四十三次太阳西下的那一天，你的心情差得很吧？", "t": [31850, 36900]}, {"ru": "Но на это маленький принц ничего не ответил.", "zh": "” 小王子没有答话。", "t": [36900, 39463]}]}]}, {"id": "ch07", "title_ru": "Глава 7", "title_zh": "第 7 章", "paras": [{"id": "ch07p00", "audio": true, "sents": [{"ru": "Этот секрет жизни маленького принца мне открылся на пятый день, и опять благодаря барашку.", "zh": "第五天，仍然是多亏了那只绵羊，小王子生活中的秘密才被泄露了出来。", "t": [100, 6000]}, {"ru": "Он меня внезапно спросил без всякого предисловия, словно давно размышлял над этой проблемой: — Ведь если барашек ест кустарники, значит и цветы тоже?", "zh": "他似乎对一个问题反复思考了许久，然后开门见山，直截了当地突然问我： “绵羊吃灌木，它也吃花吗？", "t": [6000, 15188]}, {"ru": "— Барашек ест все, что ему попадается.", "zh": "” “绵羊遇见什么吃什么。", "t": [15188, 18938]}, {"ru": "— Даже цветы с шипами?", "zh": "” “带刺的花也吃？", "t": [18938, 21438]}, {"ru": "— Да, даже цветы с шипами.", "zh": "” “吃的。", "t": [21438, 24262]}, {"ru": "— А колючки?", "zh": "带刺的花也吃。", "t": [24262, 26088]}, {"ru": "Зачем они тогда нужны?", "zh": "” “那刺还有什么作用呢？", "t": [26088, 28588]}, {"ru": "Я этого не знал.", "zh": "” “那刺还有什么作用呢？", "t": [28588, 30750]}, {"ru": "К тому же я тогда был очень занят, пытаясь открутить тугой болт в моем моторе.", "zh": "” 我不知道刺还有什么作用。", "t": [30750, 36062]}, {"ru": "Я был очень озабочен, потому что поломка стала казаться мне очень серьезной.", "zh": "看来故障极其严重，我正在犯愁呢。", "t": [36062, 41175]}, {"ru": "Питьевая вода у меня заканчивалась, и это заставляло думать о худшем.", "zh": "最让我担心的，是饮用水已经所剩不多了。", "t": [41175, 46062]}, {"ru": "— Колючки.", "zh": "“那刺还有什么作用呢？", "t": [46062, 47812]}, {"ru": "Зачем они нужны?", "zh": "“那刺还有什么作用呢？", "t": [47812, 50000]}, {"ru": "Стоило маленькому принцу задать вопрос, и он уже не отступал.", "zh": "” 小王子一旦提出疑问，就要寻根究底，追问个没完，绝不会中途而废。", "t": [50000, 54462]}, {"ru": "Тугой болт выводил меня из себя, и я ответил наобум: — Колючки?", "zh": "” 小王子一旦提出疑问，就要寻根究底，追问个没完，绝不会中途而废。", "t": [54462, 59262]}, {"ru": "Ни для чего они не нужны.", "zh": "我正被螺栓闹得心烦意乱，便顺口答道：“刺不起作用，都是因为花儿心眼太坏！", "t": [59262, 61875]}, {"ru": "Чистая вредность со стороны цветов.", "zh": "我正被螺栓闹得心烦意乱，便顺口答道：“刺不起作用，都是因为花儿心眼太坏！", "t": [61875, 65012]}, {"ru": "— Ох!", "zh": "” “哦？", "t": [65012, 66362]}, {"ru": "Однако после минутного молчания он буркнул мне в ответ: — Я тебе не верю!", "zh": "” “哦？", "t": [66362, 71662]}, {"ru": "Цветы слабые.", "zh": "” 沉默了一会儿，他悻悻地说： “我不信你说的话！", "t": [71662, 73862]}, {"ru": "Они простодушные.", "zh": "” 沉默了一会儿，他悻悻地说： “我不信你说的话！", "t": [73862, 76138]}, {"ru": "Они защищают себя, как могут.", "zh": "花儿弱不禁风，花儿天真无邪，她们自顾不暇呢。", "t": [76138, 79325]}, {"ru": "Им кажется, что они грозные со своими колючками…", "zh": "花儿弱不禁风，花儿天真无邪，她们自顾不暇呢。", "t": [79325, 82487]}]}, {"id": "ch07p01", "audio": true, "sents": [{"ru": "Я ничего не ответил.", "zh": "她们身上长了刺，是为了给自己壮胆，为了保护自己……” 我不说话。", "t": [100, 2450]}, {"ru": "В ту минуту я говорил себе: «Если этот болт не поддастся, я выбью его ударом молотка».", "zh": "她们身上长了刺，是为了给自己壮胆，为了保护自己……” 我不说话。", "t": [2450, 8375]}, {"ru": "Но маленький принц снова отвлек меня вопросом: — И ты считаешь…", "zh": "这时我的念头是：“如果这颗螺栓拧不下来，我就用锤子把它砸了。", "t": [8375, 12888]}, {"ru": "Ты думаешь, что цветы…", "zh": "” 小王子打断我的思路： “你相信，你，相信花……” “别烦我了！", "t": [12888, 14775]}, {"ru": "— Да нет же!", "zh": "” 小王子打断我的思路： “你相信，你，相信花……” “别烦我了！", "t": [14775, 16288]}, {"ru": "Нет!", "zh": "” 小王子打断我的思路： “你相信，你，相信花……” “别烦我了！", "t": [16288, 17800]}, {"ru": "Ничего я не считаю.", "zh": "” 小王子打断我的思路： “你相信，你，相信花……” “别烦我了！", "t": [17800, 20188]}, {"ru": "Неважно, что я сказал.", "zh": "” 小王子打断我的思路： “你相信，你，相信花……” “别烦我了！", "t": [20188, 22775]}, {"ru": "Я занят серьезными вещами!", "zh": "别烦我了！", "t": [22775, 25712]}, {"ru": "Он взглянул на меня с удивлением.", "zh": "我什么也不信！", "t": [25712, 28750]}, {"ru": "— Серьезными вещами?", "zh": "我不过在信口开河啊。", "t": [28750, 31262]}, {"ru": "Он смотрел на меня, а я стоял с молотком в руке и с пальцами, черными от смазки.", "zh": "” 他瞪着我，愣住了。", "t": [31262, 37075]}, {"ru": "Я склонялся над предметом, который казался ему уродливым.", "zh": "“你在忙正经事！", "t": [37075, 41662]}, {"ru": "— Ты говоришь, как взрослые!", "zh": "” 他看见我手攥锤子，两手油污，俯身对着一件他认为很丑的物件。", "t": [41662, 44700]}, {"ru": "Это меня смутило, а он добавил без всякой жалости: — Ты все путаешь…", "zh": "“你说话的时候像个大人！", "t": [44700, 49575]}, {"ru": "Ты ничего не понимаешь!", "zh": "” 听了这话，我有点难为情。", "t": [49575, 51862]}, {"ru": "Он действительно был рассержен.", "zh": "” 听了这话，我有点难为情。", "t": [51862, 54588]}]}, {"id": "ch07p02", "audio": true, "sents": [{"ru": "Он тряхнул на ветру своими золотистыми волосами: — Мне знакома одна планета, на которой живет господин с багровой физиономией.", "zh": "” 他真的气坏了。", "t": [100, 3462]}, {"ru": "Он никогда не нюхал цветы.", "zh": "“我知道一颗行星，上面有一位红脸先生。", "t": [3462, 6138]}, {"ru": "Он ни разу не взглянул на звезду.", "zh": "他从未嗅过一朵花。", "t": [6138, 8950]}, {"ru": "Он никогда никого не любил.", "zh": "他从未嗅过一朵花。", "t": [8950, 11600]}, {"ru": "Он лишь занимается подсчетами.", "zh": "他从未观赏过一颗星星。", "t": [11600, 14612]}, {"ru": "И целый день кряду он, как и ты, повторяет: «Я человек серьезный!", "zh": "他什么事也没干过，只会做算术中的加法。", "t": [14612, 19975]}, {"ru": "Я человек серьезный!»", "zh": "他什么事也没干过，只会做算术中的加法。", "t": [19975, 22600]}, {"ru": "И он раздувается от гордости.", "zh": "他整天就像你一样，反复地唠叨：‘我是个正经人！", "t": [22600, 25562]}, {"ru": "Но это не человек, а какой-то гриб!", "zh": "我是正经人！", "t": [25562, 28712]}, {"ru": "— Кто?", "zh": "我是正经人！", "t": [28712, 30088]}, {"ru": "— Гриб!", "zh": "我是正经人！", "t": [30088, 31600]}, {"ru": "В эту минуту маленький принц был бледен от гнева.", "zh": "’真是自命不凡，神气活现！", "t": [31600, 35350]}, {"ru": "— Вот уже миллионы лет, как цветы отращивают шипы.", "zh": "” “是什么？", "t": [35350, 39775]}, {"ru": "Несмотря на это вот уже миллионы лет, как овцы их едят.", "zh": "” 小王子气得脸色发白。", "t": [39775, 44312]}, {"ru": "И это не серьезно — пытаться понять, почему они так стараются отращивать шипы, которые ни для чего не нужны?", "zh": "“几百万年以来，花儿都长着刺；几百万年以来，羊也在吃花。", "t": [44312, 51162]}, {"ru": "И это не важно — постоянная война между овцами и цветами?", "zh": "难道我想知道，花儿为什么憋足了劲长没用的刺，这是不正经的事吗？", "t": [51162, 55850]}, {"ru": "Это не так важно и серьезно, как подсчеты багрового господина?", "zh": "这不比红脸胖子的加法更正经，更重要吗？", "t": [55850, 60675]}, {"ru": "И если я знаю, что единственный цветок в мире, который существует только на моей планете, в одно прекрасное утро может вот так запросто уничтожить барашек, который даже не понимает, что делает, — разве это не важно?", "zh": "要是我认识的世界上的一朵独一无二的花，她哪儿也不去，就爱长在我的星球上，可是却在某天早晨，被小绵羊一不留神咬死了，难道这样的事也不重要吗？", "t": [60675, 72938]}, {"ru": "Он покраснел, а потом продолжил: — Если ты любишь цветок, существующий среди миллионов и миллионов звезд, этого достаточно, чтобы быть счастливым, когда смотришь на звезды.", "zh": "” 他的脸由白转红，然后说： “要是有个人爱上了一朵花，这朵花不长在亿万颗星球上，只长在他的星球上，而他只要仰望星空，想到‘我的花儿就在那儿……’，心就陶醉在幸福里，羊却吃了他心爱的花——这对他而言，简直是整个星空都黯淡无光了，难道这样的事还不重要吗？", "t": [72938, 83462]}, {"ru": "Ты знаешь — мой цветок где-то там…", "zh": "” 他的脸由白转红，然后说： “要是有个人爱上了一朵花，这朵花不长在亿万颗星球上，只长在他的星球上，而他只要仰望星空，想到‘我的花儿就在那儿……’，心就陶醉在幸福里，羊却吃了他心爱的花——这对他而言，简直是整个星空都黯淡无光了，难道这样的事还不重要吗？", "t": [83462, 86600]}, {"ru": "Но если барашек съест этот цветок, покажется, что погасли все звезды!", "zh": "” 他的脸由白转红，然后说： “要是有个人爱上了一朵花，这朵花不长在亿万颗星球上，只长在他的星球上，而他只要仰望星空，想到‘我的花儿就在那儿……’，心就陶醉在幸福里，羊却吃了他心爱的花——这对他而言，简直是整个星空都黯淡无光了，难道这样的事还不重要吗？", "t": [86600, 91912]}, {"ru": "И это не важно?!", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [91912, 94038]}, {"ru": "Он не смог больше ничего сказать и неожиданно разразился рыданиями.", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [94038, 97937]}]}, {"id": "ch07p03", "audio": true, "sents": [{"ru": "Настала ночь.", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [100, 2050]}, {"ru": "Я отложил в сторону свои инструменты.", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [2050, 5475]}, {"ru": "Мне стали безразличны мой молоток, болт, жажда и даже сама смерть.", "zh": "夜幕降临，我扔下手里的工具，顾不得锤子、螺栓、干渴、死亡了。", "t": [5475, 10975]}, {"ru": "На звезде, на планете, на моей Земле плакал маленький принц, и его надо было утешить.", "zh": "在一颗星球上，在我的行星地球上，有一个小王子需要安慰！", "t": [10975, 17075]}, {"ru": "Я взял его на руки, баюкал и говорил: «Цветок, который ты так любишь, в безопасности.", "zh": "我把他搂进怀里，轻柔地摇着他。", "t": [17075, 23438]}, {"ru": "Я нарисую твоему барашку намордник.", "zh": "我把他搂进怀里，轻柔地摇着他。", "t": [23438, 26712]}, {"ru": "Я нарисую доспехи для твоего цветка…»", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [26712, 29938]}, {"ru": "Я не знал точно, что надо говорить.", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [29938, 33188]}, {"ru": "Я чувствовал себя таким глупым и неуклюжим.", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [33188, 36825]}, {"ru": "Я не знал, как достучаться, как проникнуть в его душу…", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [36825, 41262]}, {"ru": "Ведь она такая непознанная и таинственная — эта страна слез…", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [41262, 45213]}]}]}, {"id": "ch08", "title_ru": "Глава 8", "title_zh": "第 8 章", "paras": [{"id": "ch08p00", "audio": true, "sents": [{"ru": "Вскоре я узнал об этом цветке больше.", "zh": "我很快就对这朵花有了更深的了解。", "t": [100, 3288]}, {"ru": "На планете маленького принца было много простых цветов с обычным венчиком лепестков.", "zh": "小王子生活的星球上长着很朴素的单瓣花，她们一点儿也不占地方，也不扰人，在草地上朝开暮落。", "t": [3288, 8938]}, {"ru": "Они не занимали много места и никому не мешали.", "zh": "小王子生活的星球上长着很朴素的单瓣花，她们一点儿也不占地方，也不扰人，在草地上朝开暮落。", "t": [8938, 12712]}, {"ru": "По утрам они распускались среди травы, а к вечеру увядали.", "zh": "而这朵花的种子不知道是从哪儿来的。", "t": [12712, 17250]}, {"ru": "А тот цветок возник из семечка, занесенного невесть откуда, и маленький принц внимательно разглядывал необычный росток, который отличался от всех прочих.", "zh": "她很可能是新品种的猴面包树苗呢。", "t": [17250, 26975]}, {"ru": "Ведь он мог оказаться ростком новой разновидности баобаба.", "zh": "然而枝条很快就停止伸展，竟开始结花蕾。", "t": [26975, 31088]}, {"ru": "Но кустик вскоре перестал расти и был готов к цветению.", "zh": "小王子看着硕大的花苞，预感到她会绽放出奇异的花朵。", "t": [31088, 35450]}, {"ru": "Маленький принц видел, как зарождался огромный бутон, и предугадывал появление чуда, но цветок под зеленой защитой листьев медлил раскрыть свою красоту.", "zh": "她仔细挑！", "t": [35450, 44850]}, {"ru": "Казалось, он все еще тщательно подбирает свои будущие оттенки.", "zh": "她不肯像虞美人那样，皱巴巴地就往外跑，就亮相。", "t": [44850, 49712]}, {"ru": "Он медленно прихорашивался, расправляя один лепесток за другим.", "zh": "唉！", "t": [49712, 54388]}, {"ru": "Он не желал появиться растрепанным, словно какой-нибудь мак.", "zh": "不错，她就是朵极爱俏的花儿。", "t": [54388, 58838]}, {"ru": "Он хотел возникнуть в полном великолепии своей красоты.", "zh": "她神秘兮兮地梳妆打扮了好几天，终于在一天早晨，在太阳出来的那一刻，她露脸亮相了。", "t": [58838, 63062]}, {"ru": "И да!", "zh": "她神秘兮兮地梳妆打扮了好几天，终于在一天早晨，在太阳出来的那一刻，她露脸亮相了。", "t": [63062, 64500]}, {"ru": "Цветок был очень кокетлив.", "zh": "精心打扮了几天，算准了出场的时间，她却打着哈欠说： “唉！", "t": [64500, 67262]}, {"ru": "Ведь его таинственные приготовления длились изо дня в день.", "zh": "精心打扮了几天，算准了出场的时间，她却打着哈欠说： “唉！", "t": [67262, 71425]}, {"ru": "Но однажды утром, как раз на восходе солнца, эта красавица появилась.", "zh": "我刚刚睡醒呢……请你原谅……我的妆还零乱呢……” 小王子忍不住赞叹： “您真美啊！", "t": [71425, 76725]}, {"ru": "Хотя она трудилась над своим появлением долго и прилежно, зевнув, она сказала: — Ах!", "zh": "我刚刚睡醒呢……请你原谅……我的妆还零乱呢……” 小王子忍不住赞叹： “您真美啊！", "t": [76725, 82812]}, {"ru": "Я еще не совсем проснулась…", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [82812, 85550]}, {"ru": "Прошу меня извинить…", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [85550, 87975]}, {"ru": "Я такая растрепанная…", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [87975, 89662]}]}, {"id": "ch08p01", "audio": true, "sents": [{"ru": "Однако маленький принц не смог сдержать своего восхищения и воскликнул: — Как вы прекрасны!", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [100, 6112]}, {"ru": "— В самом деле?", "zh": "“是吃早点的时候了吧。", "t": [6112, 8075]}, {"ru": "— тихо проговорила она.", "zh": "“是吃早点的时候了吧。", "t": [8075, 10512]}, {"ru": "— Я ведь родилась вместе с солнцем…", "zh": "”很快她又说。", "t": [10512, 13675]}, {"ru": "Маленький принц понял, что цветок слегка нескромен, но он был таким трогательным!", "zh": "“劳驾您给我……” 小王子为自己的疏忽而感到羞惭，赶紧找了一壶清水，侍候花儿用餐。", "t": [13675, 19150]}, {"ru": "— Мне кажется, в это время пора завтракать, — тут же добавила красавица.", "zh": "不久，她爱慕虚荣的性情开始折磨他。", "t": [19150, 24250]}, {"ru": "— Вы же позаботитесь обо мне?", "zh": "不久，她爱慕虚荣的性情开始折磨他。", "t": [24250, 25912]}]}, {"id": "ch08p02", "audio": true, "sents": [{"ru": "И маленький принц, взволнованный и смущенный, поискал лейку с водой и услужил цветку.", "zh": "例如，有一天，她对小王子说到她身上长的四根刺的用途。", "t": [100, 6412]}, {"ru": "А красавица вскоре стала испытывать терпение маленького принца своими страхами и капризами.", "zh": "她说： “这儿也许有老虎吧，老虎的爪子锋利得很呢！", "t": [6412, 12250]}, {"ru": "Однажды, например, говоря о своих четырех шипах, она сказала ему: — Ведь сюда могут заявиться тигры со своими ужасными когтями!", "zh": "“我可不是草。", "t": [12250, 19738]}]}, {"id": "ch08p03", "audio": true, "sents": [{"ru": "— На моей планете нет тигров, — возразил маленький принц.", "zh": "“对不起……” “我一点也不畏惧老虎，但我讨厌风。", "t": [100, 4525]}, {"ru": "— И потом, тигры не едят траву.", "zh": "您没有屏风吗？", "t": [4525, 7525]}, {"ru": "— Я не трава, — тихо ответила она.", "zh": "” “你居然讨厌风啊……这可不好。", "t": [7525, 10675]}, {"ru": "— Извините меня…", "zh": "”小王子对她有了看法。", "t": [10675, 12038]}, {"ru": "— Меня вовсе не страшат тигры, но я ужасно боюсь сквозняков.", "zh": "”小王子对她有了看法。", "t": [12038, 16350]}, {"ru": "У вас найдется ширма?", "zh": "“这朵花倒很复杂……” “晚上您用罩子把我罩起来吧。", "t": [16350, 18800]}, {"ru": "«Подумать только!", "zh": "“这朵花倒很复杂……” “晚上您用罩子把我罩起来吧。", "t": [18800, 20850]}, {"ru": "Боязнь сквозняков!", "zh": "您这儿太冷，位置不好。", "t": [20850, 23275]}, {"ru": "Да, с этим цветком будет непросто», — решил про себя маленький принц.", "zh": "我来的那个地方……” 她住了口。", "t": [23275, 27400]}]}, {"id": "ch08p04", "audio": true, "sents": [{"ru": "— По вечерам вы должны накрывать меня стеклянным колпаком.", "zh": "来这儿的时候她还是一颗种子呢，怎么可能了解别的地方呢。", "t": [100, 4025]}, {"ru": "У вас тут так холодно и неуютно.", "zh": "来这儿的时候她还是一颗种子呢，怎么可能了解别的地方呢。", "t": [4025, 7200]}, {"ru": "Там, откуда я родом…", "zh": "她撒的谎幼稚可笑，让人一下子就能识破。", "t": [7200, 8688]}]}, {"id": "ch08p05", "audio": true, "sents": [{"ru": "Но тут она замолкла.", "zh": "她撒的谎幼稚可笑，让人一下子就能识破。", "t": [100, 2550]}, {"ru": "Она ведь попала на планету в виде семечка и поэтому не знала ничего о других мирах.", "zh": "她觉得丢脸，便咳嗽了两三声，想把过错推到小王子身上去： “我要的屏风呢？", "t": [2550, 8088]}, {"ru": "Попав врасплох из-за попытки невинно соврать, она немного покашляла, чтобы заставить маленького принца почувствовать себя виноватым.", "zh": "……” “我正要去找屏风，是您和我说话的呀！", "t": [8088, 16225]}, {"ru": "— Так где же ширма?", "zh": "” 她又故意咳嗽，存心让他内疚不安。", "t": [16225, 18438]}, {"ru": "— Я хотел пойти за ней, но вы со мной говорили!", "zh": "” 她又故意咳嗽，存心让他内疚不安。", "t": [18438, 22038]}, {"ru": "Тогда она закашлялась громче, чтобы маленькому принцу стало совестно.", "zh": "小王子很怜爱她，但她的做作令他生疑。", "t": [22038, 26213]}]}, {"id": "ch08p06", "audio": true, "sents": [{"ru": "Несмотря на искреннюю любовь маленького принца к цветку, в его душе появились некоторые сомнения.", "zh": "他是个做事一丝不苟的人，常把无关紧要的闲话当真，难免招来不少麻烦。", "t": [100, 6662]}, {"ru": "Он страдал, принимая пустые слова цветка всерьез.", "zh": "有一天，他向我倾诉他的心事：“我本不该听信她的话的。", "t": [6662, 10738]}, {"ru": "«Я не должен был слушать ее, — признался он мне позже.", "zh": "永远也别信花儿讲的话。", "t": [10738, 14975]}, {"ru": "— Не нужно слушать, что говорят цветы.", "zh": "她们的作用就是供人观赏，供人嗅闻。", "t": [14975, 18412]}, {"ru": "Ими нужно любоваться, вдыхать их аромат.", "zh": "我的花熏香了我的星球，但我不懂得为此高兴。", "t": [18412, 21912]}, {"ru": "Моя красавица наполняла благоуханием всю планету, но я не умел этому радоваться.", "zh": "她说的老虎爪子的话，本来应该打动我的心，我却生了她的气。", "t": [21912, 27662]}, {"ru": "Эта история с тигриными когтями, которая меня так вывела из себя, должна была меня насторожить…»", "zh": "” 他还说： “那时我真是不懂事。", "t": [27662, 34050]}, {"ru": "И он признался еще кое в чем: «Я тогда ничего не понимал!", "zh": "要对一个人下定论，不应听其言，而应观其行。", "t": [34050, 38238]}, {"ru": "Я должен был судить по ее делам, а не по словам.", "zh": "她芬芳馥郁，赏心悦目，我不应抛下她一走了之！", "t": [38238, 42138]}, {"ru": "Она дарила мне свой аромат и озаряла мою жизнь.", "zh": "我不理解她那不聪明的谎言饱含的深情。", "t": [42138, 45988]}, {"ru": "Я не должен был убегать!", "zh": "我不理解她那不聪明的谎言饱含的深情。", "t": [45988, 48588]}, {"ru": "Мне надо было разглядеть за ее уловками нежность и хрупкость.", "zh": "花儿是缺点不少、但优点也很多的矛盾的东西！", "t": [48588, 52900]}, {"ru": "Цветы так противоречивы!", "zh": "花儿是缺点不少、但优点也很多的矛盾的东西！", "t": [52900, 55538]}, {"ru": "Но я был слишком неопытен, чтобы уметь ее любить».", "zh": "那时我年纪太轻，不懂得珍惜她，爱她。", "t": [55538, 58812]}]}]}, {"id": "ch09", "title_ru": "Глава 9", "title_zh": "第 9 章", "paras": [{"id": "ch09p00", "audio": true, "sents": [{"ru": "Думаю, он воспользовался для своего побега перелетными птицами.", "zh": "我估计他是趁候鸟迁徙时出走的。", "t": [100, 4925]}, {"ru": "В последнее утро перед отлетом он тщательно привел свою планету в порядок.", "zh": "出走的那天早晨，他认真收拾整理他的星球，仔细疏通火山口。", "t": [4925, 9938]}, {"ru": "Он прочистил жерла действующих вулканов.", "zh": "他有两座活火山，热早饭挺方便的。", "t": [9938, 13475]}, {"ru": "У него на планете было два таких вулкана.", "zh": "他还有一座死火山。", "t": [13475, 16812]}, {"ru": "С их помощью было так удобно по утрам разогревать завтраки.", "zh": "可是正如他说的：“日后的事很难说！", "t": [16812, 20988]}, {"ru": "Один вулкан на планете был потухшим, но маленький принц частенько говорил себе: «Никогда не знаешь, что может пригодиться».", "zh": "所以他也疏通死火山。", "t": [20988, 28862]}, {"ru": "Поэтому он прочистил также и потухший вулкан.", "zh": "火山喷发的道理与炉火一样。", "t": [28862, 32575]}, {"ru": "Ведь если вулканы хорошо прочищены, они работают тихо и равномерно, без извержений.", "zh": "我们这些人太渺小，没有疏通火山的能力，所以火山才给我们造成很多麻烦。", "t": [32575, 38812]}, {"ru": "Вулканические извержения — они как искры из печной трубы.", "zh": "我们这些人太渺小，没有疏通火山的能力，所以火山才给我们造成很多麻烦。", "t": [38812, 43875]}, {"ru": "К сожалению, на нашей Земле мы слишком малы, чтобы прочищать свои вулканы.", "zh": "小王子闷闷地拔除了最后几棵猴面包树苗。", "t": [43875, 49412]}, {"ru": "Вот почему от них бывает так много неприятностей.", "zh": "他知道自己不会再回来了。", "t": [49412, 53425]}, {"ru": "Маленький принц с некоторым сожалением выполол также последние ростки баобабов.", "zh": "那天早晨，他觉得所有的家务活干起来都挺亲切的。", "t": [53425, 58750]}, {"ru": "Ведь он думал, что больше сюда не вернется.", "zh": "最后一次给花儿浇水，准备给她盖上罩子，他竟觉得他想哭。", "t": [58750, 62312]}, {"ru": "Тем утром эта привычная работа казалась ему необычайно приятной.", "zh": "他对花儿说：“别了。", "t": [62312, 66800]}, {"ru": "И когда он полил в последний раз свой цветок и готов был уже поместить его под стеклянный колпак, он готов был расплакаться.", "zh": "花儿咳嗽，可不是因为着了凉。", "t": [66800, 74438]}, {"ru": "— Прощай, — сказал он цветку.", "zh": "好好地享受生活吧，愿你幸福。", "t": [74438, 77288]}, {"ru": "Но цветок ему ничего не ответил.", "zh": "好好地享受生活吧，愿你幸福。", "t": [77288, 80212]}, {"ru": "— Прощай, — повторил он.", "zh": "” 她并没有责备他的意思。", "t": [80212, 82688]}, {"ru": "Красавица покашляла.", "zh": "他觉得挺意外。", "t": [82688, 85138]}, {"ru": "Хотя, конечно, дело было не в простуде.", "zh": "他觉得挺意外。", "t": [85138, 87812]}]}, {"id": "ch09p01", "audio": true, "sents": [{"ru": "— Я была глупой, — сказала она наконец.", "zh": "他不知所措地站在那儿，高举着罩子。", "t": [100, 3550]}, {"ru": "— Прости меня и постарайся быть счастливым.", "zh": "他不理解她的脉脉深情。", "t": [3550, 6900]}, {"ru": "Маленький принц был удивлен, не услыхав никаких укоров.", "zh": "“是的，我爱你，”花儿对他说，“你丝毫没察觉到我对你的爱，这是我的错。", "t": [6900, 11362]}, {"ru": "Он был растерян и замер, все еще держа стеклянный колпак в руке.", "zh": "如今说也没用了。", "t": [11362, 15875]}, {"ru": "Он не ожидал такой нежности.", "zh": "你和我一样傻。", "t": [15875, 17788]}]}, {"id": "ch09p02", "audio": true, "sents": [{"ru": "— Ну, конечно, я люблю тебя, — сказал ему цветок.", "zh": "好好地享受生活吧，愿你幸福……你把这罩子放一边去吧，我不需要它。", "t": [100, 4275]}, {"ru": "— Ты об этом не знал, и это моя ошибка.", "zh": "好好地享受生活吧，愿你幸福……你把这罩子放一边去吧，我不需要它。", "t": [4275, 7500]}, {"ru": "Но теперь это не важно.", "zh": "好好地享受生活吧，愿你幸福……你把这罩子放一边去吧，我不需要它。", "t": [7500, 9812]}, {"ru": "Ты был таким же глупым, как и я.", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [9812, 12662]}, {"ru": "Будь счастлив.", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [12662, 14700]}, {"ru": "Оставь этот колпак в покое.", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [14700, 17638]}, {"ru": "Он мне больше не нужен.", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [17638, 20012]}, {"ru": "— А сквозняки?", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [20012, 21925]}, {"ru": "— Не так уж я и простужена.", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [21925, 24650]}, {"ru": "Ночной свежий воздух мне на пользу.", "zh": "” “可是动物……” “如果我想认识蝴蝶，就必须能承受两三条毛虫。", "t": [24650, 27812]}, {"ru": "Я же цветок.", "zh": "” “可是动物……” “如果我想认识蝴蝶，就必须能承受两三条毛虫。", "t": [27812, 29950]}, {"ru": "— А хищные звери?", "zh": "” “可是动物……” “如果我想认识蝴蝶，就必须能承受两三条毛虫。", "t": [29950, 32088]}, {"ru": "— Было бы неплохо выдержать на себе двух или трех гусениц, если я хочу познакомиться с бабочками.", "zh": "这似乎是很美的事。", "t": [32088, 38438]}]}, {"id": "ch09p03", "audio": true, "sents": [{"ru": "Говорят, они прекрасны.", "zh": "你呢，又快离我而去了。", "t": [100, 2750]}, {"ru": "Иначе кто будет меня навещать?", "zh": "你呢，又快离我而去了。", "t": [2750, 5675]}, {"ru": "Ты ведь будешь далеко отсюда.", "zh": "我一点不畏惧大的动物，我有爪子呀。", "t": [5675, 8300]}, {"ru": "Что до хищных зверей, то я ничего не боюсь.", "zh": "” 她天真地伸出她的四根刺。", "t": [8300, 11750]}, {"ru": "У меня ведь есть свои когти.", "zh": "” 她天真地伸出她的四根刺。", "t": [11750, 14538]}, {"ru": "При этом она наивно показала свои четыре шипа.", "zh": "然后又说： “别婆婆妈妈，磨磨蹭蹭的了，闹得人心乱。", "t": [14538, 18188]}, {"ru": "Потом она добавила: — Ну, не тяни!", "zh": "你既已下了决心，那就走吧。", "t": [18188, 21338]}, {"ru": "Это же невыносимо!", "zh": "你既已下了决心，那就走吧。", "t": [21338, 23575]}, {"ru": "Раз ты решил уйти, так уходи!", "zh": "” 她不愿让小王子看见她哭。", "t": [23575, 26512]}, {"ru": "Она не хотела, чтобы он увидел ее заплаканной.", "zh": "” 她不愿让小王子看见她哭。", "t": [26512, 30212]}, {"ru": "Ведь это был гордый цветок.", "zh": "她是一朵多么骄傲的花儿哟……", "t": [30212, 31988]}]}]}, {"id": "ch10", "title_ru": "Глава 10", "title_zh": "第 10 章", "paras": [{"id": "ch10p00", "audio": true, "sents": [{"ru": "Маленький принц очутился вблизи астероидов 325, 326, 327, 329 и 330.", "zh": "他居住的星球位于小行星325号、326号、327号、328号、329号、330号所在的地区。", "t": [100, 7225]}, {"ru": "Он решил их посетить, чтобы занять себя и чему-нибудь научиться.", "zh": "他居住的星球位于小行星325号、326号、327号、328号、329号、330号所在的地区。", "t": [7225, 13975]}, {"ru": "На первом астероиде жил король.", "zh": "于是他决定首先拜访它们，在那儿找事干，并增长见识。", "t": [13975, 16900]}, {"ru": "В пурпурной мантии, украшенной мехом горностаев, он восседал на простом и вместе с тем величественном троне.", "zh": "325号行星上住着一位国王。", "t": [16900, 24075]}, {"ru": "— А!", "zh": "325号行星上住着一位国王。", "t": [24075, 25338]}, {"ru": "Вот и подданный!", "zh": "他穿着镶有紫红色袖口和领口的白鼬皮衣服，坐在式样简单然而威严的宝座上。", "t": [25338, 27638]}, {"ru": "— воскликнул король, заметив маленького принца.", "zh": "他穿着镶有紫红色袖口和领口的白鼬皮衣服，坐在式样简单然而威严的宝座上。", "t": [27638, 31612]}, {"ru": "А маленький принц удивился: «Как он меня узнал?", "zh": "看见小王子，国王大声嚷： “哈！", "t": [31612, 35250]}, {"ru": "Ведь он меня ни разу не видел!»", "zh": "看见小王子，国王大声嚷： “哈！", "t": [35250, 38100]}, {"ru": "Маленький принц не знал, что для королей мир устроен довольно просто.", "zh": "来了一个老百姓。", "t": [38100, 42750]}, {"ru": "Ведь для них все люди — подданные.", "zh": "” 小王子心想： “他从未见过我，怎么认得出我呢？", "t": [42750, 46062]}, {"ru": "— Подойди поближе, чтобы я мог тебя рассмотреть получше, — сказал ему король.", "zh": "” 他不知道，国王们把世界看得很简单，他们以为普天下的人都是他的百姓。", "t": [46062, 51238]}, {"ru": "Он был необычайно горд, что наконец-то стал для кого-то повелителем.", "zh": "国王为终于成为另一个人的国王而自豪。", "t": [51238, 56200]}, {"ru": "Маленький принц поискал глазами, куда бы присесть, но вся планета была занята великолепной горностаевой мантией короля.", "zh": "他对小王子说：“过来，让我好好地瞧瞧你。", "t": [56200, 63788]}, {"ru": "И он остался стоять, а поскольку устал, то зевнул.", "zh": "” 小王子用眼睛搜寻可坐之处，可是行星被国王豪华的鼬皮塞满了，他只好站着，因为累了，他打了个哈欠。", "t": [63788, 67888]}, {"ru": "— Это совершенно против правил — зевать в присутствии короля, — сказал ему монарх.", "zh": "“在国王面前打哈欠，违反礼节，我不准你打哈欠。", "t": [67888, 73425]}, {"ru": "— Я тебе это запрещаю.", "zh": "“在国王面前打哈欠，违反礼节，我不准你打哈欠。", "t": [73425, 76138]}, {"ru": "— Но я не могу удержаться от зевоты, — смущенно ответил маленький принц.", "zh": "”国王说道。", "t": [76138, 81050]}, {"ru": "— Я проделал такой долгий путь и давно не спал.", "zh": "小王子抱歉地说：“我不是有意的。", "t": [81050, 83813]}]}, {"id": "ch10p01", "audio": true, "sents": [{"ru": "— Тогда, — сказал король, — я приказываю тебе зевать.", "zh": "我长途跋涉，没有睡眠……” “既然如此，”国王对他说，“我命令你打哈欠。", "t": [100, 4250]}, {"ru": "Я не видел как зевают уже много лет.", "zh": "我已经多年没看见别人打哈欠了。", "t": [4250, 7350]}, {"ru": "Зевающие люди меня забавляют.", "zh": "我已经多年没看见别人打哈欠了。", "t": [7350, 10388]}, {"ru": "Ну, давай!", "zh": "依我看，打哈欠挺好玩的。", "t": [10388, 12462]}, {"ru": "Зевни еще разок.", "zh": "依我看，打哈欠挺好玩的。", "t": [12462, 14788]}, {"ru": "Это приказ!", "zh": "依我看，打哈欠挺好玩的。", "t": [14788, 16612]}, {"ru": "— У меня больше не получается, — смутился маленький принц и густо покраснел.", "zh": "这是命令。", "t": [16612, 21688]}, {"ru": "— Вот как?", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [21688, 23450]}, {"ru": "— ответил король.", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [23450, 25500]}, {"ru": "— Тогда я…", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [25500, 27212]}, {"ru": "Я приказываю тебе зевать, а то…", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [27212, 30400]}, {"ru": "Он забормотал и казался сбитым с толку.", "zh": "“嗯，嗯，”国王说，“那么我……我命令你一会儿打，一会儿不打……” 显然，挨了小王子的冲撞，他有点气恼，话也说不流利了。", "t": [30400, 32900]}]}, {"id": "ch10p02", "audio": true, "sents": [{"ru": "Для короля ведь было очень важно не потерять авторитет.", "zh": "“嗯，嗯，”国王说，“那么我……我命令你一会儿打，一会儿不打……” 显然，挨了小王子的冲撞，他有点气恼，话也说不流利了。", "t": [100, 4062]}, {"ru": "Он не выносил непокорности.", "zh": "“嗯，嗯，”国王说，“那么我……我命令你一会儿打，一会儿不打……” 显然，挨了小王子的冲撞，他有点气恼，话也说不流利了。", "t": [4062, 6825]}, {"ru": "Это был абсолютный монарх.", "zh": "“嗯，嗯，”国王说，“那么我……我命令你一会儿打，一会儿不打……” 显然，挨了小王子的冲撞，他有点气恼，话也说不流利了。", "t": [6825, 9512]}, {"ru": "Но поскольку он был правителем добрым, то отдавал лишь разумные приказы.", "zh": "国王最关心的是别人尊重他的权威，他不允许别人违抗他的命令，他是一个典型的专制君王，但他毕竟是个善良之辈，下达的命令都合乎情理。", "t": [9512, 14412]}, {"ru": "«Если я прикажу, — говорил он частенько, — какому-нибудь генералу превратиться в морскую птицу, и он не подчинится, это будет вина не генерала.", "zh": "国王最关心的是别人尊重他的权威，他不允许别人违抗他的命令，他是一个典型的专制君王，但他毕竟是个善良之辈，下达的命令都合乎情理。", "t": [14412, 23075]}, {"ru": "Виноват буду я».", "zh": "“要是我向一个将军下令，要他变成海鸟，将军是不愿服从的。", "t": [23075, 25338]}, {"ru": "— Могу я присесть?", "zh": "“要是我向一个将军下令，要他变成海鸟，将军是不愿服从的。", "t": [25338, 27512]}, {"ru": "— робко осведомился маленький принц.", "zh": "“要是我向一个将军下令，要他变成海鸟，将军是不愿服从的。", "t": [27512, 30612]}, {"ru": "— Я приказываю тебе сесть, — ответил ему король, подобрав полу своей горностаевой мантии.", "zh": "”他说，口齿很伶俐。", "t": [30612, 36875]}, {"ru": "Однако маленькому принцу стало любопытно, чем можно было править на такой маленькой планетке.", "zh": "“我命令你坐下。", "t": [36875, 42750]}, {"ru": "— Сир, — сказал он королю, — прошу меня простить, что спрашиваю…", "zh": "”国王说，他威风凛凛地一挥白鼬皮皇袍的下摆。", "t": [42750, 46825]}, {"ru": "— Я приказываю тебе меня спрашивать!", "zh": "小王子有个问题弄不明白：这颗星球小得惊人，国王统治什么？", "t": [46825, 49588]}, {"ru": "— поспешно перебил король.", "zh": "小王子有个问题弄不明白：这颗星球小得惊人，国王统治什么？", "t": [49588, 52012]}, {"ru": "— Сир… а над чем вы властвуете?", "zh": "“陛下……”他说，“请原谅我向您提个问题……” “我命令你向我提问题……”国王急忙说。", "t": [52012, 55162]}, {"ru": "— Над всем!", "zh": "“陛下……”他说，“请原谅我向您提个问题……” “我命令你向我提问题……”国王急忙说。", "t": [55162, 56912]}, {"ru": "— простодушно ответил король.", "zh": "“陛下……”他说，“请原谅我向您提个问题……” “我命令你向我提问题……”国王急忙说。", "t": [56912, 59625]}, {"ru": "— Над всем?", "zh": "“陛下……”他说，“请原谅我向您提个问题……” “我命令你向我提问题……”国王急忙说。", "t": [59625, 61350]}, {"ru": "Король скромно указал на свою планетку и на другие планеты со звездами.", "zh": "“陛下……您统治什么？", "t": [61350, 66338]}, {"ru": "— Над всем этим?", "zh": "“陛下……您统治什么？", "t": [66338, 68338]}, {"ru": "— переспросил маленький принц.", "zh": "” “统治一切！", "t": [68338, 71000]}, {"ru": "— Над всем этим, — гордо ответил король.", "zh": "” 国王指指他的星球，其他星球，所有的星球。", "t": [71000, 74338]}, {"ru": "Ведь он был не только монархом абсолютным, но и вселенским.", "zh": "“所有这一切？", "t": [74338, 78612]}, {"ru": "— И вам повинуются звезды?", "zh": "“所有这一切……”国王答道。", "t": [78612, 80237]}]}, {"id": "ch10p03", "audio": true, "sents": [{"ru": "— Разумеется, — сказал король.", "zh": "“所有这一切……”国王答道。", "t": [100, 3125]}, {"ru": "— По первому приказу.", "zh": "因为他不但是个专制君主，还是宇宙之王。", "t": [3125, 5388]}, {"ru": "Я не терплю неповиновения!", "zh": "因为他不但是个专制君主，还是宇宙之王。", "t": [5388, 8400]}, {"ru": "Такое могущество восхитило маленького принца.", "zh": "“所有的星星都听命于您吗？", "t": [8400, 12012]}, {"ru": "Если бы он обладал подобной властью, то мог бы присутствовать не только при сорока четырех, а при семидесяти двух или даже при сотне или при двух сотнях закатов солнца в течение одного дня, даже не передвигая свой стул!", "zh": "” 小王子既赞叹又羡慕国王的权威。", "t": [12012, 24412]}, {"ru": "А поскольку после расставания со своей планетой маленькому принцу было грустно, он осмелился попросить у короля милости.", "zh": "如果他也掌握这样的权力，一天之内他就可以不止观赏四十三次，而是观赏七十二次，甚至一百次，或两百次日落，还不用挪动椅子！", "t": [24412, 31700]}, {"ru": "— Я хотел бы увидеть закат солнца…", "zh": "想到被他遗弃的小行星，他有点伤感惆怅。", "t": [31700, 34725]}, {"ru": "Сделайте одолжение — прикажите солнцу зайти…", "zh": "想到被他遗弃的小行星，他有点伤感惆怅。", "t": [34725, 37850]}, {"ru": "— Если бы я приказал какому-нибудь генералу перелетать с одного цветка на другой подобно бабочке, или написать великую трагедию, или превратиться в морскую птицу, и, если бы генерал не выполнил этот полученный приказ, кто был бы в этом виноват — он или я?", "zh": "他壮壮胆，请求国王开恩： “我想观看夕阳西下……求您开恩……命令太阳下去吧……” “如果我命令将军像蝴蝶那样，在花间飞来飞去，或命令他写一部悲剧，或变成海鸟，如果将军接到命令后不愿执行，你说是他的错还是我的错？", "t": [37850, 51950]}, {"ru": "— Конечно, вы, — уверенно ответил маленький принц.", "zh": "” “那是您的错。", "t": [51950, 56000]}, {"ru": "— Верно.", "zh": "” “那是您的错。", "t": [56000, 57588]}, {"ru": "От каждого надо требовать лишь то, на что он способен, — продолжил король.", "zh": "“你说得对，不能强人所难。", "t": [57588, 62625]}, {"ru": "— Власть держится прежде всего на разуме.", "zh": "”国王说。", "t": [62625, 66088]}, {"ru": "Если прикажешь своему народу пойти и броситься в пропасть, он устроит революцию.", "zh": "如果你命令你的人民跳海，他们定会造反。", "t": [66088, 71850]}, {"ru": "А я могу требовать повиновения, ведь мои приказы разумны.", "zh": "我有命令百姓服从的权利，那是因为我的命令合符情理。", "t": [71850, 76212]}, {"ru": "— А как же заход солнца?", "zh": "” “那么，我要求的日落呢？", "t": [76212, 78712]}, {"ru": "— напомнил маленький принц, который никогда не отступал, если задавал вопрос.", "zh": "”小王子问道。", "t": [78712, 83324]}]}, {"id": "ch10p04", "audio": true, "sents": [{"ru": "— Получишь ты свой закат.", "zh": "一旦提出一个问题，他是不会中途而废的。", "t": [100, 2625]}, {"ru": "Я этого потребую!", "zh": "一旦提出一个问题，他是不会中途而废的。", "t": [2625, 5025]}, {"ru": "Однако надо подождать.", "zh": "“你会看到你要求的日落的，我会发布命令。", "t": [5025, 7500]}, {"ru": "В науке управления важно выбрать подходящий момент.", "zh": "“你会看到你要求的日落的，我会发布命令。", "t": [7500, 11438]}, {"ru": "— А когда он настанет?", "zh": "要科学管理一个国家，下命令应等时机成熟。", "t": [11438, 13900]}, {"ru": "— спросил маленький принц.", "zh": "要科学管理一个国家，下命令应等时机成熟。", "t": [13900, 16525]}, {"ru": "— Так, так, — ответил король, взглянув сначала на большой календарь.", "zh": "”小王子问。", "t": [16525, 21562]}, {"ru": "— Так, так…", "zh": "“嗯，嗯，首先我要查看大皇历。", "t": [21562, 23488]}, {"ru": "Это произойдет…", "zh": "“嗯，嗯，首先我要查看大皇历。", "t": [23488, 25612]}, {"ru": "Это случится…", "zh": "“嗯，嗯，首先我要查看大皇历。", "t": [25612, 27712]}, {"ru": "Этим вечером около семи часов двадцати минут!", "zh": "嗯，嗯，要等到……今晚……十时四十分左右……左右……你会看到他们怎样执行我的命令。", "t": [27712, 31400]}, {"ru": "И ты увидишь, как всё мне повинуется!", "zh": "嗯，嗯，要等到……今晚……十时四十分左右……左右……你会看到他们怎样执行我的命令。", "t": [31400, 34912]}, {"ru": "Маленький принц зевнул.", "zh": "嗯，嗯，要等到……今晚……十时四十分左右……左右……你会看到他们怎样执行我的命令。", "t": [34912, 37450]}, {"ru": "Он уже пожалел о пропущенных закатах на своей собственной планете.", "zh": "” 小王子打了个哈欠。", "t": [37450, 42025]}, {"ru": "К тому же ему становилось скучно.", "zh": "他感到惋惜，因为他的要求泡汤了。", "t": [42025, 45000]}, {"ru": "— Пожалуй, мне тут больше делать нечего, — сказал он королю.", "zh": "再说，他已经有点儿腻烦了。", "t": [45000, 49312]}, {"ru": "— Я лучше пойду.", "zh": "“我在这儿没事可干了，”他对国王说，“我要告辞了！", "t": [49312, 51462]}, {"ru": "— Останься,— ответил король, которому было так лестно иметь подданного.", "zh": "” “你别走。", "t": [51462, 56562]}, {"ru": "— Не уходи!", "zh": "”国王说，拥有一个百姓，对他来说是一件值得自豪的事。", "t": [56562, 58338]}, {"ru": "Я сделаю тебя министром…", "zh": "”国王说，拥有一个百姓，对他来说是一件值得自豪的事。", "t": [58338, 60300]}, {"ru": "— Министром чего?", "zh": "”国王说，拥有一个百姓，对他来说是一件值得自豪的事。", "t": [60300, 62050]}, {"ru": "— Ну… правосудия.", "zh": "“别走，我任命你为部长！", "t": [62050, 64825]}, {"ru": "— Но тут некого судить!", "zh": "“别走，我任命你为部长！", "t": [64825, 67400]}, {"ru": "— Как знать, — ответил ему король.", "zh": "” “哪个部的部长？", "t": [67400, 70500]}, {"ru": "— Я еще не объехал все свое королевство.", "zh": "” “……司法部。", "t": [70500, 73862]}, {"ru": "Я очень стар, места для кареты у меня нет, а ходить пешком очень утомительно.", "zh": "” “可这儿没人可审呀！", "t": [73862, 79362]}, {"ru": "— Да?", "zh": "” “这可就难说了，”国王说，“我还没视察过我的王国呢。", "t": [79362, 80738]}, {"ru": "Но я уже все видел, — сказал маленький принц и наклонился, чтобы еще раз бросить взгляд на другую сторону планеты.", "zh": "我上了年纪，这儿又没有停马车的地方，走路又太累了。", "t": [80738, 87900]}, {"ru": "— Тут никого нет.", "zh": "” “啊，我已经看过了。", "t": [87900, 89938]}, {"ru": "— Тогда ты будешь судить себя самого, — ответил король.", "zh": "”小王子俯身朝星球的另一端又瞟了一眼。", "t": [89938, 93925]}, {"ru": "— А это труднее всего.", "zh": "”小王子俯身朝星球的另一端又瞟了一眼。", "t": [93925, 96288]}, {"ru": "Это значительно сложнее, чем судить других.", "zh": "“那儿也没一个人……” “你就审你自己吧，”国王说，“这是最难办的事。", "t": [96288, 100075]}, {"ru": "Если ты сможешь правильно судить о себе, значит, ты поистине мудр.", "zh": "“那儿也没一个人……” “你就审你自己吧，”国王说，“这是最难办的事。", "t": [100075, 104200]}]}, {"id": "ch10p05", "audio": true, "sents": [{"ru": "— Но я, — возразил маленький принц, — могу судить о себе самом где угодно.", "zh": "你若能审自己，你就是真正的聪明人。", "t": [100, 5362]}, {"ru": "Для этого не нужно здесь жить.", "zh": "你若能审自己，你就是真正的聪明人。", "t": [5362, 8112]}, {"ru": "— Так, так…", "zh": "” “我嘛，”小王子说，“无论在什么地方我都能审自己，无需住在这儿。", "t": [8112, 9212]}, {"ru": "— сказал король.", "zh": "” “我嘛，”小王子说，“无论在什么地方我都能审自己，无需住在这儿。", "t": [9212, 11050]}, {"ru": "— Однако я точно знаю, что на моей планете где-то живет старая крыса.", "zh": "” “嗯，嗯，我知道。", "t": [11050, 15875]}, {"ru": "Я слышу ее по ночам.", "zh": "” “嗯，嗯，我知道。", "t": [15875, 18450]}, {"ru": "Ты можешь судить ее и время от времени приговаривать к смерти.", "zh": "“在我的星球的某一处，有一只老耗子。", "t": [18450, 22638]}, {"ru": "Тогда ее жизнь будет зависеть от твоего судейского решения.", "zh": "我在夜里听到的。", "t": [22638, 27038]}, {"ru": "Но каждый раз из милости и экономии ты будешь ее миловать.", "zh": "隔一段时间判它一次死刑。", "t": [27038, 31400]}, {"ru": "Ведь она тут одна…", "zh": "这样，它的死活就由你的裁判决定了。", "t": [31400, 32762]}, {"ru": "— Но я, — возразил маленький принц, — не люблю приговаривать к смерти, поэтому я, пожалуй, пойду.", "zh": "但你每一次都要免除它的死罪，你要悠着点，因为就只有这一个犯人了。", "t": [32762, 39462]}, {"ru": "— Нет, не пойдешь!", "zh": "” “我可不喜欢判人死刑。", "t": [39462, 41888]}, {"ru": "— сказал король.", "zh": "” “我可不喜欢判人死刑。", "t": [41888, 43900]}, {"ru": "Однако уже собравшемуся в путь маленькому принцу не хотелось огорчать старого монарха.", "zh": "“我看我该走了。", "t": [43900, 49450]}, {"ru": "— Если вы, Ваше Величество, желаете беспрекословного подчинения, отдайте мне разумный приказ.", "zh": "”国王说。", "t": [49450, 56025]}, {"ru": "Вы могли бы, к примеру, мне повелеть не мешкая отправиться в дорогу.", "zh": "小王子已经做好走的准备，但他不愿伤老国王的心，他对老国王说：“如果陛下您希望令出即行，您可以向我下达合理的命令。", "t": [56025, 60862]}, {"ru": "Мне кажется, что момент для этого самый подходящий.", "zh": "例如说，可以命令我在一分钟之内离开。", "t": [60862, 65125]}, {"ru": "И поскольку король на это ничего не ответил, маленький принц после минутного колебания со вздохом отправился в путь.", "zh": "我认为时机已经成熟……” 国王一言不发。", "t": [65125, 72075]}, {"ru": "— Я назначаю тебя своим послом!", "zh": "小王子犹豫片刻，然后叹口气，抬腿走了。", "t": [72075, 75062]}, {"ru": "— успел крикнуть ему вдогонку король.", "zh": "国王急忙大叫：“我封你为大使。", "t": [75062, 78100]}, {"ru": "Вид у него при этом был очень властный.", "zh": "” 他摆出威风凛凛的神气。", "t": [78100, 81325]}, {"ru": "«Взрослые такие странные», — подумал маленький принц, продолжая свой полет.", "zh": "小王子一面赶路，一面自言自语： “大人们真怪。", "t": [81325, 86013]}]}]}, {"id": "ch11", "title_ru": "Глава 11", "title_zh": "第 11 章", "paras": [{"id": "ch11p00", "audio": true, "sents": [{"ru": "На второй планете жил честолюбец.", "zh": "第二颗星球住着一个爱慕虚荣的人。", "t": [100, 3125]}, {"ru": "— Ага!", "zh": "第二颗星球住着一个爱慕虚荣的人。", "t": [3125, 4600]}, {"ru": "— закричал он, еще издалека заметив маленького принца.", "zh": "啊！", "t": [4600, 8950]}, {"ru": "— Вот и почитатель явился!", "zh": "崇拜我的人访问我啦！", "t": [8950, 11538]}, {"ru": "Ведь для честолюбцев все прочие люди являются лишь почитателями и поклонниками.", "zh": "”看见小王子，这位爱慕虚荣的人打老远就高声喊。", "t": [11538, 17075]}, {"ru": "— Добрый день, — сказал маленький принц.", "zh": "“您好。", "t": [17075, 20475]}, {"ru": "— У вас очень забавная шляпа.", "zh": "“您的帽子真怪。", "t": [20475, 23250]}, {"ru": "— Она чтобы раскланиваться, — ответил честолюбец.", "zh": "“您的帽子真怪。", "t": [23250, 27138]}, {"ru": "— Я снимаю ее, когда мне аплодируют, но, к несчастью, здесь никого не бывает.", "zh": "” “这顶帽子是用来敬礼的，”爱慕虚荣的人说，“有人向我欢呼的时候，我就用它敬礼。", "t": [27138, 33075]}, {"ru": "— В самом деле?", "zh": "可惜这儿没一个人来。", "t": [33075, 35038]}, {"ru": "— ответил маленький принц, который мало что понял.", "zh": "可惜这儿没一个人来。", "t": [35038, 38950]}, {"ru": "— Похлопай одной ладонью по другой, — посоветовал ему честолюбец.", "zh": "”小王子听不懂他的话。", "t": [38950, 43762]}, {"ru": "Маленький принц похлопал руками, и тогда честолюбец изящно его приветствовал, приподняв над головой свою шляпу.", "zh": "小王子依言鼓掌。", "t": [43762, 51262]}, {"ru": "«Тут веселее, чем на планете у короля», — подумал при этом маленький принц.", "zh": "“这比拜访国王有趣多了。", "t": [51262, 56325]}, {"ru": "И он снова начал хлопать в ладоши, а честолюбец продолжал приподнимать свою шляпу.", "zh": "爱慕虚荣的人又举帽子行礼。", "t": [56325, 62188]}, {"ru": "Минут через пять эта однообразная игра маленькому принцу надоела.", "zh": "反复操练了五分钟之后，小王子厌倦了这个单调的游戏。", "t": [62188, 66900]}, {"ru": "— А что надо сделать, чтобы шляпа упала?", "zh": "“该怎样做才能让您放下帽子？", "t": [66900, 70388]}, {"ru": "— спросил он честолюбца.", "zh": "”小王子问。", "t": [70388, 73188]}, {"ru": "Однако тот его не услышал.", "zh": "爱慕虚荣的人听不见这句话。", "t": [73188, 75900]}, {"ru": "Ведь честолюбцы не слышат ничего, кроме восхвалений.", "zh": "爱慕虚荣的人只听得见赞扬声。", "t": [75900, 79150]}]}, {"id": "ch11p01", "audio": true, "sents": [{"ru": "— Ты ведь действительно мной ужасно восхищаешься?", "zh": "“你对我真的崇拜到了五体投地？", "t": [100, 3662]}, {"ru": "— спросил честолюбец маленького принца.", "zh": "”他问小王子。", "t": [3662, 7038]}, {"ru": "— А что значит «восхищаться»?", "zh": "“什么叫做‘崇拜’？", "t": [7038, 10038]}, {"ru": "— Восхищаться?", "zh": "” “‘崇拜’就是承认我是星球上最帅、衣着最讲究、最富有、最聪明的人。", "t": [10038, 12075]}, {"ru": "Это значит признавать, что я самый лучший, самый нарядный, самый богатый и самый умный на этой планете.", "zh": "” “‘崇拜’就是承认我是星球上最帅、衣着最讲究、最富有、最聪明的人。", "t": [12075, 19375]}, {"ru": "— Но ты же тут один!", "zh": "” “在你的星球上只有你一个人啊！", "t": [19375, 21550]}, {"ru": "— Ну, пожалуйста, сделай одолжение, повосхищайся мной еще немного!", "zh": "” “你就让我享受被人崇拜的快乐吧，仍然崇拜我吧！", "t": [21550, 26762]}, {"ru": "— Хорошо, — сказал маленький принц, пожав плечами.", "zh": "” “你就让我享受被人崇拜的快乐吧，仍然崇拜我吧！", "t": [26762, 30988]}, {"ru": "— Я тобой восхищаюсь.", "zh": "” “我崇拜你，”小王子耸耸肩，“这有什么值得你快乐的呢？", "t": [30988, 33425]}, {"ru": "Но какой тебе от этого прок?", "zh": "” “我崇拜你，”小王子耸耸肩，“这有什么值得你快乐的呢？", "t": [33425, 36225]}, {"ru": "И маленький принц помчался дальше.", "zh": "” 小王子走了。", "t": [36225, 39325]}, {"ru": "«Нет, определенно взрослые весьма странные создания», — думал он про себя во время полета.", "zh": "“大人们确实怪得出奇。", "t": [39325, 44400]}]}]}, {"id": "ch12", "title_ru": "Глава 12", "title_zh": "第 12 章", "paras": [{"id": "ch12p00", "audio": true, "sents": [{"ru": "На следующей планете жил пьяница.", "zh": "下一颗星球住着一个酒鬼。", "t": [100, 3312]}, {"ru": "Визит к нему был коротким, и он весьма огорчил маленького принца.", "zh": "这次访问时间不长，但小王子极为不快。", "t": [3312, 7213]}]}, {"id": "ch12p01", "audio": true, "sents": [{"ru": "— Что ты тут делаешь?", "zh": "“你在干什么？", "t": [100, 2288]}, {"ru": "— спросил он пьяницу, который сидел перед целой коллекцией пустых и полных бутылок.", "zh": "”小王子看见酒鬼在喝闷酒，面前摆着一大堆空瓶子和装满了酒的瓶子，就这样问他。", "t": [2288, 8200]}, {"ru": "— Я пью, — мрачно ответил пьяница.", "zh": "“我在喝酒呀。", "t": [8200, 11600]}, {"ru": "— И зачем ты пьешь?", "zh": "”酒鬼闷闷不乐地回答。", "t": [11600, 13738]}, {"ru": "— поинтересовался маленький принц.", "zh": "“你为什么喝酒呢？", "t": [13738, 16675]}, {"ru": "— Чтобы забыть, — ответил пьяница.", "zh": "”小王子问他。", "t": [16675, 20075]}, {"ru": "— Забыть что?", "zh": "”酒鬼答。", "t": [20075, 21912]}, {"ru": "— с сочувствием осведомился маленький принц.", "zh": "“为了忘记什么？", "t": [21912, 25388]}, {"ru": "— Что мне стыдно, — признался пьяница, опустив голову.", "zh": "“为了忘记羞愧呗。", "t": [25388, 28863]}]}, {"id": "ch12p02", "audio": true, "sents": [{"ru": "— Стыдно что?", "zh": "”酒鬼低着头，老老实实地承认。", "t": [100, 1888]}, {"ru": "— спросил маленький принц, которому захотелось ему помочь.", "zh": "“为了什么事羞愧呢？", "t": [1888, 6362]}, {"ru": "— Стыдно, что я пью, — буркнул пьяница и надолго замолк.", "zh": "”小王子打算帮助他，又问。", "t": [6362, 10800]}, {"ru": "И маленький принц покинул эту планету в полной растерянности.", "zh": "”酒鬼讲完后，闭了嘴巴不再讲话。", "t": [10800, 15062]}, {"ru": "«Взрослые определенно очень, очень странные», — снова подумал он про себя во время полета.", "zh": "“大人们真是没法理解。", "t": [15062, 20288]}]}]}, {"id": "ch13", "title_ru": "Глава 13", "title_zh": "第 13 章", "paras": [{"id": "ch13p00", "audio": true, "sents": [{"ru": "На четвертой планете обитал бизнесмен.", "zh": "第四颗星球是商人的星球。", "t": [100, 3475]}, {"ru": "Этот человек был так занят, что даже не поднял голову при появлении маленького принца.", "zh": "小王子到来的时候，商人正埋头忙碌，头也没抬起来。", "t": [3475, 9225]}, {"ru": "— Добрый день, — поздоровался маленький принц.", "zh": "“您的香烟已经熄灭了。", "t": [9225, 12800]}, {"ru": "— Смотрите, ваша сигарета погасла.", "zh": "” “三加二等于五，五加七等于十二，十二加三等于十五，你好。", "t": [12800, 16000]}, {"ru": "— Три да два — пять.", "zh": "” “三加二等于五，五加七等于十二，十二加三等于十五，你好。", "t": [16000, 18462]}, {"ru": "Семь и пять — двенадцать.", "zh": "” “三加二等于五，五加七等于十二，十二加三等于十五，你好。", "t": [18462, 21162]}, {"ru": "Двенадцать и три — пятнадцать.", "zh": "十五加七等于二十二，二十二加六等于二十八，我没时间点烟。", "t": [21162, 24138]}, {"ru": "Привет.", "zh": "十五加七等于二十二，二十二加六等于二十八，我没时间点烟。", "t": [24138, 25788]}, {"ru": "Пятнадцать и семь — двадцать два.", "zh": "十五加七等于二十二，二十二加六等于二十八，我没时间点烟。", "t": [25788, 28538]}, {"ru": "Двадцать два и шесть — двадцать восемь.", "zh": "二十六加五等于三十一。", "t": [28538, 31675]}, {"ru": "У меня нет времени ее снова зажечь.", "zh": "一共是五亿零一百六十二万二千七百三十一。", "t": [31675, 34750]}, {"ru": "Двадцать шесть и пять — тридцать один.", "zh": "” “五亿个什么？", "t": [34750, 38025]}, {"ru": "Уф!", "zh": "” “五亿个什么？", "t": [38025, 39400]}, {"ru": "Итого получается пятьсот один миллион шестьсот двадцать две тысячи семьсот тридцать один.", "zh": "你还在这儿？", "t": [39400, 44700]}, {"ru": "— Пятьсот миллионов чего?", "zh": "我是个正经人，不爱讲废话！", "t": [44700, 47062]}, {"ru": "— Что?", "zh": "我是个正经人，不爱讲废话！", "t": [47062, 48525]}, {"ru": "Ты еще тут?", "zh": "我是个正经人，不爱讲废话！", "t": [48525, 50412]}, {"ru": "Пятьсот один миллион…", "zh": "二加五等于七……” “五亿零一百万个什么？", "t": [50412, 52700]}, {"ru": "Чего?..", "zh": "二加五等于七……” “五亿零一百万个什么？", "t": [52700, 54288]}, {"ru": "Я уже не помню.", "zh": "二加五等于七……” “五亿零一百万个什么？", "t": [54288, 56412]}, {"ru": "У меня столько дел!", "zh": "二加五等于七……” “五亿零一百万个什么？", "t": [56412, 58500]}, {"ru": "Я человек серьезный.", "zh": "”小王子还在追问，他一旦提出问题，绝不中途而废。", "t": [58500, 61012]}, {"ru": "Меня не занимает всякий вздор.", "zh": "”小王子还在追问，他一旦提出问题，绝不中途而废。", "t": [61012, 63862]}, {"ru": "Два и пять — семь.", "zh": "”小王子还在追问，他一旦提出问题，绝不中途而废。", "t": [63862, 66400]}, {"ru": "— Пятьсот миллионов чего?", "zh": "商人抬起头： “我住在这个星球已经五十四年了，只受过三次干扰。", "t": [66400, 68775]}, {"ru": "— спросил маленький принц, который никогда не отступал, если задавал вопрос.", "zh": "商人抬起头： “我住在这个星球已经五十四年了，只受过三次干扰。", "t": [68775, 74175]}, {"ru": "Бизнесмен поднял голову: — За те пятьдесят четыре года, что я живу на этой планете, мне мешали всего три раза.", "zh": "第一次干扰发生在二十二年前，鬼知道从哪儿掉下一个愣头青，发出的声音大得吓人，弄得我的加法出了四个错；第二次干扰发生在十一年前，我患了关节炎，我缺乏体育锻炼，我没时间闲逛，我是个正经人；第三次……就是这一次！", "t": [74175, 81000]}, {"ru": "Первый раз это случилось двадцать два года тому назад.", "zh": "第一次干扰发生在二十二年前，鬼知道从哪儿掉下一个愣头青，发出的声音大得吓人，弄得我的加法出了四个错；第二次干扰发生在十一年前，我患了关节炎，我缺乏体育锻炼，我没时间闲逛，我是个正经人；第三次……就是这一次！", "t": [81000, 84738]}, {"ru": "Бог знает откуда сюда прилетел майский жук.", "zh": "第一次干扰发生在二十二年前，鬼知道从哪儿掉下一个愣头青，发出的声音大得吓人，弄得我的加法出了四个错；第二次干扰发生在十一年前，我患了关节炎，我缺乏体育锻炼，我没时间闲逛，我是个正经人；第三次……就是这一次！", "t": [84738, 88350]}, {"ru": "Он ужасно жужжал, и я сделал четыре ошибки в сложении.", "zh": "我刚好算到五亿零一百万个……” “五亿零一百万个什么？", "t": [88350, 92775]}, {"ru": "Второй случай был одиннадцать лет назад.", "zh": "我刚好算到五亿零一百万个……” “五亿零一百万个什么？", "t": [92775, 96112]}, {"ru": "Меня скрутил ревматизм.", "zh": "我刚好算到五亿零一百万个……” “五亿零一百万个什么？", "t": [96112, 98812]}]}, {"id": "ch13p01", "audio": true, "sents": [{"ru": "Мне не хватает движения, но у меня нет времени на прогулки.", "zh": "” 商人知道他休想安宁了： “五亿零一百万个小东西，有时在天上看得到的小东西。", "t": [100, 1450]}, {"ru": "Ведь я человек серьезный.", "zh": "” 商人知道他休想安宁了： “五亿零一百万个小东西，有时在天上看得到的小东西。", "t": [1450, 4162]}, {"ru": "А в третий раз сюда явился ты!", "zh": "” 商人知道他休想安宁了： “五亿零一百万个小东西，有时在天上看得到的小东西。", "t": [4162, 7012]}, {"ru": "Итак, я говорил — пятьсот один миллион…", "zh": "” “苍蝇吗？", "t": [7012, 9838]}, {"ru": "— Миллионов чего?", "zh": "” “不是，是闪闪发亮的小东西。", "t": [9838, 11612]}, {"ru": "Бизнесмен понял, что от него не отстанут.", "zh": "” “蜜蜂吗？", "t": [11612, 15112]}, {"ru": "— Миллионов этих маленьких штуковин, которые иногда видны на небе.", "zh": "” “不是，是金色的小东西，能教闲得发慌的人发痴做梦的小东西，可我是正经人，我没时间遐想做梦。", "t": [15112, 20100]}, {"ru": "— Мошек?", "zh": "” “不是，是金色的小东西，能教闲得发慌的人发痴做梦的小东西，可我是正经人，我没时间遐想做梦。", "t": [20100, 21750]}, {"ru": "— Да нет же!", "zh": "” “不是，是金色的小东西，能教闲得发慌的人发痴做梦的小东西，可我是正经人，我没时间遐想做梦。", "t": [21750, 23500]}, {"ru": "Таких маленьких штучек, которые сияют.", "zh": "” “啊！", "t": [23500, 27250]}, {"ru": "— Пчел?", "zh": "” “啊！", "t": [27250, 28675]}, {"ru": "— Да нет же!", "zh": "” “啊！", "t": [28675, 30412]}, {"ru": "Тех золотистых маленьких штучек, которые заставляют мечтать.", "zh": "” “就是这个。", "t": [30412, 35238]}, {"ru": "Но я-то человек серьезный.", "zh": "” “你要五亿多颗星星做什么？", "t": [35238, 38012]}, {"ru": "У меня нет времени предаваться пустым мечтам.", "zh": "” “是五亿零一百六十二万二千七百三十一颗。", "t": [38012, 40600]}]}, {"id": "ch13p02", "audio": true, "sents": [{"ru": "— А!", "zh": "” “是五亿零一百六十二万二千七百三十一颗。", "t": [100, 1362]}, {"ru": "Звезд!", "zh": "” “是五亿零一百六十二万二千七百三十一颗。", "t": [1362, 3038]}, {"ru": "— Вот именно — звезд.", "zh": "” “是五亿零一百六十二万二千七百三十一颗。", "t": [3038, 5712]}, {"ru": "— И что ты делаешь с этими миллионами звезд?", "zh": "我是个一丝不苟的人，我务求精确。", "t": [5712, 9138]}, {"ru": "— С пятьсот одним миллионом шестьюстами двадцатью двумя тысячами семьсот тридцать одной звездой, если быть точным.", "zh": "” “我要它们干什么？", "t": [9138, 15825]}, {"ru": "— Так что ты делаешь с этими звездами?", "zh": "” “你拥有星星？", "t": [15825, 18925]}, {"ru": "— Что я с ними делаю?", "zh": "” “是呀。", "t": [18925, 21212]}, {"ru": "— Ну, да…", "zh": "” “是呀。", "t": [21212, 22500]}, {"ru": "— Ничего.", "zh": "” “我见过一个国王，他……” “国王不是‘拥有’，他是‘统治’。", "t": [22500, 24012]}, {"ru": "Я ими владею.", "zh": "” “我见过一个国王，他……” “国王不是‘拥有’，他是‘统治’。", "t": [24012, 26200]}, {"ru": "— Ты владеешь звездами?", "zh": "” “我见过一个国王，他……” “国王不是‘拥有’，他是‘统治’。", "t": [26200, 28675]}, {"ru": "— Да.", "zh": "” “我见过一个国王，他……” “国王不是‘拥有’，他是‘统治’。", "t": [28675, 30050]}, {"ru": "— Однако я уже видел короля, который…", "zh": "大不相同。", "t": [30050, 32512]}, {"ru": "— Короли не владеют.", "zh": "” “你拥有星星又怎么样呢？", "t": [32512, 34475]}, {"ru": "Они правят.", "zh": "” “你拥有星星又怎么样呢？", "t": [34475, 36362]}, {"ru": "Это совсем другое дело.", "zh": "” “拥有了星星，我就成了大富翁呗。", "t": [36362, 38900]}, {"ru": "— А зачем тебе владеть звездами?", "zh": "” “拥有了星星，我就成了大富翁呗。", "t": [38900, 41838]}, {"ru": "— Зачем владеть?", "zh": "” “成了富翁有什么好处？", "t": [41838, 43950]}, {"ru": "Чтобы быть богатым.", "zh": "” “成了富翁有什么好处？", "t": [43950, 46200]}, {"ru": "— А зачем тебе богатство?", "zh": "” “如果又有人发现了新的星星，我就把它们买下来呀。", "t": [46200, 48638]}, {"ru": "— Чтобы приобретать новые звезды, когда их ктонибудь откроет.", "zh": "” “如果又有人发现了新的星星，我就把它们买下来呀。", "t": [48638, 53325]}, {"ru": "«Этот взрослый, — подумал про себя маленький принц, — рассуждает почти как тот пьяница».", "zh": "” 小王子心想：“这个人的推理方法有点像我见过的那个酒鬼。", "t": [53325, 59550]}, {"ru": "Тем не менее он спросил еще кое о чем: — Как можно владеть звездами?", "zh": "” 他仍然提出问题： “怎样才能拥有星星？", "t": [59550, 64712]}, {"ru": "— А чьи они?", "zh": "” 商人烦了，没好气地反问： “你说，这满天的星星属于谁？", "t": [64712, 66662]}, {"ru": "— проворчал в ответ бизнесмен.", "zh": "” 商人烦了，没好气地反问： “你说，这满天的星星属于谁？", "t": [66662, 69312]}, {"ru": "— Я не знаю.", "zh": "” “我不知道。", "t": [69312, 71225]}, {"ru": "Наверно, ничьи.", "zh": "” “我不知道。", "t": [71225, 73812]}, {"ru": "— Тогда они будут моими, раз я первый догадался ими владеть.", "zh": "” “那么它们属于我。", "t": [73812, 78212]}, {"ru": "— И этого достаточно?", "zh": "因为我是第一个想到要拥有它们的人。", "t": [78212, 79637]}]}, {"id": "ch13p03", "audio": true, "sents": [{"ru": "— Вполне!", "zh": "因为我是第一个想到要拥有它们的人。", "t": [100, 1750]}, {"ru": "Ведь если ты найдешь алмаз, который никому не принадлежит, он станет твоим.", "zh": "” “光是想就行了吗？", "t": [1750, 7150]}, {"ru": "И если ты откроешь ничейный остров, он тоже станет твоим.", "zh": "你发现一颗没有主人的钻石，这颗钻石就归你了。", "t": [7150, 11812]}, {"ru": "А если тебе первому в голову приходит какая-то идея, ты ее патентуешь, и тогда она твоя.", "zh": "你发现一个不属于任何人的岛，这岛就是你的了。", "t": [11812, 18138]}, {"ru": "Я владею звездами просто потому, что раньше еще никому не приходило в голову ими завладеть.", "zh": "你头一个想出一个主意，你就可以申请专利，这个主意就是你的了。", "t": [18138, 24188]}, {"ru": "— Это правда, — сказал маленький принц.", "zh": "而我呢，我拥有星星，因为在我之前没有一个人想过要拥有星星。", "t": [24188, 27462]}, {"ru": "— И что ты с ними делаешь?", "zh": "” “这倒是真的。", "t": [27462, 29950]}, {"ru": "— Я ими распоряжаюсь.", "zh": "”小王子想。", "t": [29950, 32438]}, {"ru": "Считаю их и пересчитываю, — ответил бизнесмен.", "zh": "“你要星星做什么用？", "t": [32438, 36488]}, {"ru": "— Это трудно, но я человек серьезный.", "zh": "我数它们，一次又一次地数它们。", "t": [36488, 39700]}, {"ru": "Однако маленькому принцу было все-таки кое-что не ясно.", "zh": "”商人说。", "t": [39700, 43738]}, {"ru": "— Если я владею шейным платком, я могу им распорядиться — повязать на шею и уйти с ним.", "zh": "“这是件困难的事，但我是个正经人！", "t": [43738, 49750]}, {"ru": "Если мне принадлежит цветок, я могу его сорвать и унести.", "zh": "” 小王子对这个回答还不满意： “我若拥有一条围巾，我可以把它围在脖子上带走；我若拥有一朵花，我可以把它摘下带走；可你摘不下星星呀！", "t": [49750, 54338]}, {"ru": "Но ты ведь не можешь собрать звезды!", "zh": "” 小王子对这个回答还不满意： “我若拥有一条围巾，我可以把它围在脖子上带走；我若拥有一朵花，我可以把它摘下带走；可你摘不下星星呀！", "t": [54338, 57300]}, {"ru": "— Не могу.", "zh": "” “我不能摘星星，但我能把它们存入银行。", "t": [57300, 58962]}, {"ru": "Зато я могу поместить их в банк.", "zh": "” “我不能摘星星，但我能把它们存入银行。", "t": [58962, 62112]}, {"ru": "— Как это?", "zh": "” “我不能摘星星，但我能把它们存入银行。", "t": [62112, 63750]}, {"ru": "Что это значит?", "zh": "” “我不能摘星星，但我能把它们存入银行。", "t": [63750, 65900]}, {"ru": "— Это значит, что я записываю на бумажке количество моих звезд, помещаю эту бумажку в ящик и запираю его на ключ.", "zh": "” “我在一张小纸条上写上我的星星的数目，然后把它锁进抽屉里。", "t": [65900, 73400]}, {"ru": "— И все?", "zh": "” “就这样？", "t": [73400, 75038]}, {"ru": "— Этого достаточно.", "zh": "” “就这样？", "t": [75038, 77288]}, {"ru": "«Это забавно, — подумал маленький принц.", "zh": "” “这就行啦！", "t": [77288, 80600]}, {"ru": "— Звучит красиво, но не слишком серьезно».", "zh": "” 小王子想：“这倒是挺好玩的，还挺有诗意的呢，但算不上是严肃正经的事儿。", "t": [80600, 84262]}, {"ru": "В отличие от взрослых маленький принц имел совсем другие представления о серьезных вещах.", "zh": "” 小王子想：“这倒是挺好玩的，还挺有诗意的呢，但算不上是严肃正经的事儿。", "t": [84262, 89413]}]}, {"id": "ch13p04", "audio": true, "sents": [{"ru": "— Вот я, — заметил он снова, — владею цветком, который поливаю каждый день.", "zh": "” 对“严肃正经的事儿”，小王子的看法与大人的看法极不相同。", "t": [100, 5462]}, {"ru": "У меня есть три вулкана, которые я прочищаю каждую неделю.", "zh": "小王子说：“我呢，我拥有一朵花，我就天天给它浇水；我拥有三座火山，我就每个星期给它们疏通清理。", "t": [5462, 10238]}, {"ru": "Я чищу также и потухший вулкан.", "zh": "小王子说：“我呢，我拥有一朵花，我就天天给它浇水；我拥有三座火山，我就每个星期给它们疏通清理。", "t": [10238, 13450]}, {"ru": "Просто так — на всякий случай.", "zh": "我也疏通死火山，因为日后的事难说。", "t": [13450, 16600]}, {"ru": "Моим вулканам и моему цветку идет на пользу, что я ими владею.", "zh": "我也疏通死火山，因为日后的事难说。", "t": [16600, 21588]}, {"ru": "Но какая польза от тебя звездам?", "zh": "我能做对火山、对花有益的事，才叫做拥有它们。", "t": [21588, 24625]}, {"ru": "Бизнесмен открыл рот, но так ничего и не ответил.", "zh": "但你却不给星星做有益的事。", "t": [24625, 28750]}, {"ru": "А маленький принц отправился дальше.", "zh": "” 商人张口结舌，找不到话回答。", "t": [28750, 31912]}, {"ru": "«Определенно, взрослые совершенно необыкновенные создания», — повторял он мысленно по дороге.", "zh": "“大人们真是怪得没法说。", "t": [31912, 37400]}]}]}, {"id": "ch14", "title_ru": "Глава 14", "title_zh": "第 14 章", "paras": [{"id": "ch14p00", "audio": true, "sents": [{"ru": "Пятая планета оказалась самой забавной.", "zh": "第五颗星球稀奇古怪，它是熠熠繁星中最小的一颗，它仅能容纳一盏路灯和一个点灯人。", "t": [100, 3500]}, {"ru": "Она была самой маленькой из им увиденных.", "zh": "第五颗星球稀奇古怪，它是熠熠繁星中最小的一颗，它仅能容纳一盏路灯和一个点灯人。", "t": [3500, 6912]}, {"ru": "Места на ней хватало только для фонаря и фонарщика.", "zh": "第五颗星球稀奇古怪，它是熠熠繁星中最小的一颗，它仅能容纳一盏路灯和一个点灯人。", "t": [6912, 10962]}, {"ru": "Маленький принц не мог понять, зачем где-то в небе, на планете без домов и жителей, нужны фонарь и фонарщик.", "zh": "小王子怎么想都想不明白，这颗位于太空中不起眼的星球，既没有房屋，又没有居民，这路灯和点灯人有何用途。", "t": [10962, 18425]}, {"ru": "Тем не менее он подумал — может, этот человек и странный, однако он не менее странен, чем король, бизнесмен и пьяница.", "zh": "他想：“这个点灯人也许古怪，然而他不会比国王、爱慕虚荣的人、商人、酒鬼更荒谬吧，至少他干的工作还有意义。", "t": [18425, 26475]}, {"ru": "По крайней мере, его работа имеет какой-то смысл.", "zh": "他想：“这个点灯人也许古怪，然而他不会比国王、爱慕虚荣的人、商人、酒鬼更荒谬吧，至少他干的工作还有意义。", "t": [26475, 30388]}, {"ru": "Когда он зажигает свой фонарь, кажется, что загорается еще одна звезда или распускается новый цветок.", "zh": "他点亮路灯，如同给太空增添一颗星星，或一朵鲜花；他熄灭路灯，就是让花儿和星星休息睡眠。", "t": [30388, 37188]}, {"ru": "А когда он гасит фонарь, кажется, что звезда или цветок засыпают.", "zh": "他点亮路灯，如同给太空增添一颗星星，或一朵鲜花；他熄灭路灯，就是让花儿和星星休息睡眠。", "t": [37188, 42312]}, {"ru": "Это приятная работа.", "zh": "他点亮路灯，如同给太空增添一颗星星，或一朵鲜花；他熄灭路灯，就是让花儿和星星休息睡眠。", "t": [42312, 44800]}, {"ru": "Она полезна, потому что порождает красоту.", "zh": "这活儿充满诗意，既然充满诗意，那就是有益的工作。", "t": [44800, 48450]}, {"ru": "Подлетев к этой планете, маленький принц вежливо поприветствовал фонарщика.", "zh": "这活儿充满诗意，既然充满诗意，那就是有益的工作。", "t": [48450, 53500]}, {"ru": "— Добрый день, — сказал он.", "zh": "” 他走近星球，毕恭毕敬地向点灯人行礼： “你好。", "t": [53500, 56275]}, {"ru": "— Почему ты только что погасил свой фонарь?", "zh": "你刚才为什么把灯灭了？", "t": [56275, 59450]}, {"ru": "— Таково правило, — ответил фонарщик.", "zh": "” “这是规定。", "t": [59450, 62888]}, {"ru": "— Доброе утро.", "zh": "”点灯人答道。", "t": [62888, 65012]}, {"ru": "— Какое правило?", "zh": "”点灯人答道。", "t": [65012, 67012]}, {"ru": "— Надо погасить фонарь.", "zh": "“早上好。", "t": [67012, 69362]}, {"ru": "Добрый вечер!", "zh": "” “什么规定？", "t": [69362, 71312]}, {"ru": "При этих словах он зажег свой фонарь.", "zh": "” “熄灯的规定。", "t": [71312, 74538]}, {"ru": "— А почему ты снова зажег его?", "zh": "” 他点上灯。", "t": [74538, 77262]}, {"ru": "— спросил маленький принц.", "zh": "“你怎么又把灯点着了？", "t": [77262, 79888]}, {"ru": "— Таково правило, — ответил фонарщик.", "zh": "” “这是规定。", "t": [79888, 83312]}, {"ru": "— Я не понимаю…", "zh": "”点灯人说。", "t": [83312, 84500]}, {"ru": "— сказал маленький принц.", "zh": "“我不明白。", "t": [84500, 85988]}]}, {"id": "ch14p01", "audio": true, "sents": [{"ru": "— Нечего тут понимать, — сказал фонарщик.", "zh": "”小王子说。", "t": [100, 3862]}, {"ru": "— Правила есть правила.", "zh": "“用不着明白，”点灯人说，“规定就是规定。", "t": [3862, 6238]}, {"ru": "Доброе утро!", "zh": "“用不着明白，”点灯人说，“规定就是规定。", "t": [6238, 8312]}, {"ru": "И он снова погасил свой фонарь.", "zh": "早上好。", "t": [8312, 10338]}]}, {"id": "ch14p02", "audio": true, "sents": [{"ru": "Потом он вытер свой лоб красным клетчатым платком.", "zh": "” 他灭掉路灯。", "t": [100, 3900]}, {"ru": "— Эта ужасная работа изматывает.", "zh": "“这活儿可把我累苦了。", "t": [3900, 7100]}, {"ru": "Раньше было легче.", "zh": "“这活儿可把我累苦了。", "t": [7100, 9425]}, {"ru": "Я гасил фонарь по утрам и зажигал его вечером.", "zh": "从前的规定还合乎情理，早上熄灯，晚上点灯。", "t": [9425, 13225]}, {"ru": "Днем я мог отдохнуть, а ночью выспаться.", "zh": "从前的规定还合乎情理，早上熄灯，晚上点灯。", "t": [13225, 16962]}, {"ru": "— С той поры изменились правила?", "zh": "熄灯之后休息，点灯之后睡觉……” “现在的规定改了？", "t": [16962, 19912]}, {"ru": "— спросил маленький принц.", "zh": "熄灯之后休息，点灯之后睡觉……” “现在的规定改了？", "t": [19912, 22550]}, {"ru": "— Правила не изменились, — вздохнул фонарщик.", "zh": "” “规定倒没有改，”点灯人说，“倒霉就倒霉在这儿！", "t": [22550, 26425]}, {"ru": "— В этом-то и беда.", "zh": "” “规定倒没有改，”点灯人说，“倒霉就倒霉在这儿！", "t": [26425, 28788]}, {"ru": "С каждым годом эта планета вращается все быстрее, а правила остались прежними.", "zh": "行星一年转得比一年快，而规定却没有改变！", "t": [28788, 34488]}, {"ru": "— И что теперь?", "zh": "行星一年转得比一年快，而规定却没有改变！", "t": [34488, 36450]}, {"ru": "— спросил маленький принц.", "zh": "” “这是怎么回事？", "t": [36450, 39062]}, {"ru": "— Теперь она делает оборот каждую минуту, и у меня нет ни секунды для отдыха.", "zh": "” “现在它一分钟转一次，我连一秒钟的休息时间都没有。", "t": [39062, 44350]}, {"ru": "Раз в минуту я зажигаю и гашу этот фонарь.", "zh": "每分钟要点亮、熄灭一次灯火！", "t": [44350, 48075]}, {"ru": "— Это забавно!", "zh": "每分钟要点亮、熄灭一次灯火！", "t": [48075, 49975]}, {"ru": "Значит, сутки у тебя длятся всего минуту?", "zh": "” “这怎么可能呢？", "t": [49975, 53738]}, {"ru": "— Это совсем не забавно!", "zh": "你这儿一分钟就是一天？", "t": [53738, 56162]}, {"ru": "— ответил фонарщик.", "zh": "你这儿一分钟就是一天？", "t": [56162, 58525]}, {"ru": "— Мы с тобой разговариваем уже целый месяц!", "zh": "” “怎么不可能，”点灯人说，“我们已经聊了一个月了。", "t": [58525, 62062]}, {"ru": "— Месяц?", "zh": "” “怎么不可能，”点灯人说，“我们已经聊了一个月了。", "t": [62062, 63712]}, {"ru": "— Ну, да.", "zh": "” “怎么不可能，”点灯人说，“我们已经聊了一个月了。", "t": [63712, 65775]}, {"ru": "Тридцать дней.", "zh": "” “怎么不可能，”点灯人说，“我们已经聊了一个月了。", "t": [65775, 67712]}, {"ru": "Добрый вечер!", "zh": "” “一个月？", "t": [67712, 69675]}, {"ru": "И фонарщик опять зажег свой фонарь.", "zh": "” “一个月？", "t": [69675, 72762]}, {"ru": "Маленький принц задумчиво посмотрел на фонарщика.", "zh": "” “是的，三十分钟，就是三十天！", "t": [72762, 76675]}, {"ru": "Ему нравился этот человек, который не отступал от своих правил.", "zh": "” 点灯人又点亮了路灯。", "t": [76675, 81575]}, {"ru": "Он вспомнил, как и сам раньше не раз передвигал свой стул, наблюдая за закатами на своей планете.", "zh": "小王子看着他，小王子喜欢这个一丝不苟，按章办事的点灯人。", "t": [81575, 87925]}, {"ru": "И маленькому принцу захотелось помочь своему новому знакомому.", "zh": "他记起自己以前必须挪动椅子才能看到日落的情景。", "t": [87925, 92438]}, {"ru": "— Послушай, — сказал он, — кажется, я знаю, как ты сможешь отдыхать, когда захочешь.", "zh": "他很愿意帮助他的朋友。", "t": [92438, 97737]}]}, {"id": "ch14p03", "audio": true, "sents": [{"ru": "— Мне все время этого хочется.", "zh": "“你知道吗……我有个办法，你什么时候想休息就可以休息……” “我一直想找个办法呢。", "t": [100, 3100]}, {"ru": "Ведь можно же быть одновременно верным слову и немного лениться.", "zh": "”点灯人说。", "t": [3100, 7600]}, {"ru": "— Смотри, — продолжил маленький принц.", "zh": "有个办法既能按章办事又能偷懒就好了。", "t": [7600, 10962]}, {"ru": "— Твоя планета такая маленькая, что ты можешь обойти ее за три шага.", "zh": "小王子继续说道： “你的星球这么小，走三步就绕了一个圈。", "t": [10962, 15850]}, {"ru": "И если ты пойдешь достаточно медленно, ты все время будешь оставаться на солнце.", "zh": "你只要放慢脚步，太阳就老在你的头顶上。", "t": [15850, 21012]}, {"ru": "Захочешь отдохнуть от своей работы — просто пойди вперед, и твой день будет длиться, сколько пожелаешь.", "zh": "你想休息的时候，你就往前走……你的白天要多长有多长。", "t": [21012, 27450]}, {"ru": "— От этого будет мало проку, — вздохнул фонарщик.", "zh": "” “这个办法解决不了我多大的问题，”点灯人说，“我平生喜欢的就是睡觉。", "t": [27450, 31462]}, {"ru": "— Мне бы выспаться как следует.", "zh": "” “这个办法解决不了我多大的问题，”点灯人说，“我平生喜欢的就是睡觉。", "t": [31462, 34275]}, {"ru": "Вот чего я хочу!", "zh": "” “这个办法解决不了我多大的问题，”点灯人说，“我平生喜欢的就是睡觉。", "t": [34275, 36600]}, {"ru": "— Да, плохо твое дело, — посочувствовал маленький принц.", "zh": "” “那你就太不走运了。", "t": [36600, 40962]}, {"ru": "— Да, не повезло, — ответил фонарщик.", "zh": "”小王子说。", "t": [40962, 44538]}, {"ru": "— Доброе утро!", "zh": "“我真的不走运。", "t": [44538, 46612]}, {"ru": "И он опять погасил свой фонарь.", "zh": "”点灯人说。", "t": [46612, 49488]}, {"ru": "«Наверняка этого взрослого, — подумал маленький принц, продолжив свое путешествие, — невзлюбили бы остальные: король, честолюбец, пьяница и бизнесмен.", "zh": "小王子一面赶路一面想：“这个人会被其他人瞧不起的。", "t": [49488, 59500]}, {"ru": "Тем не менее он не кажется мне нелепым.", "zh": "会被国王、爱慕虚荣的人、酒鬼、商人瞧不起。", "t": [59500, 62812]}, {"ru": "Возможно потому, что он занят своим делом, а не самим собой».", "zh": "可是他是惟一的我不觉得可笑的人，也许因为他没有光顾自己吧！", "t": [62812, 67488]}, {"ru": "При этом маленький принц вздохнул и добавил про себя: «Это единственный взрослый, который мог бы стать мне другом.", "zh": "可是他是惟一的我不觉得可笑的人，也许因为他没有光顾自己吧！", "t": [67488, 74462]}, {"ru": "Но его планета так мала, что двоим места на ней просто не хватит…»", "zh": "” 他惋惜地叹口气，又想： “这个人本来是惟一可做我的朋友的人，但他的星球实在太小了，搁不下两个人……” 小王子不敢承认，他对这颗星球颇有好感的原因是，它得天独厚，二十四小时之内就可以观看一千四百四十次日落。", "t": [74462, 79500]}, {"ru": "Маленький принц не мог себе откровенно признаться, что он сожалеет об этой прекрасной планете просто потому, что он мог бы увидеть на ней тысячу четыреста сорок закатов за двадцать четыре часа!", "zh": "” 他惋惜地叹口气，又想： “这个人本来是惟一可做我的朋友的人，但他的星球实在太小了，搁不下两个人……” 小王子不敢承认，他对这颗星球颇有好感的原因是，它得天独厚，二十四小时之内就可以观看一千四百四十次日落。", "t": [79500, 89326]}]}]}, {"id": "ch15", "title_ru": "Глава 15", "title_zh": "第 15 章", "paras": [{"id": "ch15p00", "audio": true, "sents": [{"ru": "Шестая планета была в десять раз больше.", "zh": "第六颗星球比刚才那颗大十倍。", "t": [100, 3438]}, {"ru": "На ней жил старый господин, который писал толстенные книги.", "zh": "星球上住着一位老先生，正在撰写大部头著作。", "t": [3438, 7250]}]}, {"id": "ch15p01", "audio": true, "sents": [{"ru": "— Ага!", "zh": "看见小王子，他大声嚷： “嗬！", "t": [100, 1562]}, {"ru": "— воскликнул он, заметив маленького принца.", "zh": "看见小王子，他大声嚷： “嗬！", "t": [1562, 5288]}, {"ru": "— Вот и путешественник!", "zh": "来了一个勘探人员！", "t": [5288, 7875]}, {"ru": "Маленький принц присел за стол, чтобы немного отдышаться.", "zh": "” 小王子有点气喘，坐在桌子上。", "t": [7875, 12388]}, {"ru": "Ведь он уже проделал такой длинный путь.", "zh": "他赶了大老远的路呢！", "t": [12388, 15650]}, {"ru": "— Ты откуда?", "zh": "“你从哪儿来？", "t": [15650, 17462]}, {"ru": "— спросил его старый господин.", "zh": "”老先生问他。", "t": [17462, 20238]}, {"ru": "— А что это за толстая книга?", "zh": "”小王子问。", "t": [20238, 22938]}, {"ru": "— спросил его в ответ маленький принц.", "zh": "“您在这儿干什么？", "t": [22938, 26100]}, {"ru": "— И что вы тут делаете?", "zh": "” “我是地理学家。", "t": [26100, 28462]}, {"ru": "— Я географ, — ответил старик.", "zh": "”老先生说。", "t": [28462, 31700]}, {"ru": "— А кто такой географ?", "zh": "“什么叫‘地理学家’？", "t": [31700, 34025]}, {"ru": "— Это ученый, который знает, где находятся моря, где расположены реки, города, горы и пустыни.", "zh": "” “地理学家是学者，知道哪儿有大海、江河、城市、山脉、沙漠。", "t": [34025, 41212]}, {"ru": "— Здорово!", "zh": "” “这倒挺有趣的。", "t": [41212, 42925]}, {"ru": "— воскликнул маленький принц.", "zh": "”小王子说。", "t": [42925, 45662]}, {"ru": "— Это отличная профессия.", "zh": "“总算是真正的职业！", "t": [45662, 47738]}]}, {"id": "ch15p02", "audio": true, "sents": [{"ru": "При этом он окинул восхищенным взором планету географа.", "zh": "”他环顾地理学家的行星。", "t": [100, 4162]}, {"ru": "Он еще ни разу не видел таких величественных планет.", "zh": "他从未见过这样豪华的行星。", "t": [4162, 8025]}, {"ru": "— Какая она красивая, ваша планета!", "zh": "这儿有大洋吗？", "t": [8025, 11412]}, {"ru": "У нее есть океаны?", "zh": "” “我不可能知道这事。", "t": [11412, 13850]}, {"ru": "— Мне это неизвестно, — ответил географ.", "zh": "”地理学家说。", "t": [13850, 17362]}, {"ru": "— Вот как…", "zh": "“啊（小王子有点失望）！", "t": [17362, 18425]}, {"ru": "— маленький принц был слегка разочарован.", "zh": "有山脉吗？", "t": [18425, 21462]}, {"ru": "— А горы?", "zh": "” “我不可能知道。", "t": [21462, 23088]}, {"ru": "— И это мне неизвестно, — отвечал географ.", "zh": "”地理学家说。", "t": [23088, 26588]}, {"ru": "— А города, реки и пустыни?", "zh": "“有城市、河流、沙漠吗？", "t": [26588, 29825]}, {"ru": "— Это мне тоже неизвестно, — ответил географ.", "zh": "” “我也不可能知道。", "t": [29825, 33462]}, {"ru": "— Но вы же географ!", "zh": "“可你是地理学家啊！", "t": [33462, 35700]}, {"ru": "— Это верно, но я не путешественник.", "zh": "“可你是地理学家啊！", "t": [35700, 38788]}, {"ru": "Мне их так не хватает.", "zh": "” “不错，”地理学家说，“但我不是勘探人员。", "t": [38788, 41375]}, {"ru": "Ведь не географы изучают города, реки, горы, моря, океаны и пустыни.", "zh": "我这儿很缺勘探人员。", "t": [41375, 47725]}, {"ru": "Географ — слишком важная персона, чтобы слоняться там или сям.", "zh": "计算城市、江河、山脉、大海、大洋、沙漠的数目，不是地理学家干的事。", "t": [47725, 52938]}, {"ru": "Он не покидает стен своего кабинета.", "zh": "地理学家太重要了，没有工夫四处闲逛。", "t": [52938, 56162]}, {"ru": "Зато он принимает у себя путешественников.", "zh": "地理学家太重要了，没有工夫四处闲逛。", "t": [56162, 59700]}, {"ru": "Он расспрашивает их и записывает их рассказы.", "zh": "他必须寸步不离办公室。", "t": [59700, 63325]}, {"ru": "И если какой-нибудь рассказ покажется ему интересным, географ поручает навести справки, можно ли этому рассказчику верить.", "zh": "他在办公室接见勘探人员，询问他们，记下他们的回忆。", "t": [63325, 70838]}, {"ru": "— Это зачем?", "zh": "勘探人员引起了地理学家的兴趣，地理学家就要调查这位勘探人员的品质。", "t": [70838, 72575]}, {"ru": "— Потому что если путешественник подвирает, это приведет к полнейшей путанице в учебниках по географии.", "zh": "” “为什么？", "t": [72575, 79088]}, {"ru": "К тому же вдруг он окажется пьяницей?", "zh": "” “一个撒谎的勘探人员会给地理学家的书带来灾难，酒喝得太多的也不行。", "t": [79088, 82188]}, {"ru": "— И что тогда?", "zh": "” “为什么？", "t": [82188, 84100]}, {"ru": "— поинтересовался маленький принц.", "zh": "” “为什么？", "t": [84100, 87038]}, {"ru": "— У пьяниц все двоится в глазах.", "zh": "” “酒鬼看的东西是重叠的，地理学家就会在有一座山的地方记下两座山。", "t": [87038, 89912]}, {"ru": "В результате географ опишет две горы там, где всего одна.", "zh": "” “酒鬼看的东西是重叠的，地理学家就会在有一座山的地方记下两座山。", "t": [89912, 93537]}]}, {"id": "ch15p03", "audio": true, "sents": [{"ru": "— Я был знаком с одним пьяницей, — заметил маленький принц.", "zh": "” 小王子说：“我认识一个人，他会成为糟糕的勘探员。", "t": [100, 4588]}, {"ru": "— Из него и впрямь вышел бы плохой путешественник.", "zh": "” “很可能。", "t": [4588, 8162]}, {"ru": "— Наверняка.", "zh": "勘探人员的品质不错，我就调查他的发现。", "t": [8162, 10062]}, {"ru": "Но если путешественнику можно верить, надо навести справки о его открытии.", "zh": "” “你亲自去实地调查吗？", "t": [10062, 15562]}, {"ru": "— Надо пойти и посмотреть, что он открыл?", "zh": "” “不，那太复杂了。", "t": [15562, 19100]}, {"ru": "— Нет.", "zh": "我要求勘探人员提供证据。", "t": [19100, 20612]}, {"ru": "Это слишком хлопотно.", "zh": "我要求勘探人员提供证据。", "t": [20612, 23112]}, {"ru": "От путешественника требуют доказательств.", "zh": "比如说，他发现了一座大山，我就要求他带大石来。", "t": [23112, 26525]}, {"ru": "Например, если речь идет о большой горе, надо, чтобы он оттуда принес большие камни.", "zh": "” 地理学家突然兴奋起来： “你呢，你是从远方来的！", "t": [26525, 32538]}, {"ru": "При этих словах географ неожиданно разволновался.", "zh": "你是勘探队员！", "t": [32538, 36338]}, {"ru": "— А ты же прибыл издалека?", "zh": "你给我描写你的星球吧！", "t": [36338, 38988]}, {"ru": "Ты же путешественник!", "zh": "” 地理学家打开他的登记册，削尖铅笔。", "t": [38988, 41312]}, {"ru": "Ты мне расскажешь о своей планете!", "zh": "” 地理学家打开他的登记册，削尖铅笔。", "t": [41312, 44288]}, {"ru": "При этих словах географ открыл свой толстенный каталог и подточил карандаш.", "zh": "他先用铅笔记下勘探人员的口述。", "t": [44288, 49625]}, {"ru": "Ведь рассказы путешественников сперва записывают карандашом.", "zh": "“请谈吧！", "t": [49625, 54000]}, {"ru": "Чтобы записать их чернилами, надо дождаться представленных доказательств.", "zh": "“啊！", "t": [54000, 59162]}, {"ru": "— Ну?", "zh": "我们那儿，可没意思了，”小王子说，“它才一点大，我有三座火山：两座活火山，一座死火山，可谁知道以后会有什么变化呢。", "t": [59162, 60525]}, {"ru": "— поторопил географ.", "zh": "我们那儿，可没意思了，”小王子说，“它才一点大，我有三座火山：两座活火山，一座死火山，可谁知道以后会有什么变化呢。", "t": [60525, 62800]}, {"ru": "— У меня на планете, — сказал маленький принц, — не так уж много интересного.", "zh": "我们那儿，可没意思了，”小王子说，“它才一点大，我有三座火山：两座活火山，一座死火山，可谁知道以后会有什么变化呢。", "t": [62800, 67975]}, {"ru": "Там все очень маленькое.", "zh": "” “以后的事谁知道呢。", "t": [67975, 70900]}, {"ru": "Есть три вулкана — два работают, а один потухший.", "zh": "”地理学家说。", "t": [70900, 75088]}, {"ru": "Но ведь никогда не знаешь, что может случиться.", "zh": "” “我们不记录花的。", "t": [75088, 79038]}, {"ru": "— Это верно, — заметил географ.", "zh": "”地理学家说。", "t": [79038, 82088]}, {"ru": "— У меня также есть цветок.", "zh": "“为什么不记录花呢？", "t": [82088, 84888]}, {"ru": "— Нас не интересуют цветы, — сказал географ.", "zh": "” “因为它‘昙花一现’。", "t": [84888, 88712]}, {"ru": "— Но почему?", "zh": "” “因为它‘昙花一现’。", "t": [88712, 90550]}, {"ru": "Они же такие красивые!", "zh": "” “什么叫做‘昙花一现’？", "t": [90550, 93038]}, {"ru": "— Потому, что цветы эфемерны.", "zh": "” “什么叫做‘昙花一现’？", "t": [93038, 96212]}, {"ru": "— Что значит «эфемерны»?", "zh": "” “地理书是一切书籍中最珍贵的书籍，从不会过时。", "t": [96212, 97900]}]}, {"id": "ch15p04", "audio": true, "sents": [{"ru": "— Книги по географии, — сказал географ, — самые ценные на свете.", "zh": "” “地理书是一切书籍中最珍贵的书籍，从不会过时。", "t": [100, 5150]}, {"ru": "Они никогда не устаревают.", "zh": "山移位，海洋干枯都是极少发生的事。", "t": [5150, 7825]}, {"ru": "Ведь редко так бывает, чтобы гора сдвинулась с места.", "zh": "我们写的是永恒不变的东西。", "t": [7825, 12088]}, {"ru": "Да и океаны пересыхают очень редко.", "zh": "” “可是死火山也会复苏。", "t": [12088, 15438]}, {"ru": "Мы пишем о вещах вечных.", "zh": "”小王子打断他的话。", "t": [15438, 18250]}, {"ru": "— Но ведь потухший вулкан может проснуться, — перебил маленький принц.", "zh": "“什么叫做‘昙花一现’？", "t": [18250, 22975]}, {"ru": "— Что же такое «эфемерный»?", "zh": "” “火山死与不死，在我们看来都是一回事。", "t": [22975, 26075]}, {"ru": "— Для нас, географов, потухший вулкан или действующий — все едино, — пояснил географ.", "zh": "“我们重视的是山，山不会改变。", "t": [26075, 32688]}, {"ru": "Для нас важна сама гора.", "zh": "” “什么叫做‘昙花一现’？", "t": [32688, 35388]}, {"ru": "Он не меняется.", "zh": "”小王子继续追问。", "t": [35388, 37588]}, {"ru": "— И все-таки что значит «эфемерный»?", "zh": "”小王子继续追问。", "t": [37588, 40888]}, {"ru": "— снова повторил маленький принц.", "zh": "他素来如此，一旦提出一个问题，绝不肯放弃。", "t": [40888, 43825]}, {"ru": "Ведь стоило ему задать вопрос, и он уже не отступал.", "zh": "“‘昙花一现’的意思就是‘面临很快消失的危险’。", "t": [43825, 47788]}, {"ru": "— Такой, чему грозит скорое исчезновение.", "zh": "“‘昙花一现’的意思就是‘面临很快消失的危险’。", "t": [47788, 51575]}, {"ru": "— Значит, моему цветку грозит исчезновение?", "zh": "” “我的花儿也有很快消失的危险吗？", "t": [51575, 55588]}, {"ru": "— Разумеется.", "zh": "” “当然。", "t": [55588, 57562]}, {"ru": "«Мой цветок эфемерен!", "zh": "” “当然。", "t": [57562, 60025]}, {"ru": "— подумал при этом маленький принц.", "zh": "” “我的花会‘昙花一现’，”小王子想，“而她只有四根刺保护自己，应付这个世界！", "t": [60025, 62900]}, {"ru": "— И у него всего четыре шипа, чтобы защищаться от целого мира!", "zh": "” “我的花会‘昙花一现’，”小王子想，“而她只有四根刺保护自己，应付这个世界！", "t": [62900, 67550]}, {"ru": "А я его оставил дома совершенно одного!»", "zh": "我却抛弃了她，让她孤苦伶仃地待在我家！", "t": [67550, 71150]}, {"ru": "В этот момент он впервые пожалел, что покинул свою планету.", "zh": "” 他头一次体会到悔恨的感觉。", "t": [71150, 75650]}, {"ru": "Но он сумел взять себя в руки.", "zh": "然而他还是鼓起勇气问： “您能否指点我，我该去哪儿访问？", "t": [75650, 78600]}, {"ru": "— Какие места вы мне посоветуете посетить?", "zh": "然而他还是鼓起勇气问： “您能否指点我，我该去哪儿访问？", "t": [78600, 81962]}, {"ru": "— спросил он географа.", "zh": "然而他还是鼓起勇气问： “您能否指点我，我该去哪儿访问？", "t": [81962, 84600]}, {"ru": "— Планету Земля, — ответил тот.", "zh": "” “到地球上去吧，”地理学家说，“它非常有名……” 小王子走了，一路上都在思念他的花儿。", "t": [84600, 87662]}, {"ru": "— У нее неплохая репутация…", "zh": "” “到地球上去吧，”地理学家说，“它非常有名……” 小王子走了，一路上都在思念他的花儿。", "t": [87662, 90675]}, {"ru": "И маленький принц снова пустился в путь, думая о своем покинутом цветке.", "zh": "” “到地球上去吧，”地理学家说，“它非常有名……” 小王子走了，一路上都在思念他的花儿。", "t": [90675, 95000]}]}]}, {"id": "ch16", "title_ru": "Глава 16", "title_zh": "第 16 章", "paras": [{"id": "ch16p00", "audio": true, "sents": [{"ru": "Так, по совету географа, седьмой планетой, которую посетил маленький принц, стала Земля.", "zh": "地球可不是等闲之辈！", "t": [100, 6550]}, {"ru": "Эта планета совсем особенная.", "zh": "地球可不是等闲之辈！", "t": [6550, 9712]}, {"ru": "На ней живут сто одиннадцать королей, не считая королей африканских, семь тысяч географов, девятьсот тысяч бизнесменов, семь с половиной миллионов пьяниц, триста одиннадцать миллионов честолюбцев и около двух миллиардов взрослых.", "zh": "地球上有一百一十一位国王（我当然没有忘记算上黑人国王）、七千位地理学家、九十万个商人、七百五十万个酒鬼、三亿一千一百万个爱慕虚荣的人，也就是说，约莫有二十亿个大人。", "t": [9712, 23375]}, {"ru": "Чтобы вы смогли представить, как велика Земля, я скажу, что до изобретения электричества на шести континентах там работала настоящая армия фонарщиков — четыреста шестьдесят две тысячи пятьсот одиннадцать человек!", "zh": "我告诉你们，世界上还没有人发明电的时候，六大洲需要维持一支由四十六万二千五百一十一个点灯人组成的真正大军。", "t": [23375, 35750]}, {"ru": "Со стороны их действия смотрелись великолепно.", "zh": "从稍远处眺望这支大军，真是蔚为壮观。", "t": [35750, 39438]}, {"ru": "Согласованное движение армии фонарщиков напоминало балет.", "zh": "从稍远处眺望这支大军，真是蔚为壮观。", "t": [39438, 43938]}, {"ru": "Сначала свое дело начинали фонарщики Новой Зеландии и Австралии.", "zh": "点灯人的动作犹如芭蕾舞演员的动作：整齐划一，井然有序。", "t": [43938, 48812]}, {"ru": "Засветив свои фонари, они уходили спать.", "zh": "首先上场的是新西兰、澳大利亚的点灯人，他们点亮路灯后就去睡觉。", "t": [48812, 52588]}, {"ru": "Потом приступали к работе фонарщики Китая и Сибири.", "zh": "首先上场的是新西兰、澳大利亚的点灯人，他们点亮路灯后就去睡觉。", "t": [52588, 56600]}, {"ru": "Затем они также скрывались за кулисами.", "zh": "接着加入舞蹈行列的是中国和西伯利亚的点灯人，然后他们也隐没于后台。", "t": [56600, 60075]}, {"ru": "Тогда наступала очередь фонарщиков России и Индии, затем — Африки и Европы.", "zh": "接着加入舞蹈行列的是中国和西伯利亚的点灯人，然后他们也隐没于后台。", "t": [60075, 66412]}, {"ru": "Им на смену появлялись фонарщики Южной и Северной Америки.", "zh": "然后轮到俄罗斯和印度的点灯人，接着是非洲和欧洲的，然后是南美洲、北美洲。", "t": [66412, 71038]}, {"ru": "Порядок этого величественного парада никогда не нарушался.", "zh": "这支大军的进场顺序从不错乱，真是让人叹为观止。", "t": [71038, 75112]}, {"ru": "Это было грандиозное зрелище!", "zh": "这支大军的进场顺序从不错乱，真是让人叹为观止。", "t": [75112, 77912]}, {"ru": "Лишь фонарщик на Северном полюсе и его собрат на Южном вели неспешную, праздную жизнь.", "zh": "惟有北极点灯人和他的南极同行，过着悠闲懒散的生活。", "t": [77912, 83925]}, {"ru": "Каждый зажигал и гасил свой единственный фонарь только один раз в год.", "zh": "北极和南极各自仅有一盏灯，他们一年只点两次灯。", "t": [83925, 87962]}]}]}, {"id": "ch17", "title_ru": "Глава 17", "title_zh": "第 17 章", "paras": [{"id": "ch17p00", "audio": true, "sents": [{"ru": "Когда хочешь сострить, приходится порой и приврать.", "zh": "好出风头，喜欢卖弄聪明的人，多少会讲几句大话，吹点牛皮。", "t": [100, 4175]}, {"ru": "Рассказывая о фонарщиках Земли, я не был до конца честен.", "zh": "我给你们介绍点灯人的时候，也不太老实。", "t": [4175, 8888]}, {"ru": "И у того, кто не видел эту планету, может создаться о ней неправильное представление.", "zh": "我也许让不了解我们星球的人产生误解，造成错觉。", "t": [8888, 14738]}, {"ru": "На самом деле люди на ней занимают очень мало места.", "zh": "人在地球上占的位置微乎其微。", "t": [14738, 17912]}]}, {"id": "ch17p01", "audio": true, "sents": [{"ru": "Если бы два миллиарда жителей Земли собрались вместе как на митинг, они легко разместились бы на площади длиной и шириной в двадцать миль.", "zh": "倘若让散居在地球上的二十亿人口集中在一起开大会，他们可以松快地站在二十英里长二十英里宽的广场上。", "t": [100, 8200]}, {"ru": "Все население мира легко поместилось бы на каком-нибудь островке Тихого океана.", "zh": "可以把人类堆在太平洋最小的岛屿里。", "t": [8200, 13538]}, {"ru": "Взрослые, конечно, в это не поверят.", "zh": "当然，大人们不会相信这些话。", "t": [13538, 17188]}, {"ru": "Они воображают, что занимают очень много места.", "zh": "他们以为自己占了很大的位置，自以为自己像猴面包树那么庞大。", "t": [17188, 21388]}, {"ru": "Они кажутся себе большими и важными, как баобабы.", "zh": "那你就建议他们算一算。", "t": [21388, 25612]}, {"ru": "Поэтому посоветуйте сделать им эти прикидки.", "zh": "他们不是喜欢数字吗？", "t": [25612, 29138]}, {"ru": "Они обожают цифры, им это понравится.", "zh": "他们会高兴的。", "t": [29138, 32725]}, {"ru": "Но сами вы лучше не тратьте время на эту занудную и бесполезную работу.", "zh": "但我劝你们别多此一举了，挺麻烦的，毫无用处的。", "t": [32725, 37612]}, {"ru": "Вы же мне доверяете?", "zh": "相信我的话吧。", "t": [37612, 39912]}, {"ru": "Оказавшись на Земле, маленький принц был весьма удивлен.", "zh": "小王子来到地球后，看不见一个人影，不由心里纳闷。", "t": [39912, 44300]}, {"ru": "Он никого не увидел и уже побоялся, что ошибся планетой.", "zh": "他担心走错了路，到了别的星球了。", "t": [44300, 48800]}, {"ru": "И тут на песке шевельнулось кольцо бледно-лунного цвета.", "zh": "这时，他看见沙地上有一个月白色的圆环在蠕动。", "t": [48800, 52962]}, {"ru": "— Добрый вечер, — сказал на всякий случай маленький принц.", "zh": "”小王子随口说。", "t": [52962, 57238]}, {"ru": "— Добрый вечер, — сказала змея.", "zh": "“这儿是什么星球？", "t": [57238, 60275]}, {"ru": "— На какую планету я попал?", "zh": "”小王子问。", "t": [60275, 62888]}, {"ru": "— спросил маленький принц.", "zh": "“是地球，非洲。", "t": [62888, 65512]}, {"ru": "— На Землю.", "zh": "”蛇回答说。", "t": [65512, 67300]}, {"ru": "Ты в Африке, — ответила змея.", "zh": "……地球上没人吗？", "t": [67300, 70238]}, {"ru": "— А!", "zh": "……地球上没人吗？", "t": [70238, 71500]}, {"ru": "Так на Земле никто не живет?", "zh": "” “这儿是沙漠，沙漠里是没有人烟的，地球很大。", "t": [71500, 74162]}, {"ru": "— Ты в пустыне.", "zh": "” “这儿是沙漠，沙漠里是没有人烟的，地球很大。", "t": [74162, 76062]}, {"ru": "В пустынях никто не живет.", "zh": "” “这儿是沙漠，沙漠里是没有人烟的，地球很大。", "t": [76062, 78800]}, {"ru": "Земля большая, — ответила змея.", "zh": "”蛇说。", "t": [78800, 81962]}, {"ru": "Маленький принц присел на камень и поднял глаза к небу.", "zh": "小王子坐在一块石头上，抬头看天空： “我在想，星星发亮是否为了让每个人有一天能找到自己的星星。", "t": [81962, 86075]}, {"ru": "— Интересно, — сказал он, — звезды светятся, чтобы каждый мог когда-нибудь найти свою?", "zh": "小王子坐在一块石头上，抬头看天空： “我在想，星星发亮是否为了让每个人有一天能找到自己的星星。", "t": [86075, 91962]}, {"ru": "Посмотри на", "zh": "你看我的星球，它正好在我的头顶上……可它多么的遥远！", "t": [91962, 92838]}]}, {"id": "ch17p02", "audio": true, "sents": [{"ru": "мою планету.", "zh": "你看我的星球，它正好在我的头顶上……可它多么的遥远！", "t": [100, 2150]}, {"ru": "Она сейчас точно над нами.", "zh": "你看我的星球，它正好在我的头顶上……可它多么的遥远！", "t": [2150, 4938]}, {"ru": "Но она так далеко!", "zh": "” “它真美。", "t": [4938, 7200]}, {"ru": "— Она красивая, — сказала змея.", "zh": "”蛇说。", "t": [7200, 10150]}, {"ru": "— Зачем ты прилетел сюда?", "zh": "“你来这儿干什么？", "t": [10150, 12712]}, {"ru": "— У меня проблемы с одним цветком, — ответил маленький принц.", "zh": "” “我和一朵花赌气闹别扭呢。", "t": [12712, 17038]}, {"ru": "— Понятно, — сказала змея.", "zh": "”蛇说。", "t": [17038, 19800]}, {"ru": "— А где все люди?", "zh": "他们都缄口不言了。", "t": [19800, 21838]}, {"ru": "— продолжил разговор маленький принц после минутного молчания.", "zh": "”小王子终于开口说话。", "t": [21838, 26362]}, {"ru": "— Здесь, в пустыне, довольно одиноко.", "zh": "“待在沙漠有点孤独……” “跟人在一起也孤独。", "t": [26362, 30088]}, {"ru": "— Среди людей тоже бывает одиноко, — ответила змея.", "zh": "”蛇说。", "t": [30088, 34125]}, {"ru": "Маленький принц внимательно на нее посмотрел.", "zh": "小王子久久凝视着它。", "t": [34125, 37662]}, {"ru": "— Ты забавная, — сказал он наконец.", "zh": "“你是奇特的动物，”小王子终于说道，“你像一根指头般细……” “可我比国王的指头强大得多。", "t": [37662, 40812]}, {"ru": "— Такая тонкая…", "zh": "“你是奇特的动物，”小王子终于说道，“你像一根指头般细……” “可我比国王的指头强大得多。", "t": [40812, 43062]}, {"ru": "Как палец.", "zh": "“你是奇特的动物，”小王子终于说道，“你像一根指头般细……” “可我比国王的指头强大得多。", "t": [43062, 44900]}, {"ru": "— Я могу быть более могущественной, чем перст короля, — заметила змея.", "zh": "”蛇说。", "t": [44900, 49900]}, {"ru": "Маленький принц улыбнулся: — Ты не могущественная.", "zh": "小王子微微一笑。", "t": [49900, 53925]}, {"ru": "У тебя ведь даже нет лап, и ты не можешь путешествовать.", "zh": "“你没有那么强大吧……你连爪子都没有……你连走路都不会……” “船能送你走远路，可我能送你走更远的路。", "t": [53925, 58150]}, {"ru": "— Однако я могу унести тебя дальше любого корабля, — сказала змея.", "zh": "“你没有那么强大吧……你连爪子都没有……你连走路都不会……” “船能送你走远路，可我能送你走更远的路。", "t": [58150, 62862]}, {"ru": "И она обвилась вокруг ноги маленького принца, словно золотой браслет.", "zh": "” 它盘着小王子的脚踝，像一只金镯子。", "t": [62862, 67912]}, {"ru": "— Тот, кого я касаюсь, возвращается в землю, откуда и вышел, — добавила она.", "zh": "“我碰到谁，就能把他送回他来的地方，”蛇还说，“但你纯洁，你是从星球上来的……” 小王子默默无言。", "t": [67912, 73812]}, {"ru": "— Но ты чист, ведь ты прибыл со звезды.", "zh": "“我碰到谁，就能把他送回他来的地方，”蛇还说，“但你纯洁，你是从星球上来的……” 小王子默默无言。", "t": [73812, 77050]}, {"ru": "На это маленький принц ничего не ответил.", "zh": "“我同情你，在这花岗岩构成的地球上，你这么弱小。", "t": [77050, 79488]}]}, {"id": "ch17p03", "audio": true, "sents": [{"ru": "— Мне тебя жаль, — продолжила змея.", "zh": "“我同情你，在这花岗岩构成的地球上，你这么弱小。", "t": [100, 3188]}, {"ru": "Ты ведь так слаб на этой каменной Земле.", "zh": "如果你有朝一日思念你的星球，我可以帮助你。", "t": [3188, 6388]}, {"ru": "Возможно, однажды я смогу тебе помочь, если ты пожалеешь, что покинул свою планету.", "zh": "我可以……” “啊！", "t": [6388, 12775]}, {"ru": "Я могла бы…", "zh": "我完全明白你的意思，”小王子说，“但你的话为什么句句都像谜似的？", "t": [12775, 13912]}, {"ru": "— Я понял тебя, — ответил маленький принц.", "zh": "我完全明白你的意思，”小王子说，“但你的话为什么句句都像谜似的？", "t": [13912, 17150]}, {"ru": "— Но почему ты все время говоришь загадками?", "zh": "” “我能解一切谜。", "t": [17150, 20662]}, {"ru": "— Я все их решаю, — ответила змея, и оба замолкли.", "zh": "”蛇说。", "t": [20662, 24275]}]}]}, {"id": "ch18", "title_ru": "Глава 18", "title_zh": "第 18 章", "paras": [{"id": "ch18p00", "audio": true, "sents": [{"ru": "Маленький принц пересек пустыню и по дороге встретил лишь один цветок.", "zh": "小王子穿过沙漠，只遇见一朵花。", "t": [100, 5088]}, {"ru": "У него было всего три лепестка, и он был совершенно невзрачный.", "zh": "”王子说。", "t": [5088, 9588]}, {"ru": "— Привет, — сказал маленький принц.", "zh": "”花儿说。", "t": [9588, 12738]}, {"ru": "— Привет, — ответил цветок.", "zh": "”小王子彬彬有礼地问。", "t": [12738, 15638]}, {"ru": "— А где все люди?", "zh": "”小王子彬彬有礼地问。", "t": [15638, 17675]}, {"ru": "— деликатно поинтересовался маленький принц.", "zh": "花儿有一天曾看见一队骆驼走过。", "t": [17675, 21138]}, {"ru": "Цветок однажды видел, как мимо проходил караван.", "zh": "依我看，人是有的，大概六七个吧。", "t": [21138, 25138]}, {"ru": "— Люди?", "zh": "好几年前我见过他们。", "t": [25138, 26700]}, {"ru": "Думаю, их шесть или семь.", "zh": "好几年前我见过他们。", "t": [26700, 29775]}, {"ru": "Я видел их много лет назад.", "zh": "但我不知道在哪儿能找到他们。", "t": [29775, 32612]}, {"ru": "Никогда не знаешь, где их искать.", "zh": "风把他们吹散了。", "t": [32612, 35862]}, {"ru": "Их носит ветер.", "zh": "风把他们吹散了。", "t": [35862, 37975]}, {"ru": "У них ведь нет корней, и это мешает…", "zh": "他们没有根，这就使他们吃尽了苦头。", "t": [37975, 40525]}, {"ru": "— Прощай, — сказал маленький принц.", "zh": "” “别了。", "t": [40525, 43412]}, {"ru": "— Прощай, — ответил цветок.", "zh": "”花儿说。", "t": [43412, 45326]}]}]}, {"id": "ch19", "title_ru": "Глава 19", "title_zh": "第 19 章", "paras": [{"id": "ch19p00", "audio": true, "sents": [{"ru": "Маленький принц поднялся на высокую гору.", "zh": "小王子登上一座高山。", "t": [100, 3562]}, {"ru": "Единственными горами, которые он видел раньше, были три вулкана на его планете.", "zh": "以前他只见过自己的那三座火山，火山很矮，才到他的膝盖。", "t": [3562, 9112]}, {"ru": "Они были совсем невысокими — едва доходили ему до колена, и он использовал потухший вулкан как табуретку.", "zh": "死火山只能给他当凳子坐。", "t": [9112, 15838]}, {"ru": "Поэтому", "zh": "“站在这座高山上，”他想道，“我一眼就能看见整个星球和所有的人了……” 但他只看见悬崖峭壁。", "t": [15838, 16626]}]}, {"id": "ch19p01", "audio": true, "sents": [{"ru": "маленький принц подумал, что с такой высокой горы, как эта, он сможет окинуть взором сразу всю планету и всех живущих на ней людей.", "zh": "“您好。", "t": [100, 8675]}, {"ru": "Однако он не увидел ничего, кроме остро заточенных скал.", "zh": "“您好……您好……您好……”回声应道。", "t": [8675, 13150]}, {"ru": "— Привет, — сказал он на всякий случай.", "zh": "”小王子问。", "t": [13150, 16600]}, {"ru": "— Привет, привет, привет, — ответило эхо.", "zh": "“您是谁……您是谁……您是谁……”回声应道。", "t": [16600, 20662]}, {"ru": "— Кто вы?", "zh": "“您是谁……您是谁……您是谁……”回声应道。", "t": [20662, 22262]}, {"ru": "— спросил маленький принц.", "zh": "“做我的朋友吧，我很孤单……”他说。", "t": [22262, 24875]}, {"ru": "— Кто вы, кто вы, кто вы?", "zh": "“做我的朋友吧，我很孤单……”他说。", "t": [24875, 27825]}, {"ru": "— спросило эхо.", "zh": "“做我的朋友吧，我很孤单……”他说。", "t": [27825, 30125]}, {"ru": "— Будь моим другом, — предложил маленький принц, — я одинок.", "zh": "“我很孤单……我很孤单……我很孤单……”回声又答应道。", "t": [30125, 34812]}, {"ru": "— Я одинок, я одинок, я одинок, — повторило эхо.", "zh": "“多么古怪的星球！", "t": [34812, 39688]}, {"ru": "«Какая это чудная планета, — подумал маленький принц, — такая сухая, заостренная и просоленная.", "zh": "”小王子想道。", "t": [39688, 46712]}, {"ru": "А людям не хватает воображения.", "zh": "“干干巴巴的，尖尖峭峭的，带点咸味儿的，这儿的人缺乏想像力，他们净重复别人讲过的话……而在我的那个星球里，我有一朵花，她总是抢先讲话……”", "t": [46712, 49912]}, {"ru": "Они просто повторяют, что им говорят.", "zh": "“干干巴巴的，尖尖峭峭的，带点咸味儿的，这儿的人缺乏想像力，他们净重复别人讲过的话……而在我的那个星球里，我有一朵花，她总是抢先讲话……”", "t": [49912, 53275]}, {"ru": "А у меня на планете был цветок, моя красавица, и она всегда заговаривала со мной первой».", "zh": "“干干巴巴的，尖尖峭峭的，带点咸味儿的，这儿的人缺乏想像力，他们净重复别人讲过的话……而在我的那个星球里，我有一朵花，她总是抢先讲话……”", "t": [53275, 58474]}]}]}, {"id": "ch20", "title_ru": "Глава 20", "title_zh": "第 20 章", "paras": [{"id": "ch20p00", "audio": true, "sents": [{"ru": "Так случилось, что маленький принц, пройдя через пески, миновав скалы и снега, набрел, наконец, на дорогу.", "zh": "小王子在沙漠、山峰、大雪中长途跋涉。", "t": [100, 8162]}, {"ru": "А все дороги ведут к людям.", "zh": "“你们好。", "t": [8162, 10862]}, {"ru": "— Здравствуйте, — сказал маленький принц.", "zh": "”他说。", "t": [10862, 14338]}, {"ru": "Ведь перед ним был сад с цветущими розами.", "zh": "“你好。", "t": [14338, 17000]}]}, {"id": "ch20p01", "audio": true, "sents": [{"ru": "— Здравствуйте, — сказали розы.", "zh": "小王子看着她们。", "t": [100, 3088]}, {"ru": "Маленький принц посмотрел на них, и они ему показались очень похожими на его цветок.", "zh": "“你们是谁？", "t": [3088, 8888]}, {"ru": "— Кто вы?", "zh": "”小王子大吃一惊，问她们说。", "t": [8888, 10475]}, {"ru": "— спросил он, пораженный этим зрелищем.", "zh": "“我们是玫瑰花。", "t": [10475, 14212]}, {"ru": "— Мы розы, — ответили розы.", "zh": "“啊！", "t": [14212, 17025]}, {"ru": "— Вот как?", "zh": "”小王子说…… 小王子伤心极了。", "t": [17025, 18788]}, {"ru": "— сказал маленький принц…", "zh": "”小王子说…… 小王子伤心极了。", "t": [18788, 21312]}, {"ru": "Он почувствовал себя несчастным.", "zh": "他的花儿告诉他，大千世界中，她是惟一的玫瑰花。", "t": [21312, 24162]}, {"ru": "Ведь его цветок говорил ему, что он единственный в своем роде на целом свете.", "zh": "他的花儿告诉他，大千世界中，她是惟一的玫瑰花。", "t": [24162, 29350]}, {"ru": "А тут, всего в одном саду, их было не меньше пяти тысяч!", "zh": "可是在这儿，仅仅一座花园里就有五千朵玫瑰花，全都长得一模一样！", "t": [29350, 33075]}]}, {"id": "ch20p02", "audio": true, "sents": [{"ru": "«Если бы моя красавица это увидела, — подумал маленький принц, — ее бы это очень расстроило.", "zh": "可是在这儿，仅仅一座花园里就有五千朵玫瑰花，全都长得一模一样！", "t": [100, 6312]}, {"ru": "И чтобы не показаться смешной, она наверняка бы долго кашляла и прикинулась умирающей.", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [6312, 12262]}, {"ru": "А я бы делал вид, что ухаживаю за ней.", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [12262, 15862]}, {"ru": "Иначе, чтобы мне досадить, она могла бы решиться умереть на самом деле».", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [15862, 21338]}, {"ru": "Потом он добавил про себя: «Я чувствовал себя богачом, обладавшим уникальным цветком, а на самом деле у меня обычная роза.", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [21338, 29050]}, {"ru": "Она да три вулкана, из которых к тому же один потух, и возможно навсегда, — это маловато для настоящего принца».", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [29050, 36475]}, {"ru": "И, бросившись на траву, он заплакал.", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [36475, 39213]}]}]}, {"id": "ch21", "title_ru": "Глава 21", "title_zh": "第 21 章", "paras": [{"id": "ch21p00", "audio": true, "sents": [{"ru": "В это время появился лис.", "zh": "就在这个时候，出现了一只狐狸。", "t": [100, 2700]}, {"ru": "— Привет, — сказал он.", "zh": "“你好。", "t": [2700, 5212]}, {"ru": "— Привет, — вежливо ответил маленький принц.", "zh": "“你好。", "t": [5212, 8900]}, {"ru": "Однако, обернувшись, он никого не заметил.", "zh": "”小王子彬彬有礼地回答，他转过身，但看不见有什么东西。", "t": [8900, 12700]}, {"ru": "— Я здесь, — раздался голос, — под яблоней.", "zh": "“我在这里，”那声音说，“在苹果树下。", "t": [12700, 16700]}, {"ru": "— Ты кто?", "zh": "“我在这里，”那声音说，“在苹果树下。", "t": [16700, 18300]}, {"ru": "— спросил маленький принц.", "zh": "“我在这里，”那声音说，“在苹果树下。", "t": [18300, 20938]}, {"ru": "— Ты красивый…", "zh": "” “你是谁？", "t": [20938, 22088]}, {"ru": "— Я лис, — ответил лис.", "zh": "” “你是谁？", "t": [22088, 24625]}, {"ru": "— Ты не хочешь поиграть со мной?", "zh": "”小王子说，“你真漂亮……” “我是狐狸。", "t": [24625, 27325]}, {"ru": "— предложил маленький принц.", "zh": "”狐狸说。", "t": [27325, 29950]}, {"ru": "— Мне так грустно…", "zh": "“来跟我一起玩吧。", "t": [29950, 31438]}, {"ru": "— Я не могу играть с тобой, — ответил лис.", "zh": "”小王子向他建议。", "t": [31438, 34475]}, {"ru": "— Я не приручен.", "zh": "”小王子向他建议。", "t": [34475, 36538]}, {"ru": "— А…", "zh": "“我非常伤心……” “我不能跟你一起玩，”狐狸说，“我不是驯养的动物。", "t": [36538, 37788]}, {"ru": "Ну, извини, — сказал маленький принц.", "zh": "“我非常伤心……” “我不能跟你一起玩，”狐狸说，“我不是驯养的动物。", "t": [37788, 41375]}, {"ru": "Однако, подумав, он добавил: — А что значит «приручать»?", "zh": "” “哦，对不起。", "t": [41375, 45262]}]}, {"id": "ch21p01", "audio": true, "sents": [{"ru": "— Я вижу, ты не отсюда, — ответил лис.", "zh": "”小王子说。", "t": [100, 3512]}, {"ru": "— Что ты тут ищешь?", "zh": "小王子想了想，又问： “什么叫做‘驯养’？", "t": [3512, 5750]}, {"ru": "— Я ищу людей, — сказал маленький принц.", "zh": "” “你不是本地人。", "t": [5750, 9238]}, {"ru": "— Так что значит «приручать»?", "zh": "”狐狸说。", "t": [9238, 12300]}, {"ru": "— Люди, — ответил лис, — у них есть ружья, и они охотятся.", "zh": "“人有枪，人打猎，太可恶了！", "t": [12300, 17288]}, {"ru": "Это очень неудобно.", "zh": "这是人惟一的好处。", "t": [17288, 19800]}, {"ru": "А еще они разводят кур.", "zh": "你也找鸡吗？", "t": [19800, 22338]}, {"ru": "Это все, что их волнует.", "zh": "” “不！", "t": [22338, 25212]}, {"ru": "Ты ищешь кур?", "zh": "”小王子说，“我找朋友。", "t": [25212, 27188]}, {"ru": "— Нет, — ответил маленький принц.", "zh": "什么叫做‘驯养’？", "t": [27188, 30300]}, {"ru": "— Я ищу друзей.", "zh": "什么叫做‘驯养’？", "t": [30300, 32525]}, {"ru": "Так что значит «приручать»?", "zh": "什么叫做‘驯养’？", "t": [32525, 35612]}, {"ru": "— Это давно позабытое дело, — ответил лис.", "zh": "” “这是一件被人遗忘干净的事了，”狐狸说，“它的意思就是‘建立联系’……” “建立联系？", "t": [35612, 39162]}, {"ru": "— Это значит создавать привязанности.", "zh": "” “这是一件被人遗忘干净的事了，”狐狸说，“它的意思就是‘建立联系’……” “建立联系？", "t": [39162, 42250]}, {"ru": "— Создавать привязанности?", "zh": "” “当然，”狐狸说，“对我而言，你不过是一个小男孩，和千千万万的小男孩没有两样。", "t": [42250, 44762]}, {"ru": "— Именно, — сказал лис.", "zh": "” “当然，”狐狸说，“对我而言，你不过是一个小男孩，和千千万万的小男孩没有两样。", "t": [44762, 47450]}, {"ru": "— Ты для меня пока всего лишь маленький мальчик, похожий на сто тысяч других маленьких мальчиков.", "zh": "” “当然，”狐狸说，“对我而言，你不过是一个小男孩，和千千万万的小男孩没有两样。", "t": [47450, 53625]}, {"ru": "И ты во мне не нуждаешься.", "zh": "而且我不需要你，你也不需要我。", "t": [53625, 56162]}, {"ru": "Для тебя я — лис, похожий на сто тысяч других лисов.", "zh": "对你而言，我只是一只狐狸，和千千万万只狐狸没有两样。", "t": [56162, 60662]}, {"ru": "Но если ты меня приручишь, мы будем нужны друг другу.", "zh": "但如果你驯养了我，我们就互相需要了。", "t": [60662, 64712]}, {"ru": "Ты станешь для меня единственным в мире, а я буду единственным для тебя.", "zh": "但如果你驯养了我，我们就互相需要了。", "t": [64712, 69712]}, {"ru": "— Кажется, я начинаю понимать, — сказал маленький принц.", "zh": "你就是我世界上惟一的人了，我也是你世上惟一的狐狸了……” “我有点明白了。", "t": [69712, 74075]}, {"ru": "— У меня есть цветок, моя красавица…", "zh": "”小王子说。", "t": [74075, 77612]}, {"ru": "Мне кажется, она меня приручила.", "zh": "”小王子说。", "t": [77612, 80850]}, {"ru": "— Это возможно, — ответил лис.", "zh": "“有一朵花儿……我认为她驯养了我……” “这可能，”狐狸说，“地球上有各色各样，形形色色的东西……” “啊！", "t": [80850, 83725]}, {"ru": "— На Земле всякое случается…", "zh": "“有一朵花儿……我认为她驯养了我……” “这可能，”狐狸说，“地球上有各色各样，形形色色的东西……” “啊！", "t": [83725, 85750]}, {"ru": "— Это случилось не на Земле, — сказал маленький принц.", "zh": "她不在地球上。", "t": [85750, 89375]}, {"ru": "Лис был чрезвычайно удивлен: — На другой планете?", "zh": "”小王子说。", "t": [89375, 93312]}, {"ru": "— Да.", "zh": "狐狸露出大惊的神色。", "t": [93312, 93750]}]}, {"id": "ch21p02", "audio": true, "sents": [{"ru": "— А там есть охотники?", "zh": "“在另一个星球上？", "t": [100, 2562]}, {"ru": "— Нет.", "zh": "“在另一个星球上？", "t": [2562, 4075]}, {"ru": "— А куры?", "zh": "” “是的。", "t": [4075, 5738]}, {"ru": "— Нет.", "zh": "” “是的。", "t": [5738, 7262]}, {"ru": "— Нет в мире совершенства, — вздохнул лис.", "zh": "” “那颗星球上，有猎人吗？", "t": [7262, 10912]}, {"ru": "Однако он вернулся к прежней теме: — Видишь ли, моя жизнь довольно однообразна.", "zh": "” “那可有意思了！", "t": [10912, 16300]}, {"ru": "Я охочусь за курами, а охотники охотятся за мной.", "zh": "” “世上就没有十全十美的东西。", "t": [16300, 20488]}, {"ru": "Все куры одинаковы, и все люди похожи друг на друга.", "zh": "”狐狸叹了一口气。", "t": [20488, 24800]}, {"ru": "Поэтому мне немного скучно.", "zh": "狐狸又扯回原先的话题： “我的生活枯燥乏味，异常单调。", "t": [24800, 27512]}, {"ru": "Однако, если ты меня приручишь, мою жизнь словно озарит солнечный свет.", "zh": "我逮鸡，人逮我。", "t": [27512, 33025]}, {"ru": "Я буду узнавать звук твоих шагов, они для меня будут отличаться от всех прочих.", "zh": "但如果你驯养我，我的生活就会充满阳光。", "t": [33025, 38838]}, {"ru": "От прочих шагов я ныряю под землю, а твои будут меня выманивать из моего логова.", "zh": "我能辨得出与众不同的脚步声。", "t": [38838, 44350]}, {"ru": "Они будут звучать для меня, как музыка.", "zh": "别人的脚步声吓得我赶紧钻回地洞。", "t": [44350, 47688]}, {"ru": "И потом, взгляни!", "zh": "你的脚步声却像悦耳的音乐，召唤我走出洞穴。", "t": [47688, 50062]}, {"ru": "Видишь там поля пшеницы?", "zh": "你瞧！", "t": [50062, 52738]}, {"ru": "Я не ем хлеб.", "zh": "你瞧！", "t": [52738, 54925]}, {"ru": "Пшеница мне ни к чему.", "zh": "你看那儿，那不是一片麦田吗？", "t": [54925, 57450]}, {"ru": "И поля пшеницы", "zh": "你看那儿，那不是一片麦田吗？", "t": [57450, 58762]}]}, {"id": "ch21p03", "audio": true, "sents": [{"ru": "ничего мне не напоминают, что довольно грустно.", "zh": "我不吃面包，我不需要小麦，麦田引不起我的想像力。", "t": [100, 3938]}, {"ru": "Но у тебя золотистые волосы.", "zh": "说到这个，实在可悲！", "t": [3938, 6838]}, {"ru": "Представляешь, как будет славно, когда ты меня приручишь?", "zh": "说到这个，实在可悲！", "t": [6838, 11125]}, {"ru": "Золотистая пшеница станет мне напоминать о тебе.", "zh": "但你的头发是金灿灿的，它会叫我想起你的，我就会爱上风吹麦子的声音……”狐狸没说下去，对小王子瞧了好久，又说： “请你……驯养我吧！", "t": [11125, 14875]}, {"ru": "И я полюблю, как она шелестит на ветру…", "zh": "但你的头发是金灿灿的，它会叫我想起你的，我就会爱上风吹麦子的声音……”狐狸没说下去，对小王子瞧了好久，又说： “请你……驯养我吧！", "t": [14875, 18312]}, {"ru": "Лис замолчал и посмотрел на маленького принца долгим взглядом: — Ну, пожалуйста, приручи меня!", "zh": "但你的头发是金灿灿的，它会叫我想起你的，我就会爱上风吹麦子的声音……”狐狸没说下去，对小王子瞧了好久，又说： “请你……驯养我吧！", "t": [18312, 24625]}, {"ru": "— Я бы и рад, — ответил маленький принц.", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [24625, 28138]}, {"ru": "— Но у меня мало времени.", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [28138, 30675]}, {"ru": "Мне нужно найти друзей и так много еще узнать.", "zh": "” “人只认识自己驯养的东西。", "t": [30675, 34425]}, {"ru": "— По-настоящему узнаешь только те вещи, которые приручаешь, — ответил лис.", "zh": "”狐狸说。", "t": [34425, 39738]}, {"ru": "— У людей больше нет времени ничего узнавать как следует.", "zh": "他们到商店买现成的东西，但没有一家商店是出售朋友的，人也就没有朋友了。", "t": [39738, 43788]}, {"ru": "Торговцы продают им готовые вещи.", "zh": "他们到商店买现成的东西，但没有一家商店是出售朋友的，人也就没有朋友了。", "t": [43788, 46875]}, {"ru": "Однако нет торговцев, предлагающих друзей.", "zh": "如果你想要朋友，你就驯养我吧！", "t": [46875, 50725]}, {"ru": "Поэтому у людей их нет.", "zh": "如果你想要朋友，你就驯养我吧！", "t": [50725, 53512]}, {"ru": "Если ты хочешь завести друга, приручи меня!", "zh": "” “我该做些什么呢？", "t": [53512, 57012]}, {"ru": "— А что для этого надо делать?", "zh": "“需要非常的耐心。", "t": [57012, 59612]}, {"ru": "— спросил маленький принц.", "zh": "”狐狸回答说。", "t": [59612, 62225]}, {"ru": "— Надо быть очень терпеливым, — ответил лис.", "zh": "“首先你要离我稍远点，坐着，像这样，坐在草地上。", "t": [62225, 65812]}, {"ru": "— Сначала ты сядешь вот так в траву немного поодаль от меня.", "zh": "我斜瞟着你，你什么也别对我说。", "t": [65812, 70038]}, {"ru": "Я буду смотреть на тебя искоса, а ты будешь молчать.", "zh": "语言是误会的源泉。", "t": [70038, 74250]}, {"ru": "Ведь язык — источник всех недоразумений.", "zh": "可是每天你可以坐得稍近一点……” 翌日，小王子又来了。", "t": [74250, 78062]}, {"ru": "Однако с каждым днем ты сможешь садиться немного ближе…", "zh": "可是每天你可以坐得稍近一点……” 翌日，小王子又来了。", "t": [78062, 82200]}, {"ru": "На следующий день маленький принц пришел на встречу с лисом снова.", "zh": "“最好在同一个时间来，”狐狸说，“例如，如果你是下午四点钟来的，从三点钟开始，我就开始感觉到幸福的滋味了。", "t": [82200, 86675]}, {"ru": "— Будет лучше, — сказал тот, — если ты станешь возвращаться в одно и то же время.", "zh": "越接近四点钟，我越觉得幸福。", "t": [86675, 92188]}]}, {"id": "ch21p04", "audio": true, "sents": [{"ru": "Если ты, к примеру, будешь появляться в четыре часа дня, начиная с трех я уже буду счастлив.", "zh": "到了四点钟，我就心神恍惚，坐立不安了。", "t": [100, 5162]}, {"ru": "И чем ближе будет время встречи, тем счастливее я буду становиться.", "zh": "我发现了幸福的价值，但是如果你不按时来，我就不知道几点钟该装扮我的心，仪式还是需要的。", "t": [5162, 10012]}, {"ru": "А ровно в четыре я начну волноваться и тревожиться.", "zh": "” “什么叫做‘仪式’？", "t": [10012, 13975]}, {"ru": "Так я открою для себя цену счастья!", "zh": "”小王子问。", "t": [13975, 17238]}, {"ru": "Но если ты станешь появляться в разное время, я не буду знать, когда мне готовиться к радости встречи…", "zh": "”狐狸说。", "t": [17238, 23500]}, {"ru": "Нужны обряды…", "zh": "“仪式就是使得某一日不同于其他日子，某一个小时不同于别的小时。", "t": [23500, 24850]}, {"ru": "— Что такое «обряд»?", "zh": "“仪式就是使得某一日不同于其他日子，某一个小时不同于别的小时。", "t": [24850, 27612]}, {"ru": "— спросил маленький принц.", "zh": "“仪式就是使得某一日不同于其他日子，某一个小时不同于别的小时。", "t": [27612, 30250]}, {"ru": "— Это давно позабытая вещь, — ответил лис.", "zh": "比如说，猎人们有个仪式，每逢星期四，他们就与村里的姑娘们跳舞，星期四就成了再美妙不过的日子了！", "t": [30250, 33925]}, {"ru": "— Это то, что отличает один день от другого или делает какой-нибудь час особенным.", "zh": "比如说，猎人们有个仪式，每逢星期四，他们就与村里的姑娘们跳舞，星期四就成了再美妙不过的日子了！", "t": [33925, 39488]}, {"ru": "Например, у моих охотников есть один обряд.", "zh": "我也就可以到葡萄园里去闲逛了。", "t": [39488, 43312]}, {"ru": "По четвергам они танцуют с девушками из деревни.", "zh": "如果猎人跳舞不挑日子，每一天都一样，我就没有假期了。", "t": [43312, 47012]}, {"ru": "И поэтому четверг для них — день чудесный.", "zh": "” 于是小王子驯养狐狸了。", "t": [47012, 50775]}, {"ru": "А я могу в это время прогуляться до самых виноградников.", "zh": "小王子要走的时候到了。", "t": [50775, 54712]}, {"ru": "Если бы охотники танцевали, когда им вздумается, все дни были бы одинаковыми, и я не смог бы устраивать себе маленький праздник.", "zh": "” “这就是你的不对了，”小王子说，“我一点也不想伤害你，但你却要我驯养你……” “不错。", "t": [54712, 62788]}, {"ru": "В конце концов, маленькому принцу удалось приручить лиса, но когда настал час их прощания, лис вздохнул: — Без тебя я буду плакать.", "zh": "“但你却想哭！", "t": [62788, 71288]}, {"ru": "— Сам виноват, — заметил маленький принц.", "zh": "“那你是一无所获了！", "t": [71288, 74912]}, {"ru": "— Я не хотел причинить тебе боль.", "zh": "” “我有收获的，”狐狸说，“我得到了小麦的颜色。", "t": [74912, 77700]}, {"ru": "Ты же сам захотел, чтобы я тебя приручил.", "zh": "” “我有收获的，”狐狸说，“我得到了小麦的颜色。", "t": [77700, 81112]}, {"ru": "— Это верно, — сказал лис.", "zh": "” 然后他又说： “你去探望玫瑰花们吧，你就会明白，你的玫瑰花是世界上独一无二的花儿。", "t": [81112, 83850]}, {"ru": "— Но ты будешь плакать!", "zh": "” 然后他又说： “你去探望玫瑰花们吧，你就会明白，你的玫瑰花是世界上独一无二的花儿。", "t": [83850, 86300]}, {"ru": "— Конечно, — вздохнул лис.", "zh": "” 然后他又说： “你去探望玫瑰花们吧，你就会明白，你的玫瑰花是世界上独一无二的花儿。", "t": [86300, 89188]}, {"ru": "— Так что же ты получил в результате?", "zh": "然后你回来与我告别，我会送你一桩秘密作为礼物。", "t": [89188, 91163]}]}, {"id": "ch21p05", "audio": true, "sents": [{"ru": "—Теперь мне о многом говорит цвет пшеницы…", "zh": "然后你回来与我告别，我会送你一桩秘密作为礼物。", "t": [100, 3662]}, {"ru": "Потом лис добавил: — Пойди, взгляни еще раз на розы, и теперь ты поймешь, что твоя роза — единственная в мире.", "zh": "” 小王子探望玫瑰花们，并对她们说： “你们一点也不像我的玫瑰，你们还无足轻重，没有人驯养你们，你们也没有驯养任何人。", "t": [3662, 11025]}, {"ru": "А когда ты придешь попрощаться со мной, я открою тебе один секрет.", "zh": "” 小王子探望玫瑰花们，并对她们说： “你们一点也不像我的玫瑰，你们还无足轻重，没有人驯养你们，你们也没有驯养任何人。", "t": [11025, 15925]}, {"ru": "И маленький принц пошел взглянуть на розы.", "zh": "你们的今天如同我的狐狸的昨天。", "t": [15925, 19312]}, {"ru": "— Вы совсем не похожи на мою розу, — сказал он им.", "zh": "昨天的他与千千万万的狐狸一样，但自从我让他做了我的朋友，他就是世上绝无仅有的狐狸了。", "t": [19312, 22062]}, {"ru": "— Вы совершенно не она.", "zh": "昨天的他与千千万万的狐狸一样，但自从我让他做了我的朋友，他就是世上绝无仅有的狐狸了。", "t": [22062, 24275]}, {"ru": "Вас еще никто не приручил, и вы никого не приручили.", "zh": "昨天的他与千千万万的狐狸一样，但自从我让他做了我的朋友，他就是世上绝无仅有的狐狸了。", "t": [24275, 28350]}, {"ru": "Вы такие, каким был мой лис.", "zh": "” 玫瑰花们听了心里怪不自在的。", "t": [28350, 31338]}, {"ru": "Он был похож на сто тысяч других лисов. Но", "zh": "“你们长得很美，但你们的感情世界一片空白。", "t": [31338, 35300]}]}, {"id": "ch21p06", "audio": true, "sents": [{"ru": "он стал моим другом, и теперь он для меня единственный в мире.", "zh": "”小王子还对她们说。", "t": [100, 4412]}, {"ru": "Казалось, розы были смущены его словами.", "zh": "“没有人为你们而死。", "t": [4412, 8112]}, {"ru": "— Вы красивы, — добавил маленький принц, — но пусты.", "zh": "“没有人为你们而死。", "t": [8112, 12288]}, {"ru": "Ради вас не захочется умирать.", "zh": "不错，行人会认为我的玫瑰与你们没有两样，但只有她比你们重要，因为我给她浇了水，我给她盖上花罩，我给她竖起屏风，给她避风挡雨。", "t": [12288, 15238]}, {"ru": "Конечно, моя роза…", "zh": "不错，行人会认为我的玫瑰与你们没有两样，但只有她比你们重要，因为我给她浇了水，我给她盖上花罩，我给她竖起屏风，给她避风挡雨。", "t": [15238, 17650]}, {"ru": "Случайный прохожий сказал бы, что она похожа на вас.", "zh": "不错，行人会认为我的玫瑰与你们没有两样，但只有她比你们重要，因为我给她浇了水，我给她盖上花罩，我给她竖起屏风，给她避风挡雨。", "t": [17650, 21688]}, {"ru": "Но для меня она важнее вас всех.", "zh": "不错，行人会认为我的玫瑰与你们没有两样，但只有她比你们重要，因为我给她浇了水，我给她盖上花罩，我给她竖起屏风，给她避风挡雨。", "t": [21688, 24712]}, {"ru": "Ведь я поливал ее и помещал под стеклянный колпак.", "zh": "我为她杀死了几条毛虫（除了两三条我没杀，要让它们变成蝴蝶），我倾听她的抱怨，或她的吹嘘，有时也看着她默默无语的样子，因为她是我的玫瑰。", "t": [24712, 28812]}, {"ru": "Именно ее я прикрывал ширмой и именно с нее я сгонял гусениц, за исключением двух или трех — чтобы они превратились в бабочек.", "zh": "我为她杀死了几条毛虫（除了两三条我没杀，要让它们变成蝴蝶），我倾听她的抱怨，或她的吹嘘，有时也看着她默默无语的样子，因为她是我的玫瑰。", "t": [28812, 37175]}, {"ru": "Я слушал ее жалобы и бахвальство.", "zh": "” 他回到狐狸身边。", "t": [37175, 40412]}, {"ru": "Я даже слушал, как она молчит.", "zh": "“别了。", "t": [40412, 43575]}, {"ru": "Ведь это моя роза!", "zh": "“别了。", "t": [43575, 45800]}, {"ru": "Потом он вернулся к лису.", "zh": "”他说…… “别了，”狐狸说，“这就是我的秘密，它很简单：用心去看才能看清楚，用眼睛是看不见本质的东西的。", "t": [45800, 48325]}, {"ru": "— Прощай, — сказал он ему.", "zh": "”他说…… “别了，”狐狸说，“这就是我的秘密，它很简单：用心去看才能看清楚，用眼睛是看不见本质的东西的。", "t": [48325, 51175]}, {"ru": "— Прощай, — ответил лис.", "zh": "”他说…… “别了，”狐狸说，“这就是我的秘密，它很简单：用心去看才能看清楚，用眼睛是看不见本质的东西的。", "t": [51175, 53712]}, {"ru": "— Вот мой секрет.", "zh": "”他说…… “别了，”狐狸说，“这就是我的秘密，它很简单：用心去看才能看清楚，用眼睛是看不见本质的东西的。", "t": [53712, 55938]}, {"ru": "Он очень прост.", "zh": "” “用眼睛是看不见本质的东西的。", "t": [55938, 58100]}, {"ru": "Проницательно только сердце.", "zh": "” “用眼睛是看不见本质的东西的。", "t": [58100, 60838]}, {"ru": "Самое главное скрыто от глаз.", "zh": "” “用眼睛是看不见本质的东西的。", "t": [60838, 63912]}, {"ru": "— Главное скрыто от глаз, — повторил маленький принц, чтобы лучше запомнить.", "zh": "”小王子重复念叨这句话，为了把它牢牢记住。", "t": [63912, 69325]}, {"ru": "— Именно время, которое ты потратил на твою розу, делает ее для тебя такой значительной.", "zh": "“你为你的玫瑰失去的时间，使你的玫瑰变得重要了。", "t": [69325, 74975]}, {"ru": "— Время, которое я потратил на свою розу…— повторил маленький принц, чтобы лучше запомнить.", "zh": "” “我为我的玫瑰失去的时间，使我的玫瑰……”小王子说道，为了把它记住。", "t": [74975, 81288]}, {"ru": "— Люди забыли эту истину, — сказал лис.", "zh": "“人忘记了这条真理，”狐狸说，“但你不该忘。", "t": [81288, 84975]}, {"ru": "— Но ты не должен ее забывать.", "zh": "“人忘记了这条真理，”狐狸说，“但你不该忘。", "t": [84975, 87738]}, {"ru": "Ты навсегда в ответе за всех, кого приручил.", "zh": "你应该永远对你驯养的对象负责，你要对你的玫瑰负责……” “我要对我的玫瑰负责……”小王子反复念叨狐狸的教诲，为了牢牢记住它。", "t": [87738, 91400]}, {"ru": "И ты в ответе за твою розу.", "zh": "你应该永远对你驯养的对象负责，你要对你的玫瑰负责……” “我要对我的玫瑰负责……”小王子反复念叨狐狸的教诲，为了牢牢记住它。", "t": [91400, 94012]}, {"ru": "— Я в ответе за свою розу, — повторил маленький принц, чтобы лучше запомнить.", "zh": "你应该永远对你驯养的对象负责，你要对你的玫瑰负责……” “我要对我的玫瑰负责……”小王子反复念叨狐狸的教诲，为了牢牢记住它。", "t": [94012, 98474]}]}]}, {"id": "ch22", "title_ru": "Глава 22", "title_zh": "第 22 章", "paras": [{"id": "ch22p00", "audio": true, "sents": [{"ru": "— Здравствуй, — сказал маленький принц.", "zh": "”小王子说。", "t": [100, 3250]}, {"ru": "— Здравствуй, — ответил стрелочник.", "zh": "“你在这儿干什么？", "t": [3250, 6425]}, {"ru": "— Что ты здесь делаешь?", "zh": "” “我给旅客们分组。", "t": [6425, 8688]}, {"ru": "— спросил маленький принц.", "zh": "一千人为一批。", "t": [8688, 11312]}, {"ru": "— Я сортирую пассажиров, целыми тысячами, — ответил стрелочник.", "zh": "”扳道工说。", "t": [11312, 16375]}, {"ru": "— Я отправляю поезда, которые их увозят — то направо, то налево.", "zh": "“载乘客的火车也由我调度，它们有时开往左方，有时开往右方。", "t": [16375, 21388]}, {"ru": "В это время мимо задрожавшей будки стрелочника прогромыхал скорый поезд с ярко освещенными окнами.", "zh": "“他们行色匆匆。", "t": [21388, 28025]}, {"ru": "— Они очень спешат, — сказал маленький принц.", "zh": "“他们寻找什么？", "t": [28025, 31825]}, {"ru": "— Что они ищут?", "zh": "” “坐在火车头上的人也不知道他们要寻找什么。", "t": [31825, 34050]}, {"ru": "— Этого не знает даже машинист локомотива, — ответил стрелочник.", "zh": "”扳道工说。", "t": [34050, 38825]}, {"ru": "В это время освещенный скорый поезд прогрохотал в обратном направлении.", "zh": "第二列灯火通明的火车轰隆隆地，从相反的方向奔驰而来。", "t": [38825, 43650]}, {"ru": "— Они уже возвращаются?", "zh": "”小王子问…… “这列车坐的不是刚才那些人。", "t": [43650, 46162]}, {"ru": "— спросил маленький принц.", "zh": "”小王子问…… “这列车坐的不是刚才那些人。", "t": [46162, 48800]}, {"ru": "— Нет, это другие, — ответил стрелочник.", "zh": "”扳道工说。", "t": [48800, 52438]}, {"ru": "— Встречный поезд.", "zh": "“这是对开的火车。", "t": [52438, 54712]}, {"ru": "— Им не понравилось там, где они были?", "zh": "” “他们对他们的居住地不满意？", "t": [54712, 58000]}, {"ru": "— спросил маленький принц.", "zh": "” “人总是这山望着那山高的。", "t": [58000, 60625]}, {"ru": "— Они всегда всем недовольны, — ответил стрелочник.", "zh": "”扳道工说。", "t": [60625, 64612]}, {"ru": "Мимо прогремел третий освещенный скоростной состав.", "zh": "第三列灯火通明的火车也轰隆隆地响起来了。", "t": [64612, 68575]}, {"ru": "— А эти хотят догнать первых пассажиров?", "zh": "”小王子问。", "t": [68575, 71850]}, {"ru": "— спросил маленький принц.", "zh": "”小王子问。", "t": [71850, 73638]}]}, {"id": "ch22p01", "audio": true, "sents": [{"ru": "— Они их не преследуют, — ответил стрелочник.", "zh": "“他们从不追赶人，”扳道工说，“他们在车厢里睡大觉或打哈欠，只有孩子们才把鼻子贴在玻璃窗上看外面的世界。", "t": [100, 3912]}, {"ru": "— Внутри они спят или зевают.", "zh": "“他们从不追赶人，”扳道工说，“他们在车厢里睡大觉或打哈欠，只有孩子们才把鼻子贴在玻璃窗上看外面的世界。", "t": [3912, 6962]}, {"ru": "Только дети прижимают носы к стеклам.", "zh": "” “只有孩子才知道他们要寻觅什么。", "t": [6962, 10112]}, {"ru": "— Только дети знают, чего они ищут, — заметил маленький принц.", "zh": "” “只有孩子才知道他们要寻觅什么。", "t": [10112, 15012]}, {"ru": "— Они тратят свое время на тряпичную куклу, и она становится очень важной для них.", "zh": "“他们花不少时间与布娃娃玩，布娃娃变得很重要，如果有人抢走他们的布娃娃，他们就哭鼻子……” “他们是有运气的人……”", "t": [15012, 20712]}, {"ru": "Если ее у них отнимут, они плачут.", "zh": "“他们花不少时间与布娃娃玩，布娃娃变得很重要，如果有人抢走他们的布娃娃，他们就哭鼻子……” “他们是有运气的人……”", "t": [20712, 24188]}, {"ru": "— Хорошо им, — ответил стрелочник.", "zh": "“他们花不少时间与布娃娃玩，布娃娃变得很重要，如果有人抢走他们的布娃娃，他们就哭鼻子……” “他们是有运气的人……”", "t": [24188, 26562]}]}]}, {"id": "ch23", "title_ru": "Глава 23", "title_zh": "第 23 章", "paras": [{"id": "ch23p00", "audio": true, "sents": [{"ru": "— Здравствуй, — сказал маленький принц.", "zh": "”小王子说。", "t": [100, 3275]}, {"ru": "— Здравствуй, — ответил торговец.", "zh": "”商人说。", "t": [3275, 6188]}, {"ru": "Это был торговец усовершенствованными пилюлями, которые утоляли жажду.", "zh": "一个星期吃一颗这样的药丸，就不再需要喝水了。", "t": [6188, 11500]}, {"ru": "Проглотишь такую пилюлю, и целую неделю можно не пить.", "zh": "“为什么你卖这种药？", "t": [11500, 15875]}, {"ru": "— Зачем ты их продаешь?", "zh": "”小王子问。", "t": [15875, 18325]}, {"ru": "— спросил маленький принц.", "zh": "”小王子问。", "t": [18325, 20962]}, {"ru": "— От них большая экономия времени, — ответил торговец.", "zh": "“为了节省更多的时间，”商人说，“专家们计算过，每个星期能节省五十三分钟。", "t": [20962, 25262]}, {"ru": "— Специалисты подсчитали — пятьдесят три минуты в неделю.", "zh": "” “节省的这五十三分钟，有什么用途？", "t": [25262, 29362]}, {"ru": "— И что с этими пятьюдесятью тремя минутами делают?", "zh": "” “节省的这五十三分钟，有什么用途？", "t": [29362, 33262]}, {"ru": "— Делают, что хотят.", "zh": "” “人可以干自己愿意干的事……” 小王子想：“要是我节省下这五十三分钟，我就要悠闲自在地朝一泓泉水走去……”", "t": [33262, 35850]}, {"ru": "«Если бы у меня было лишних пятьдесят три минуты, — подумал про себя маленький принц, — я бы неспешно прогулялся к роднику…»", "zh": "” “人可以干自己愿意干的事……” 小王子想：“要是我节省下这五十三分钟，我就要悠闲自在地朝一泓泉水走去……”", "t": [35850, 42275]}]}]}, {"id": "ch24", "title_ru": "Глава 24", "title_zh": "第 24 章", "paras": [{"id": "ch24p00", "audio": true, "sents": [{"ru": "С момента моей аварии в пустыне прошло уже восемь дней.", "zh": "我的飞机在沙漠出故障的第八天，我听到了商人的故事，此时我储存的水已喝完了，一滴不剩。", "t": [100, 4288]}, {"ru": "Слушая историю про торговца, я допил последние капли моего запаса воды.", "zh": "我的飞机在沙漠出故障的第八天，我听到了商人的故事，此时我储存的水已喝完了，一滴不剩。", "t": [4288, 9325]}, {"ru": "— Твои истории очень забавны, — сказал я маленькому принцу, — но я все еще не починил свой самолет, вода у меня закончилась, и я тоже был бы счастлив, если бы мог неспешно прогуляться к роднику.", "zh": "你的这些回忆挺美好的，但我还没修好我的飞机，我的水也喝完了，如果我能悠闲自在地向一泓泉水走过去，我也会很幸福快活的！", "t": [9325, 20425]}, {"ru": "— Мой друг лис как-то сказал мне…", "zh": "” “我的朋友狐狸告诉我……” “我的小人儿，别再说狐狸的事了！", "t": [20425, 22475]}, {"ru": "— Дружок мой, речь теперь не о лисе!", "zh": "” “我的朋友狐狸告诉我……” “我的小人儿，别再说狐狸的事了！", "t": [22475, 25300]}, {"ru": "— Почему?", "zh": "” “我的朋友狐狸告诉我……” “我的小人儿，别再说狐狸的事了！", "t": [25300, 26912]}, {"ru": "— Потому что мне придется умереть от жажды.", "zh": "” “为什么？", "t": [26912, 30162]}, {"ru": "Кажется, он меня не понял, потому что ответил: — Хорошо иметь друга, даже если умрешь.", "zh": "” “因为我快渴死了……” 他听不懂我说的理由。", "t": [30162, 35925]}, {"ru": "Например, я очень рад, что у меня был друг лис.", "zh": "他说道： “有个朋友真好，哪怕命在旦夕。", "t": [35925, 40025]}, {"ru": "«Он не может по-настоящему оценить опасность, — подумал я.", "zh": "我很满意狐狸做了我的朋友……” 我想：“他不知道危险的可怕，他从未尝过饥渴的滋味。", "t": [40025, 43788]}, {"ru": "— Ведь он никогда не испытывал ни голода, ни жажды.", "zh": "我很满意狐狸做了我的朋友……” 我想：“他不知道危险的可怕，他从未尝过饥渴的滋味。", "t": [43788, 47200]}, {"ru": "Ему довольно лишь солнечных лучей…»", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [47200, 50525]}, {"ru": "Однако маленький принц, взглянув на меня, кажется, понял мои мысли.", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [50525, 55875]}, {"ru": "— Я тоже хочу пить…", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [55875, 58162]}, {"ru": "Давай поищем колодец.", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [58162, 60762]}, {"ru": "Я безнадежно махнул рукой — бессмысленно искать колодец наугад в безбрежной пустыне.", "zh": "在一望无际的沙漠中寻一口井，这不是太荒唐了吗？", "t": [60762, 66650]}, {"ru": "Тем не менее мы пустились в путь.", "zh": "但我们还是出发去寻找了。", "t": [66650, 69475]}, {"ru": "Мы прошли молча несколько часов.", "zh": "但我们还是出发去寻找了。", "t": [69475, 72562]}, {"ru": "Настала ночь, и в небе начали загораться звезды.", "zh": "我们默默地走了几个小时。", "t": [72562, 76462]}, {"ru": "Я смотрел на них, как во сне.", "zh": "夜幕降临，天上现出星星。", "t": [76462, 79425]}, {"ru": "От жажды меня немного лихорадило.", "zh": "由于干渴，我在发烧，看见星星，还以为自己在梦中呢。", "t": [79425, 82338]}, {"ru": "Слова маленького принца плясали у меня в голове.", "zh": "小王子说的话也似乎在我的脑海中跳跃。", "t": [82338, 85076]}]}, {"id": "ch24p01", "audio": true, "sents": [{"ru": "— Ты хочешь сказать, что тоже испытываешь жажду?", "zh": "“你也口渴了吗？", "t": [100, 3888]}, {"ru": "— спросил я его.", "zh": "”我问他。", "t": [3888, 6100]}, {"ru": "Он не ответил впрямую на мой вопрос, а лишь заметил: — Вода хороша и для сердца.", "zh": "他不回答我的问题，只简单地对我说： “水对心也有好处……” 我听不懂他的话，但我不做声……我知道不应该问他。", "t": [6100, 11638]}, {"ru": "Я не понял, что он хотел сказать, но промолчал.", "zh": "他不回答我的问题，只简单地对我说： “水对心也有好处……” 我听不懂他的话，但我不做声……我知道不应该问他。", "t": [11638, 15650]}, {"ru": "Я хорошо знал, что не стоит его расспрашивать.", "zh": "他走乏了，坐了下来。", "t": [15650, 19338]}, {"ru": "Он казался уставшим.", "zh": "他走乏了，坐了下来。", "t": [19338, 21812]}, {"ru": "Маленький принц присел на песок, и я сел рядом с ним.", "zh": "我靠着他坐下。", "t": [21812, 26225]}, {"ru": "Помолчав, он сказал: — Звезды великолепны; ведь где-то там есть цветок, хотя отсюда его и не видно.", "zh": "” 我应了一句：“当然。", "t": [26225, 33050]}, {"ru": "— Конечно, — ответил я и замолчал, глядя на гребни песка в лунном свете.", "zh": "“沙漠真美。", "t": [33050, 38275]}, {"ru": "— Пустыня так прекрасна, — добавил он.", "zh": "他说得不错。", "t": [38275, 41525]}, {"ru": "Это было верно.", "zh": "我们坐在沙丘上。", "t": [41525, 43550]}, {"ru": "Мне всегда нравилась пустыня.", "zh": "我们无所见，我们无所闻。", "t": [43550, 46488]}, {"ru": "Садишься на песчаную дюну.", "zh": "我们无所见，我们无所闻。", "t": [46488, 49162]}, {"ru": "Тишина.", "zh": "我们无所见，我们无所闻。", "t": [49162, 50775]}, {"ru": "Никакого движения.", "zh": "然而，有什么东西在静静地发光…… “沙漠美丽，因为沙漠的某处隐藏着一口井。", "t": [50775, 53312]}, {"ru": "И что-то мерцает в этой тишине…", "zh": "然而，有什么东西在静静地发光…… “沙漠美丽，因为沙漠的某处隐藏着一口井。", "t": [53312, 55362]}, {"ru": "— Пустыня хороша и потому, — сказал маленький принц, — что она где-то скрывает колодец.", "zh": "”小王子说。", "t": [55362, 61000]}, {"ru": "Я был удивлен, внезапно поняв про это таинственное мерцание песка.", "zh": "我吃了一惊，因为我突然明白，沙漠中那神秘的闪闪发亮的东西是什么了。", "t": [61000, 66025]}, {"ru": "Маленьким мальчиком я жил в старинном доме.", "zh": "我还是一个小男孩的时候，住在一幢古老大屋里。", "t": [66025, 69562]}, {"ru": "Легенда рассказывала, что где-то в нем было зарыто сокровище.", "zh": "传说里面埋藏着一件宝物。", "t": [69562, 73850]}, {"ru": "Конечно, никто его так и не нашел.", "zh": "当然，没有一个人能找得到它。", "t": [73850, 77025]}, {"ru": "А может, его никто и не искал.", "zh": "也许甚至没人去找它。", "t": [77025, 80188]}, {"ru": "Но оно придавало дому колдовское очарование.", "zh": "但它像给这幢屋子施了魔法，让它凭空增添了吸引力。", "t": [80188, 84000]}, {"ru": "Дом словно прятал тайну в глубине своего сердца…", "zh": "但它像给这幢屋子施了魔法，让它凭空增添了吸引力。", "t": [84000, 86988]}, {"ru": "— Да, — сказал я маленькому принцу, — когда речь идет о доме, о звездах или о пустыне.", "zh": "房里埋藏着秘密…… “你说得对，”我对小王子说，“房子也好，星星、沙漠也好，美化它们的东西是肉眼看不见的！", "t": [86988, 92800]}, {"ru": "То, что делает их прекрасными, скрыто от глаз.", "zh": "房里埋藏着秘密…… “你说得对，”我对小王子说，“房子也好，星星、沙漠也好，美化它们的东西是肉眼看不见的！", "t": [92800, 96050]}]}, {"id": "ch24p02", "audio": true, "sents": [{"ru": "— Я рад, — ответил он, — что ты согласен с моим лисом.", "zh": "” “我很欣慰，”他说，“你同意狐狸的看法。", "t": [100, 4388]}, {"ru": "Маленький принц задремал.", "zh": "” 小王子入睡了。", "t": [4388, 7100]}, {"ru": "Я взял его на руки и снова отправился в путь.", "zh": "我把他抱在怀里，继续走我们的路。", "t": [7100, 10888]}, {"ru": "Я был взволнован.", "zh": "我受了感动。", "t": [10888, 13188]}, {"ru": "Мне казалось, что я несу в руках хрупкое сокровище.", "zh": "我觉得我抱着一件脆弱的宝物。", "t": [13188, 17588]}, {"ru": "И мне казалось также, что на всей Земле нет ничего более хрупкого.", "zh": "我甚至觉得地球上没有比他更脆弱的东西了。", "t": [17588, 22262]}, {"ru": "Я смотрел при свете луны на его бледный лоб, на его закрытые глаза, на колеблющиеся от ветра пряди волос и говорил себе, что вижу лишь внешность.", "zh": "借着银色的月光，我细细看他苍白的前额、闭着的双目、随风抖动的绺绺秀发。", "t": [22262, 31338]}, {"ru": "Ведь самое важное скрыто от глаз…", "zh": "我心想：“我看见的只是一具躯壳，最重要的东西是看不见的……” 他半张的嘴唇上泛出浅浅的微笑。", "t": [31338, 34612]}, {"ru": "Его полуоткрытые губы тронула едва заметная улыбка, и я подумал: «Этот уснувший принц кажется мне таким трогательным, потому что он верен своему цветку.", "zh": "我又想：“这位睡着了的小王子打动了我，而打动了我的是他对花的忠贞。", "t": [34612, 43850]}, {"ru": "Образ его розы светится в нем наподобие пламени свечи, даже когда он спит».", "zh": "玫瑰花的倩影如同灯焰，在他心里闪闪发亮，即使是在梦乡……” 我把他想像得更脆弱了。", "t": [43850, 49538]}, {"ru": "И я еще раз почувствовал, насколько он хрупок.", "zh": "玫瑰花的倩影如同灯焰，在他心里闪闪发亮，即使是在梦乡……” 我把他想像得更脆弱了。", "t": [49538, 53350]}, {"ru": "Такое пламя нужно хорошо охранять, ведь его может задуть любой порыв ветра.", "zh": "灯是需要我们小心保护的，一股风就会把它吹灭……我就这样走着，曙光初露时我看见了那口井。", "t": [53350, 58725]}, {"ru": "Я шел так и шел, а на рассвете увидел колодец.", "zh": "灯是需要我们小心保护的，一股风就会把它吹灭……我就这样走着，曙光初露时我看见了那口井。", "t": [58725, 61900]}]}]}, {"id": "ch25", "title_ru": "Глава 25", "title_zh": "第 25 章", "paras": [{"id": "ch25p00", "audio": true, "sents": [{"ru": "— Люди, — сказал маленький принц, — они забираются в скорые поезда, но они не знают, к чему они стремятся.", "zh": "“人挤在快车的车厢里，”小王子说，“却不知道他们要寻找什么。", "t": [100, 7150]}, {"ru": "Поэтому они попусту суетятся и бегают по кругу.", "zh": "他们焦躁不安，团团乱转……” 他又说： “这又何苦呢……” 我们找到的井不像撒哈拉沙漠的井。", "t": [7150, 11125]}, {"ru": "Потом он добавил: — В этом нет смысла…", "zh": "他们焦躁不安，团团乱转……” 他又说： “这又何苦呢……” 我们找到的井不像撒哈拉沙漠的井。", "t": [11125, 14388]}, {"ru": "Колодец, до которого мы добрались, не был обычным.", "zh": "他们焦躁不安，团团乱转……” 他又说： “这又何苦呢……” 我们找到的井不像撒哈拉沙漠的井。", "t": [14388, 18650]}, {"ru": "Ведь колодцы Сахары — простые ямы, вырытые в песке.", "zh": "撒哈拉沙漠的井是在沙里挖个洞，而我们找到的这口井与村子里的井一样，可是这儿没有一个村子。", "t": [18650, 22925]}, {"ru": "Этот же напоминал деревенский колодец, хотя никакой деревни поблизости не было.", "zh": "我以为我正在做梦。", "t": [22925, 28362]}, {"ru": "Мне казалось, что я грежу.", "zh": "我以为我正在做梦。", "t": [28362, 31375]}, {"ru": "— Это странно, — сказал я маленькому принцу, — тут все наготове: ворот, ведро и веревка…", "zh": "“这就奇了，”我对小王子说，“这井一切齐备：辘轳，水桶，绳子……” 他笑了，抓住绳子，转动辘轳。", "t": [31375, 37675]}, {"ru": "В ответ он засмеялся, потянул веревку, и ворот закрутился.", "zh": "辘轳吱吱呀呀地叫唤，活像一只老风信鸡在风长睡时的叫唤。", "t": [37675, 42488]}, {"ru": "При этом ворот застонал, как стонет старый флюгер по давно заснувшему ветру.", "zh": "辘轳吱吱呀呀地叫唤，活像一只老风信鸡在风长睡时的叫唤。", "t": [42488, 47738]}, {"ru": "— Ты слышишь, — сказал маленький принц, — мы пробудили этот колодец, и он запел.", "zh": "它在唱歌呢……” 我不忍心看他劳力费神。", "t": [47738, 53550]}, {"ru": "Я не хотел, чтобы он утруждал себя.", "zh": "“让我来干吧，”我对他说，“你干这活太重了。", "t": [53550, 56800]}, {"ru": "— Пусти-ка, — сказал я ему, — тебе эта работа не по силам.", "zh": "“让我来干吧，”我对他说，“你干这活太重了。", "t": [56800, 61062]}, {"ru": "Я медленно поднял ведро и тяжело опустил его на край колодца.", "zh": "” 我轻轻把水桶提到井口，垂直放进井内。", "t": [61062, 65762]}, {"ru": "В моих ушах все еще раздавалось пение ворота, а на дрожащей поверхности воды играли блики солнца.", "zh": "倾听着辘轳的歌声，还看见在荡漾的井水中摇动的太阳。", "t": [65762, 72575]}, {"ru": "— Дай мне испить этой воды, — сказал маленький принц, — дай мне ее.", "zh": "“我渴望的就是这样的水，”小王子说，“让我喝上几口……”我明白他要寻找什么了。", "t": [72575, 76525]}]}, {"id": "ch25p01", "audio": true, "sents": [{"ru": "И я понял, что он искал.", "zh": "我把桶举到他的唇边。", "t": [100, 2750]}, {"ru": "Я приподнял ведро до его губ.", "zh": "他闭着双目喝水。", "t": [2750, 5550]}, {"ru": "Он пил с закрытыми глазами.", "zh": "水甜得有如过节。", "t": [5550, 8275]}, {"ru": "Эта вода была для него праздником.", "zh": "这水不仅是饮料，它还是别的东西。", "t": [8275, 11188]}, {"ru": "Она была совсем другой, не предназначенной для обычного питья.", "zh": "它是经过星光下的跋涉，在辘轳的歌声中和在我双臂的努力下诞生的。", "t": [11188, 15762]}, {"ru": "Эта вода родилась под звездами, под пение колодезного ворота, благодаря усилиям моих рук.", "zh": "它像礼物一样愉悦心灵。", "t": [15762, 21975]}, {"ru": "Она была приятна для сердца, как подарок.", "zh": "我还是小男孩的时候，圣诞树上挂的灯、子夜弥撒的音乐、甜蜜的微笑，是我收到的圣诞礼物的光芒。", "t": [21975, 25525]}, {"ru": "Когда я был маленьким мальчиком, свет рождественской елки, церковная музыка вечерней службы и нежность царящих вокруг улыбок тоже составляли для меня сияющий подарок праздника, который я получал.", "zh": "“你们这儿的人在一个园里种植五千株玫瑰……但他们却找不到他们寻觅的东西……” “他们没找到。", "t": [25525, 37162]}, {"ru": "— Люди здесь у тебя, — сказал маленький принц, — выращивают пять тысяч роз в одном саду и при этом не находят, что ищут…", "zh": "”我说…… “然而他们寻找的东西可以在一朵玫瑰或一点点水里找到的……” “不错。", "t": [37162, 43962]}, {"ru": "— Не находят, — подтвердил я…", "zh": "”我回答说。", "t": [43962, 45912]}, {"ru": "— А ведь все, что они ищут, можно найти в одной розе и в нескольких глотках воды.", "zh": "小王子又说： “然而肉眼是看不见的，要用心灵去寻找。", "t": [45912, 51138]}, {"ru": "— Конечно, — согласился я.", "zh": "” 我喝了水，呼吸畅通了。", "t": [51138, 52650]}, {"ru": "А маленький принц добавил: — Их глаза слепы.", "zh": "天亮时分，沙子颜色如蜜。", "t": [52650, 56162]}, {"ru": "Надо искать сердцем.", "zh": "我也喜欢蜜般的颜色。", "t": [56162, 58575]}, {"ru": "Я вдоволь напился.", "zh": "我也喜欢蜜般的颜色。", "t": [58575, 60938]}, {"ru": "На рассвете дышалось легко.", "zh": "但为什么我的心里总有点不快乐呢？", "t": [60938, 63600]}, {"ru": "Песок был медового цвета.", "zh": "…… “你可要履行诺言啊。", "t": [63600, 66325]}, {"ru": "Его оттенки радовали меня.", "zh": "…… “你可要履行诺言啊。", "t": [66325, 69062]}, {"ru": "Мне не о чем было больше тревожиться и грустить.", "zh": "”小王子轻声对我说，他又靠近我坐着。", "t": [69062, 72750]}, {"ru": "— Ты ведь сдержишь свое обещание?", "zh": "“什么诺言？", "t": [72750, 75925]}, {"ru": "— спросил маленький принц, сев рядом со мной.", "zh": "” “你知道的呀……给我的绵羊画一个口罩，我要对我的花儿负责呀！", "t": [75925, 79762]}, {"ru": "— Какое обещание?", "zh": "” “你知道的呀……给我的绵羊画一个口罩，我要对我的花儿负责呀！", "t": [79762, 82262]}, {"ru": "— Ты знаешь… намордник для моего барашка.", "zh": "” 我从口袋里掏出画稿。", "t": [82262, 85825]}, {"ru": "Я ведь в ответе за мой цветок.", "zh": "” 我从口袋里掏出画稿。", "t": [85825, 87825]}]}, {"id": "ch25p02", "audio": true, "sents": [{"ru": "Я вынул из кармана мои наброски.", "zh": "小王子看后，笑着对我说： “你画的猴面包树有点像卷心菜……” “呀！", "t": [100, 3112]}, {"ru": "Взглянув на них, маленький принц рассмеялся.", "zh": "小王子看后，笑着对我说： “你画的猴面包树有点像卷心菜……” “呀！", "t": [3112, 7112]}, {"ru": "— Твои баобабы похожи на цветную капусту…", "zh": "” 我还为我画的猴面包树自鸣得意呢！", "t": [7112, 9862]}, {"ru": "— Вот как?", "zh": "” 我还为我画的猴面包树自鸣得意呢！", "t": [9862, 10574]}]}, {"id": "ch25p03", "audio": true, "sents": [{"ru": "А я был так горд своими баобабами…", "zh": "“你画的狐狸……它的耳朵……有点像角……太长了！", "t": [100, 2400]}, {"ru": "— Твой лис… его уши… они немного похожи на оленьи рога — слишком длинные.", "zh": "” 他还在笑。", "t": [2400, 8112]}, {"ru": "И он снова рассмеялся.", "zh": "“你不公平，小人儿。", "t": [8112, 10638]}, {"ru": "— Ты несправедлив ко мне, дружок.", "zh": "我并不会画画，只会画打开了肚子的蟒蛇和没打开肚子的蟒蛇。", "t": [10638, 13575]}, {"ru": "Я ведь вообще ничего не умел рисовать, кроме удавов — снаружи и изнутри.", "zh": "” “啊！", "t": [13575, 19050]}, {"ru": "— А…", "zh": "很不错的嘛，孩子们看得懂的。", "t": [19050, 20300]}, {"ru": "Тогда сгодится.", "zh": "很不错的嘛，孩子们看得懂的。", "t": [20300, 22525]}, {"ru": "Дети поймут, — ответил маленький принц.", "zh": "”他说。", "t": [22525, 26038]}, {"ru": "Я взял карандаш и нарисовал намордник.", "zh": "我用铅笔画了一个口罩，把它交给他的时候，我的心揪得紧紧的： “你已有了我不知道的计划吧……” 但他避而不答。", "t": [26038, 29462]}, {"ru": "Но когда я протянул ему рисунок, мое сердце дрогнуло: — Что ты собираешься делать?", "zh": "我用铅笔画了一个口罩，把它交给他的时候，我的心揪得紧紧的： “你已有了我不知道的计划吧……” 但他避而不答。", "t": [29462, 34962]}, {"ru": "Ты мне не говорил…", "zh": "我用铅笔画了一个口罩，把它交给他的时候，我的心揪得紧紧的： “你已有了我不知道的计划吧……” 但他避而不答。", "t": [34962, 36950]}, {"ru": "На это маленький принц ничего не ответил.", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [36950, 40250]}, {"ru": "Он лишь сказал: — Ты знаешь… завтра ровно год, как я упал на Землю….", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [40250, 45525]}, {"ru": "Он замолк, а потом добавил: — Это случилось неподалеку отсюда.", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [45525, 50075]}, {"ru": "При этом он покраснел.", "zh": "不知何故，我有说不出来的惆怅悲哀。", "t": [50075, 52375]}, {"ru": "У меня защемило сердце, хотя я и не понимал почему.", "zh": "不知何故，我有说不出来的惆怅悲哀。", "t": [52375, 56625]}, {"ru": "В голове у меня возник единственный вопрос: — Так значит утром, восемь дней назад, когда я увидел тебя впервые, ты оказался здесь не случайно?", "zh": "我提出了一个问题： “这么说，一个星期之前，认识你的那天早上，你不是偶尔一人来到这远离人烟的沙漠的？", "t": [56625, 65275]}, {"ru": "Совсем один, за тысячу миль от человеческого жилья!", "zh": "你要回到你的降落点去？", "t": [65275, 69362]}, {"ru": "Ты возвращался к месту своего падения?", "zh": "我犹豫着又问： “也许是为了纪念降落周年？", "t": [69362, 72800]}, {"ru": "Маленький принц снова покраснел.", "zh": "我犹豫着又问： “也许是为了纪念降落周年？", "t": [72800, 75762]}, {"ru": "А я добавил нерешительно: — В связи с этой годовщиной?", "zh": "……” 小王子的脸再次红了。", "t": [75762, 78800]}]}, {"id": "ch25p04", "audio": true, "sents": [{"ru": "Маленький принц покраснел снова.", "zh": "他从不回答我提的问题。", "t": [100, 3125]}, {"ru": "Он никогда не отвечал на вопросы, но, ведь когда краснеешь, это означает «да», не так ли?", "zh": "但一个人脸红，就意味着默认，意味着做了“是的”的回答，对吧？", "t": [3125, 9538]}, {"ru": "— Вот как?", "zh": "“啊！", "t": [9538, 11300]}, {"ru": "— сказал я ему.", "zh": "”我对他说，“我怕……” 他却对我说： “现在你该干活了。", "t": [11300, 13525]}, {"ru": "— Боюсь, что…", "zh": "”我对他说，“我怕……” 他却对我说： “现在你该干活了。", "t": [13525, 15825]}, {"ru": "Но он меня перебил: — Ты должен работать.", "zh": "”我对他说，“我怕……” 他却对我说： “现在你该干活了。", "t": [15825, 19125]}, {"ru": "Отправляйся к своей машине.", "zh": "你该到你的机器旁忙活儿了。", "t": [19125, 21875]}, {"ru": "Я подожду тебя здесь.", "zh": "你该到你的机器旁忙活儿了。", "t": [21875, 24288]}, {"ru": "Возвращайся завтра вечером…", "zh": "我在这儿等你，明天晚上再来……” 但我不放心。", "t": [24288, 26962]}, {"ru": "От этих слов мне не стало спокойнее.", "zh": "我在这儿等你，明天晚上再来……” 但我不放心。", "t": [26962, 30312]}, {"ru": "Я вспомнил о лисе.", "zh": "我想起了狐狸的事，让别人驯养，难免要掉掉眼泪……", "t": [30312, 32775]}, {"ru": "Рискуешь расплакаться, если дал себя приручить…", "zh": "我想起了狐狸的事，让别人驯养，难免要掉掉眼泪……", "t": [32775, 35687]}]}]}, {"id": "ch26", "title_ru": "Глава 26", "title_zh": "第 26 章", "paras": [{"id": "ch26p00", "audio": true, "sents": [{"ru": "Рядом с колодцем находились руины старой каменной стены.", "zh": "井旁有一堵断墙残壁。", "t": [100, 4350]}, {"ru": "Когда следующим вечером я возвратился после своей работы, еще издали увидел, что маленький принц сидит на ней, свесив ноги вниз.", "zh": "我听见他说： “你不记得了吗？", "t": [4350, 12750]}, {"ru": "И я услышал, как он сказал кому-то: — Разве ты об этом забыла?", "zh": "” 无疑有另一个声音回了他的话，因为他反驳说： “没错！", "t": [12750, 17200]}, {"ru": "Это было не здесь…", "zh": "没错！", "t": [17200, 19300]}, {"ru": "Без сомнения, кто-то ему ответил, потому что он возразил: — Да, нет же!", "zh": "没错！", "t": [19300, 24525]}, {"ru": "Ровно год назад, но не тут.", "zh": "就是这一天，但不是这个地方……” 我向断墙残壁走过去，我看不见也听不见有什么人在那儿。", "t": [24525, 27525]}, {"ru": "Я подходил к стене, но по-прежнему никого не видел и не слышал.", "zh": "就是这一天，但不是这个地方……” 我向断墙残壁走过去，我看不见也听不见有什么人在那儿。", "t": [27525, 32050]}, {"ru": "Однако маленький принц снова ответил: — Ну конечно.", "zh": "然而小王子又反驳了： “……当然，你会看到我留在沙地上的足迹，看到它是从哪儿开始的。", "t": [32050, 35938]}, {"ru": "Ты заметишь мои следы на песке.", "zh": "你在那儿等我就行了。", "t": [35938, 38750]}, {"ru": "Тебе надо будет только меня подождать.", "zh": "你在那儿等我就行了。", "t": [38750, 41788]}, {"ru": "Я приду этой ночью…", "zh": "今夜我会在那儿等你。", "t": [41788, 44350]}, {"ru": "Я был уже в двадцати метрах от стены, но по-прежнему никого не видел.", "zh": "” 我离开墙才二十米，还是一无所见。", "t": [44350, 49000]}, {"ru": "А маленький принц, помолчав, спросил: — У тебя хороший яд?", "zh": "小王子沉默片刻后又说： “你有毒液吗？", "t": [49000, 53850]}, {"ru": "Уверена, что я не буду долго мучиться?", "zh": "你能肯定不让我经受很久的痛苦？", "t": [53850, 57238]}, {"ru": "Я остановился, сердце мое сжалось, но я все еще не понимал всего до конца.", "zh": "我仍然听不懂他的话。", "t": [57238, 62638]}, {"ru": "— А теперь уходи, — сказал маленький принц, — я хочу спуститься.", "zh": "“我要跳下去了！", "t": [62638, 67388]}, {"ru": "Я опустил глаза к основанию стены и отпрянул в сторону.", "zh": "一条黄蛇正仰头朝向小王子。", "t": [67388, 71688]}, {"ru": "Внизу к маленькому принцу тянулась желтая змейка.", "zh": "这种黄蛇最毒了，三十秒钟内就能要你的命。", "t": [71688, 75588]}, {"ru": "Такая может убить за полминуты.", "zh": "这种黄蛇最毒了，三十秒钟内就能要你的命。", "t": [75588, 78525]}]}, {"id": "ch26p01", "audio": true, "sents": [{"ru": "Нашаривая в кармане револьвер, я подался вперед, но, заслышав шум, змейка мягко скользнула по песку и с тихим металлическим звуком исчезла среди камней, словно струйка высыхающей воды.", "zh": "蛇听到我的脚步声，轻轻地溜进沙里，如颓然跌落的水柱，不慌不忙地钻进石缝里，发出轻微的金属的声音。", "t": [100, 11212]}, {"ru": "Я подбежал к стене как раз вовремя, чтобы подхватить на руки моего малыша принца.", "zh": "我及时赶到墙边，用双臂接住我的小人儿。", "t": [11212, 16888]}, {"ru": "Он был бледен, как снег.", "zh": "“怎么回事，你和蛇说话了？", "t": [16888, 19650]}, {"ru": "— Что это ты задумал?!", "zh": "“怎么回事，你和蛇说话了？", "t": [19650, 21975]}, {"ru": "Зачем ты беседуешь со змеями?", "zh": "” 我解下他从不离身的金围巾，用水湿湿他的太阳穴，给他喝水。", "t": [21975, 24938]}, {"ru": "Я развязал его неизменный золотистый шарф.", "zh": "” 我解下他从不离身的金围巾，用水湿湿他的太阳穴，给他喝水。", "t": [24938, 28512]}, {"ru": "Я смочил ему виски и дал попить.", "zh": "现在我不敢再向他提什么问题了。", "t": [28512, 31762]}, {"ru": "Я не решался ничего у него спрашивать.", "zh": "现在我不敢再向他提什么问题了。", "t": [31762, 34900]}, {"ru": "Он серьезно посмотрел на меня и обвил мою шею руками.", "zh": "他神情凝重地看着我，双臂搂住我的脖子。", "t": [34900, 39238]}, {"ru": "Я чувствовал, что его сердце бьется,", "zh": "我感觉到他的心的狂跳，如同中弹濒死的小鸟。", "t": [39238, 41800]}]}, {"id": "ch26p02", "audio": true, "sents": [{"ru": "как сердце подстреленной из ружья и умирающей птицы.", "zh": "他对我说：“你找到了机器的毛病，我很高兴。", "t": [100, 4212]}, {"ru": "И он сказал мне: — Я рад, что ты разобрался со своей машиной.", "zh": "你可以回家了……” “你怎么知道的？", "t": [4212, 8750]}, {"ru": "Теперь ты сможешь вернуться домой.", "zh": "” 我来找他，正是要告诉他：出乎我的意料，我竟修好了我的飞机。", "t": [8750, 11650]}, {"ru": "— Как ты узнал?", "zh": "” 我来找他，正是要告诉他：出乎我的意料，我竟修好了我的飞机。", "t": [11650, 13500]}, {"ru": "Я как раз собирался рассказать ему, что вопреки всему я успешно закончил свою работу.", "zh": "” 我来找他，正是要告诉他：出乎我的意料，我竟修好了我的飞机。", "t": [13500, 19362]}, {"ru": "Он ничего не ответил на мой вопрос и лишь сказал: — Сегодня я тоже возвращаюсь к себе домой…", "zh": "他不回答我的问题，却又说： “今天我也要回家了……” 然后，他神色凄伤，黯然说道： “我的家要远多了……也难回去得多……” 我感觉到发生了非比寻常的事情。", "t": [19362, 25062]}, {"ru": "А потом добавил грустно: — Но это гораздо дальше и гораздо труднее…", "zh": "他不回答我的问题，却又说： “今天我也要回家了……” 然后，他神色凄伤，黯然说道： “我的家要远多了……也难回去得多……” 我感觉到发生了非比寻常的事情。", "t": [25062, 29962]}, {"ru": "Я почувствовал, что происходит что-то необычное.", "zh": "我把他搂进怀里，如同他是个小孩子。", "t": [29962, 33925]}, {"ru": "Я сжимал его в своих объятиях, как маленького ребенка, и тем не менее мне казалось, что он скользит в какую-то пропасть, а я не в силах его удержать.", "zh": "然而我觉得他直往深渊里坠下去，我一点也抓不住他…… 他目光严肃，落到远方。", "t": [33925, 43050]}, {"ru": "Взгляд у него был серьезный, но какой-то потерянный.", "zh": "我有口罩……” 他凄凉地笑笑。", "t": [43050, 47088]}, {"ru": "— У меня есть твой барашек.", "zh": "我等了许久。", "t": [47088, 49788]}, {"ru": "И у меня есть твой ящик для него.", "zh": "我感觉到他的身体逐渐恢复了温暖。", "t": [49788, 52775]}, {"ru": "И у меня есть намордник…", "zh": "我感觉到他的身体逐渐恢复了温暖。", "t": [52775, 55425]}, {"ru": "При этих словах он печально улыбнулся.", "zh": "“小人儿，你害怕了……” 当然，他害怕！", "t": [55425, 58762]}, {"ru": "Я долго ждал, чувствуя, как он понемногу приходит в себя.", "zh": "他温和地笑笑： “今晚我会更害怕！", "t": [58762, 63338]}, {"ru": "— Малыш, ты боишься…", "zh": "” 我又一次体会到无可奈何的感觉。", "t": [63338, 65862]}, {"ru": "Конечно, ему было страшно.", "zh": "” 我又一次体会到无可奈何的感觉。", "t": [65862, 68688]}, {"ru": "— Сегодня вечером мне будет гораздо страшнее…", "zh": "我全身冰冷。", "t": [68688, 72312]}, {"ru": "Меня снова словно обдало холодом от ощущения надвигающейся непоправимой беды.", "zh": "他的笑声对我来说，如同沙漠里的一口井。", "t": [72312, 77738]}, {"ru": "И я понял — мне невыносимо думать, что я больше никогда не услышу его смех.", "zh": "“小人儿，我还想听到你的笑声……” 但他对我说： “今夜是我到这儿的一周年。", "t": [77738, 82988]}, {"ru": "Ведь он был для меня словно родник в пустыне.", "zh": "“小人儿，我还想听到你的笑声……” 但他对我说： “今夜是我到这儿的一周年。", "t": [82988, 86475]}, {"ru": "— Малыш, я хочу и дальше слышать твой смех…", "zh": "我的星星正好在我去年降落处的正上方……” “小人儿，蛇呀、约会呀、星星的故事，莫非都是一场噩梦？", "t": [86475, 89326]}]}, {"id": "ch26p03", "audio": true, "sents": [{"ru": "А он мне ответил: — Этой ночью моя звезда будет точно над тем местом, куда я упал ровно год назад…", "zh": "我的星星正好在我去年降落处的正上方……” “小人儿，蛇呀、约会呀、星星的故事，莫非都是一场噩梦？", "t": [100, 5762]}, {"ru": "— Малыш, пожалуйста, скажи мне, ведь вся эта история со змеей и свидание со звездой не более, чем просто дурной сон?", "zh": "……” 但他不回答我的问题。", "t": [5762, 12838]}, {"ru": "Он не ответил на мой вопрос и лишь сказал: — То, что важно, скрыто от глаз…", "zh": "他对我说： “最重要的东西，是肉眼看不到的……” “当然……” “花儿也是这样，如果你爱上了一朵长在一颗星星里的花儿，夜里看看星空，你会觉得甜蜜。", "t": [12838, 17212]}, {"ru": "— Ну, конечно…", "zh": "他对我说： “最重要的东西，是肉眼看不到的……” “当然……” “花儿也是这样，如果你爱上了一朵长在一颗星星里的花儿，夜里看看星空，你会觉得甜蜜。", "t": [17212, 18412]}, {"ru": "— Это как с цветком.", "zh": "所有的星星都像开了花。", "t": [18412, 20338]}, {"ru": "Если ты любишь цветок, который находится на далекой звезде, ночью приятно смотреть на небо.", "zh": "所有的星星都像开了花。", "t": [20338, 26450]}, {"ru": "Все звезды расцветают…", "zh": "” “不错……” “水也是这样。", "t": [26450, 28150]}, {"ru": "— Ну, конечно…", "zh": "你给我喝的水，有了辘轳和绳子，水就如同音乐……你记得……它是甘甜的。", "t": [28150, 29400]}, {"ru": "— И это как с водой.", "zh": "你给我喝的水，有了辘轳和绳子，水就如同音乐……你记得……它是甘甜的。", "t": [29400, 31425]}, {"ru": "Та, которую дал мне ты, была как музыка…", "zh": "你给我喝的水，有了辘轳和绳子，水就如同音乐……你记得……它是甘甜的。", "t": [31425, 35025]}, {"ru": "Ворот и веревка…", "zh": "” “不错。", "t": [35025, 37325]}, {"ru": "Ты помнишь?..", "zh": "” “不错。", "t": [37325, 39225]}, {"ru": "Она была прекрасна.", "zh": "” “不错。", "t": [39225, 40613]}]}, {"id": "ch26p04", "audio": true, "sents": [{"ru": "— Конечно…", "zh": "” “夜里你仰望星空吧，我的那颗星太渺小，没法子告诉你它在哪儿。", "t": [100, 1050]}, {"ru": "— Ночью ты будешь смотреть на звезды.", "zh": "” “夜里你仰望星空吧，我的那颗星太渺小，没法子告诉你它在哪儿。", "t": [1050, 3800]}, {"ru": "Мой дом слишком мал, чтобы я тебе показал, где находится моя звезда.", "zh": "这样更好……你就把我的星看做是万千星星中的一颗吧，这样你就会爱看所有的星星……它们全都成了你的朋友。", "t": [3800, 8788]}, {"ru": "Но так даже лучше.", "zh": "这样更好……你就把我的星看做是万千星星中的一颗吧，这样你就会爱看所有的星星……它们全都成了你的朋友。", "t": [8788, 11175]}, {"ru": "Моя будет для тебя лишь одной из них, и ты будешь любоваться всеми.", "zh": "这样更好……你就把我的星看做是万千星星中的一颗吧，这样你就会爱看所有的星星……它们全都成了你的朋友。", "t": [11175, 16012]}, {"ru": "Они все будут твоими друзьями.", "zh": "然后我会赠给你一份礼物……” 他还在笑。", "t": [16012, 18912]}, {"ru": "И потом, я сделаю тебе подарок…", "zh": "然后我会赠给你一份礼物……” 他还在笑。", "t": [18912, 22088]}, {"ru": "И маленький принц снова рассмеялся.", "zh": "“啊，小人儿，小人儿，我喜欢听你的笑声！", "t": [22088, 25250]}, {"ru": "— Ах, малыш, малыш!", "zh": "“啊，小人儿，小人儿，我喜欢听你的笑声！", "t": [25250, 28225]}, {"ru": "Мне нравится слушать твой смех.", "zh": "” “这正是我给你的礼物……这就和水一样……” “你想说什么？", "t": [28225, 31175]}, {"ru": "— Это и будет моим подарком… как с водой…", "zh": "” “这正是我给你的礼物……这就和水一样……” “你想说什么？", "t": [31175, 34038]}, {"ru": "— Что ты хочешь этим сказать?", "zh": "” “不同的人有不同的星星。", "t": [34038, 36425]}, {"ru": "— У каждого человека свои звезды.", "zh": "” “不同的人有不同的星星。", "t": [36425, 39362]}, {"ru": "Для тех, кто путешествует, они путеводные.", "zh": "” “不同的人有不同的星星。", "t": [39362, 43400]}, {"ru": "Для прочих они лишь маленькие огоньки.", "zh": "星星是旅行的人的向导，星星只是其他人的小灯，星星是学者研究的问题，星星是我说过的那个商人的金子。", "t": [43400, 46900]}, {"ru": "Для других, ученых, они являются загадками.", "zh": "星星是旅行的人的向导，星星只是其他人的小灯，星星是学者研究的问题，星星是我说过的那个商人的金子。", "t": [46900, 51200]}, {"ru": "Для моего бизнесмена они были из золота.", "zh": "但所有的星星都沉默不语。", "t": [51200, 54775]}, {"ru": "Но все звезды молчат.", "zh": "但所有的星星都沉默不语。", "t": [54775, 57312]}, {"ru": "У тебя же будут звезды, которых нет ни у кого больше.", "zh": "你的那颗星星是别人没有的……” “你想说什么？", "t": [57312, 61388]}, {"ru": "— Что ты хочешь этим сказать?", "zh": "你的那颗星星是别人没有的……” “你想说什么？", "t": [61388, 64088]}, {"ru": "— Ночью ты будешь смотреть на небо, и, поскольку я буду жить на одной из звезд и буду смеяться на одной из них, тебе будет казаться, что все они смеются для тебя.", "zh": "” “既然我住在天上一颗星星里，既然我在其中一颗星星里笑，这就如同所有的星星都在冲你笑，你就拥有无数会笑的星星了！", "t": [64088, 73562]}, {"ru": "У тебя будут звезды, которые умеют смеяться!", "zh": "“你得到了安慰之后（人常常自我安慰），你会为认识我而高兴。", "t": [73562, 77362]}, {"ru": "И он снова залился смехом.", "zh": "“你得到了安慰之后（人常常自我安慰），你会为认识我而高兴。", "t": [77362, 80112]}, {"ru": "— А когда ты утешишься, — ведь всегда утешаются, — ты будешь рад, что знал меня.", "zh": "你会成为我永远的朋友，你会想与我一起笑。", "t": [80112, 85725]}, {"ru": "Ты всегда будешь оставаться моим другом.", "zh": "有时候，当你想笑而打开窗户的时候……你的朋友看见你仰望星空独自发笑，他们一定会惊讶，你就对他们说：‘是的，我看见星星就要笑！", "t": [85725, 88962]}, {"ru": "Ты будешь смеяться вместе со мной.", "zh": "有时候，当你想笑而打开窗户的时候……你的朋友看见你仰望星空独自发笑，他们一定会惊讶，你就对他们说：‘是的，我看见星星就要笑！", "t": [88962, 91975]}, {"ru": "И твои друзья будут удивляться, отчего ты смеешься, глядя в небо.", "zh": "有时候，当你想笑而打开窗户的时候……你的朋友看见你仰望星空独自发笑，他们一定会惊讶，你就对他们说：‘是的，我看见星星就要笑！", "t": [91975, 96875]}]}, {"id": "ch26p05", "audio": true, "sents": [{"ru": "А ты им ответишь, что звезды всегда заставляют тебя смеяться.", "zh": "’他们会以为你神经出了毛病。", "t": [100, 3075]}, {"ru": "И они подумают, что ты слегка тронулся.", "zh": "看来是我捉弄了你了……” 他还在笑。", "t": [3075, 6550]}, {"ru": "Да, я сыграю с тобой забавную шутку…", "zh": "“这样一来，我给你的不是星星，而是一大批会笑的小铃铛……” 他还在笑。", "t": [6550, 9912]}, {"ru": "И маленький принц опять рассмеялся.", "zh": "“这样一来，我给你的不是星星，而是一大批会笑的小铃铛……” 他还在笑。", "t": [9912, 13212]}, {"ru": "— Похоже на то, как если бы я дал тебе вместо звезд целую кучу бубенчиков, которые умеют смеяться.", "zh": "然后他收敛了笑容： “今晚……你知道……你不要来了。", "t": [13212, 19975]}, {"ru": "Он расхохотался, а потом снова стал серьезным.", "zh": "” “我不会离开你的。", "t": [19975, 23938]}, {"ru": "— Этой ночью… знаешь… ты лучше не приходи.", "zh": "” “我会很难看的……会像个死人，别来看我的死了的样子，没有必要。", "t": [23938, 28050]}, {"ru": "— Я тебя не оставлю.", "zh": "” “我会很难看的……会像个死人，别来看我的死了的样子，没有必要。", "t": [28050, 30338]}, {"ru": "— Тебе будет казаться, что мне очень плохо.", "zh": "” “我不会离开你的。", "t": [30338, 33712]}, {"ru": "У меня будет такой вид, словно я умираю.", "zh": "” 他露出忧心忡忡的神色。", "t": [33712, 37488]}, {"ru": "Так уж бывает…Тебе не надо это видеть, не стоит…", "zh": "” 他露出忧心忡忡的神色。", "t": [37488, 40862]}, {"ru": "— Я тебя не оставлю.", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [40862, 42862]}, {"ru": "Маленький принц казался всерьез обеспокоенным.", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [42862, 46712]}, {"ru": "— Я тебе это говорю… из-за змеи…", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [46712, 50038]}, {"ru": "Вдруг она укусит и тебя.", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [50038, 52875]}, {"ru": "Змеи… они злые.", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [52875, 55612]}, {"ru": "Могут укусить ведь и просто так… без причины…", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [55612, 58800]}, {"ru": "— Я тебя не оставлю!", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [58800, 60738]}, {"ru": "Однако что-то его успокоило.", "zh": "他是悄悄走的。", "t": [60738, 63525]}, {"ru": "— Впрочем, верно!", "zh": "他是悄悄走的。", "t": [63525, 65788]}, {"ru": "У нее просто не хватит яда для второго укуса…", "zh": "我终于赶上他。", "t": [65788, 69488]}, {"ru": "Этой ночью я не видел, как он ушел.", "zh": "他大步走着，步子迈得又大又坚决。", "t": [69488, 72588]}, {"ru": "Он исчез незаметно.", "zh": "他见了我，只说了一句：“呀，你在这儿……” 他牵住我的手。", "t": [72588, 75000]}, {"ru": "Когда мне удалось его догнать, он быстро и решительно шел вперед.", "zh": "他见了我，只说了一句：“呀，你在这儿……” 他牵住我的手。", "t": [75000, 79738]}, {"ru": "Увидав меня, он лишь сказал: — А… ты здесь…", "zh": "然后他苦恼地说： “你不该来的。", "t": [79738, 83775]}, {"ru": "Все еще полный тревоги, он взял меня за руку.", "zh": "你会难过的。", "t": [83775, 87575]}, {"ru": "— Зря это ты…Тебе будет тяжело это видеть.", "zh": "我会像个死人，其实我不是真死……” 我不做声。", "t": [87575, 91338]}, {"ru": "Я буду выглядеть мертвым, но это не совсем так…", "zh": "“你知道吧，路途太远，我拖不动这副皮囊，它太沉了。", "t": [91338, 95175]}, {"ru": "Я молчал.", "zh": "“你知道吧，路途太远，我拖不动这副皮囊，它太沉了。", "t": [95175, 96188]}]}, {"id": "ch26p06", "audio": true, "sents": [{"ru": "— Пойми — мой дом слишком далеко для этого тела.", "zh": "” 我不做声。", "t": [100, 3738]}, {"ru": "Оно слишком тяжелое, мне его не унести…", "zh": "“也不过如同蜕了旧壳，一副旧壳不值得悲哀……” 我还是不做声。", "t": [3738, 7188]}, {"ru": "Я молчал.", "zh": "“也不过如同蜕了旧壳，一副旧壳不值得悲哀……” 我还是不做声。", "t": [7188, 9100]}, {"ru": "— Это будет похоже на старую сброшенную оболочку.", "zh": "他有点泄气了，但还在竭力安慰我： “你知道，想起你，我的心会温暖的。", "t": [9100, 13012]}, {"ru": "Старые оболочки покидать не грустно…", "zh": "他有点泄气了，但还在竭力安慰我： “你知道，想起你，我的心会温暖的。", "t": [13012, 16325]}, {"ru": "Я молчал.", "zh": "他有点泄气了，但还在竭力安慰我： “你知道，想起你，我的心会温暖的。", "t": [16325, 18238]}, {"ru": "Он немного пал духом, но все же сделал еще одну попытку.", "zh": "他有点泄气了，但还在竭力安慰我： “你知道，想起你，我的心会温暖的。", "t": [18238, 22488]}, {"ru": "— Знаешь, это будет славно!", "zh": "以后我也会仰望星空，所有的星星会成了带有生锈辘轳的井，所有的星星给我倒水喝……” 我还是不做声。", "t": [22488, 25400]}, {"ru": "Я тоже буду смотреть на звезды.", "zh": "以后我也会仰望星空，所有的星星会成了带有生锈辘轳的井，所有的星星给我倒水喝……” 我还是不做声。", "t": [25400, 28312]}, {"ru": "И все они будут словно колодцы с проржавелыми вóротами.", "zh": "“那会是多有趣的事情！", "t": [28312, 32388]}, {"ru": "И все звезды дадут мне напиться.", "zh": "“那会是多有趣的事情！", "t": [32388, 35450]}, {"ru": "Я молчал.", "zh": "“那会是多有趣的事情！", "t": [35450, 37362]}, {"ru": "— Это будет так забавно!", "zh": "你会有五亿个小铃铛，我有五亿口井……” 他也不做声了，因为他哭了…… “就在这儿吧。", "t": [37362, 39838]}, {"ru": "У тебя будет пятьсот миллионов бубенцов, а у меня — пятьсот миллионов источников.", "zh": "你会有五亿个小铃铛，我有五亿口井……” 他也不做声了，因为他哭了…… “就在这儿吧。", "t": [39838, 45575]}, {"ru": "И он тоже замолчал, потому что заплакал.", "zh": "你让我独自走一步。", "t": [45575, 48050]}]}, {"id": "ch26p07", "audio": true, "sents": [{"ru": "— Это здесь.", "zh": "” 他坐了下来，因为他害怕了。", "t": [100, 1888]}, {"ru": "Позволь мне сделать последний шаг одному.", "zh": "他还说： “你知道……我的花……我要对她负责！", "t": [1888, 5162]}, {"ru": "Он присел на песок.", "zh": "他还说： “你知道……我的花……我要对她负责！", "t": [5162, 7525]}, {"ru": "Ему было страшно.", "zh": "她弱不禁风！", "t": [7525, 9875]}, {"ru": "Потом он добавил: — Ты знаешь… мой цветок… моя красавица…", "zh": "她聪明纯洁！", "t": [9875, 14825]}, {"ru": "Она такая слабая, такая наивная!", "zh": "只凭四根刺保护自己，抵御世上的侵害……” 我瘫坐在地上。", "t": [14825, 18325]}, {"ru": "У нее всего четыре шипа для защиты от всего мира…", "zh": "只凭四根刺保护自己，抵御世上的侵害……” 我瘫坐在地上。", "t": [18325, 22362]}, {"ru": "Я сел на песок.", "zh": "因为我站不住了。", "t": [22362, 24700]}, {"ru": "Ноги меня не держали.", "zh": "因为我站不住了。", "t": [24700, 27088]}, {"ru": "— Ну, вот и все…", "zh": "他说： “我的话……讲完了……” 他还犹豫了片刻，然后站起来，向前走了一步。", "t": [27088, 29238]}, {"ru": "Он немного помедлил, потом поднялся и сделал шаг вперед.", "zh": "他说： “我的话……讲完了……” 他还犹豫了片刻，然后站起来，向前走了一步。", "t": [29238, 33700]}, {"ru": "У меня не было сил шевельнуться.", "zh": "而我不能动弹。", "t": [33700, 36612]}, {"ru": "И я заметил маленькую желтую молнию, промелькнувшую у его ноги.", "zh": "他的脚踝边闪了一道黄光。", "t": [36612, 41688]}, {"ru": "Секунду он стоял неподвижно, а потом беззвучно и медленно, как срубленное дерево, опустился на песок, скрывший звук его падения.", "zh": "好一会儿之后，他像大树倒地似的倒下。", "t": [41688, 49663]}]}]}, {"id": "ch27", "title_ru": "Глава 27", "title_zh": "第 27 章", "paras": [{"id": "ch27p00", "audio": true, "sents": [{"ru": "С тех пор прошло уже шесть лет.", "zh": "当然，这已是六年前的事了……我从来没对别人讲过这个故事。", "t": [100, 3175]}, {"ru": "Я еще никому не рассказывал эту историю.", "zh": "当然，这已是六年前的事了……我从来没对别人讲过这个故事。", "t": [3175, 6700]}, {"ru": "Мои знакомые, увидав меня вновь, были рады, что я жив и здоров.", "zh": "我的同事们看见我活着回来，都替我庆幸。", "t": [6700, 12100]}, {"ru": "А я грустил, но говорил им, что просто устал.", "zh": "我神色哀伤，但我告诉他们：“这是因为累……” 现在，我的离愁别绪已经减轻了一些。", "t": [12100, 15900]}, {"ru": "Теперь я успокоился.", "zh": "我神色哀伤，但我告诉他们：“这是因为累……” 现在，我的离愁别绪已经减轻了一些。", "t": [15900, 18325]}, {"ru": "Ну, конечно, не совсем…", "zh": "我神色哀伤，但我告诉他们：“这是因为累……” 现在，我的离愁别绪已经减轻了一些。", "t": [18325, 21200]}, {"ru": "Я уверен, что он вернулся на свою планету.", "zh": "也就是说……还没有完全消除。", "t": [21200, 24812]}, {"ru": "Ведь в то утро, на рассвете, я не нашел его тела.", "zh": "也就是说……还没有完全消除。", "t": [24812, 28738]}, {"ru": "Возможно, оно было не таким уж и тяжелым…", "zh": "我很明白，他回他的星球去了，因为天亮时我没找到他的尸体。", "t": [28738, 32312]}, {"ru": "Теперь я люблю по ночам слушать звезды.", "zh": "我很明白，他回他的星球去了，因为天亮时我没找到他的尸体。", "t": [32312, 35488]}, {"ru": "Они звенят для меня, как пятьсот миллионов бубенцов.", "zh": "他的躯体并不沉重……我喜欢在夜里倾听星星的呢喃，它们就像五亿个小铃铛…… 可是出了非同寻常的事了：我给小王子画了口罩，但我忘了给口罩配上皮带！", "t": [35488, 39738]}, {"ru": "Но вот что удивительно.", "zh": "他的躯体并不沉重……我喜欢在夜里倾听星星的呢喃，它们就像五亿个小铃铛…… 可是出了非同寻常的事了：我给小王子画了口罩，但我忘了给口罩配上皮带！", "t": [39738, 42262]}, {"ru": "Я нарисовал намордник и отдал этот рисунок маленькому принцу.", "zh": "他的躯体并不沉重……我喜欢在夜里倾听星星的呢喃，它们就像五亿个小铃铛…… 可是出了非同寻常的事了：我给小王子画了口罩，但我忘了给口罩配上皮带！", "t": [42262, 47100]}, {"ru": "Однако я забыл пририсовать к наморднику кожаный ремешок.", "zh": "他别想把口罩套上羊嘴了。", "t": [47100, 51362]}, {"ru": "Как же он сможет тогда надеть намордник на барашка?", "zh": "我于是想：“他的星球发生了什么事呢？", "t": [51362, 55062]}, {"ru": "Поэтому я порой волнуюсь — как он там, на своей планете?", "zh": "绵羊很可能吃了花儿……” 有时我又想：“一定不会的！", "t": [55062, 59488]}, {"ru": "Быть может, барашек все-таки съел цветок?", "zh": "绵羊很可能吃了花儿……” 有时我又想：“一定不会的！", "t": [59488, 63138]}, {"ru": "Но тогда я успокаиваю себя — конечно же, нет!", "zh": "小王子每天夜里把他的花儿罩在玻璃罩里，他一定会看管好他的绵羊……”于是我放心了，天上所有的星星都温和地微笑。", "t": [63138, 67138]}, {"ru": "Ведь каждую ночь маленький принц накрывает свой цветок стеклянным колпаком и внимательно следит за своим барашком.", "zh": "小王子每天夜里把他的花儿罩在玻璃罩里，他一定会看管好他的绵羊……”于是我放心了，天上所有的星星都温和地微笑。", "t": [67138, 74050]}, {"ru": "Тогда я успокаиваюсь, и все звезды тихонько смеются.", "zh": "有时我想：“人总免不了有疏忽大意的时候，这就够糟的了！", "t": [74050, 78400]}, {"ru": "Однако порой я думаю — стоит один раз зазеваться, и этого будет достаточно!", "zh": "要是有天晚上他忘了给花罩上玻璃罩，或者绵羊在夜里悄悄地溜出来呢……”于是，铃铛全变成了泪珠…… 这件事始终是无法解开的谜。", "t": [78400, 83975]}, {"ru": "А что если однажды вечером он забудет про колпак, или же барашек тихонько уйдет ночью?", "zh": "要是有天晚上他忘了给花罩上玻璃罩，或者绵羊在夜里悄悄地溜出来呢……”于是，铃铛全变成了泪珠…… 这件事始终是无法解开的谜。", "t": [83975, 89938]}, {"ru": "В такие ночи все бубенцы плачут…", "zh": "要是有天晚上他忘了给花罩上玻璃罩，或者绵羊在夜里悄悄地溜出来呢……”于是，铃铛全变成了泪珠…… 这件事始终是无法解开的谜。", "t": [89938, 93112]}, {"ru": "В этом скрыта великая тайна.", "zh": "在宇宙中不知哪个角落，我们不认识的绵羊有没有吃掉一朵玫瑰花，你们——喜爱小王子的人，和我一样，看法绝不相同…… 请你们仰望星空吧。", "t": [93112, 95950]}, {"ru": "Ведь для вас, как и я, всем сердцем полюбивших маленького принца, ничто", "zh": "在宇宙中不知哪个角落，我们不认识的绵羊有没有吃掉一朵玫瑰花，你们——喜爱小王子的人，和我一样，看法绝不相同…… 请你们仰望星空吧。", "t": [95950, 100525]}]}, {"id": "ch27p01", "audio": true, "sents": [{"ru": "во вселенной не будет уже прежним, если где-то там барашек, которого вы даже не видели, уже съел его розу.", "zh": "请你们问问自己：绵羊有没有吃掉花儿？", "t": [100, 7075]}, {"ru": "Посмотрите на небо и задайте себе вопрос — это уже случилось или еще нет?", "zh": "你们就会看到，天上所有的星星发生了变化…… 没有一个大人明白，弄清楚这个问题有多重要！", "t": [7075, 12475]}, {"ru": "И вы увидите, как все меняется кругом от ответа на этот вопрос.", "zh": "你们就会看到，天上所有的星星发生了变化…… 没有一个大人明白，弄清楚这个问题有多重要！", "t": [12475, 17062]}, {"ru": "Ни один взрослый не поймет, насколько это важно!", "zh": "我认为这幅图画是世界上最凄美的图画了。", "t": [17062, 20888]}, {"ru": "На этом рисунке для меня изображен самый прекрасный и в то же время самый грустный пейзаж на свете.", "zh": "我再一次画它，是为了让你们好好地看看它。", "t": [20888, 27012]}, {"ru": "Это тот же самый пейзаж, что и на предыдущей странице.", "zh": "小王子就是在这里出现在地球上的，然后又是从这里离开了地球。", "t": [27012, 31325]}, {"ru": "Я нарисовал его еще раз, чтобы вы могли его получше рассмотреть.", "zh": "请你们仔细看清楚这幅画，有朝一日你们到沙漠，到非洲旅行，才能认出这地方来。", "t": [31325, 36100]}, {"ru": "Именно здесь маленький принц появился на Земле, а потом исчез.", "zh": "请你们仔细看清楚这幅画，有朝一日你们到沙漠，到非洲旅行，才能认出这地方来。", "t": [36100, 40900]}, {"ru": "Посмотрите на этот вид внимательно.", "zh": "如果你经过这个地方，我恳求你们，别匆忙离去，请在那颗星下稍待片刻！", "t": [40900, 43988]}, {"ru": "Просто для того, чтобы наверняка узнать его, если вы окажетесь", "zh": "如果你经过这个地方，我恳求你们，别匆忙离去，请在那颗星下稍待片刻！", "t": [43988, 47662]}]}, {"id": "ch27p02", "audio": true, "sents": [{"ru": "однажды в африканской пустыне.", "zh": "如果有个孩子向你走过来；如果他笑吟吟的；如果他长着一头金发；如果你向他提问题，他不回答；你们就会猜到他是谁了。", "t": [100, 3000]}, {"ru": "И если вы окажетесь именно тут, прошу вас, не спешите.", "zh": "如果有个孩子向你走过来；如果他笑吟吟的；如果他长着一头金发；如果你向他提问题，他不回答；你们就会猜到他是谁了。", "t": [3000, 7712]}, {"ru": "Постойте немного, прямо здесь, под звездой!", "zh": "如果有个孩子向你走过来；如果他笑吟吟的；如果他长着一头金发；如果你向他提问题，他不回答；你们就会猜到他是谁了。", "t": [7712, 11412]}, {"ru": "И если к вам подойдет малыш и засмеется, если волосы у него будут золотистые, и он не будет отвечать на ваши вопросы, вы узнаете, кто это.", "zh": "果真如此，请你们行行好！", "t": [11412, 20200]}, {"ru": "Тогда будьте так добры — не заставляйте меня больше грустить и скорее напишите, что он вернулся…", "zh": "别眼睁睁看着我为思念他而悲伤，别坐视不理，别无动于衷：请你们快点写信告诉我，他回来了…… 【注释】 [1] 美国的一个州。", "t": [20200, 25412]}]}]}]}